/* Grammar chapters — one entry per topic-level. Each teaches a rule end to
   end: Lesson, Recognise, Drills, Write it, Apply. Built from the spec in
   docs/grammar-spec.md; the backlog of further topics is in
   docs/grammar-roadmap.md. */
"use strict";

const GRAMMAR_ORDER = ["gender", "articles", "pronouns", "relative", "connectors"];

const GRAMMAR_TOPICS = {
  "gender-A2": {"slug": "gender", "level": "A2", "title": "Le genre et le pluriel des noms", "summary": "How to guess a noun's gender from its ending, the exceptions that catch everyone, and how French really marks the plural.", "why": "Gender is the error that multiplies. Get « la » wrong once and the adjective, the pronoun and the past participle after it are all wrong too. You already know most of these words; this chapter is what makes them safe to write in an EPSO test or in a note to your head of unit.", "lesson": [{"id": "gl-gender-A2-01", "heading": "Gender is data, not logic", "body": "Every French noun is masculine or feminine, and the gender is part of the word exactly as its spelling is. There is nothing feminine about a table (la table) and nothing masculine about a problem (le problème). The mistake English speakers make is treating gender as a decoration you can add later — but it leaks into everything that follows: the article, every adjective, every pronoun, the past participle. One wrong gender makes four wrong words. So never learn « bureau »; learn « un bureau ». Be especially careful with nouns starting with a vowel or a silent h, because « l' » hides the gender completely: learn those with un / une.", "examples": [{"fr": "Je vous envoie l'adresse de la salle de réunion.", "en": "I'm sending you the address of the meeting room.", "gloss": {"adresse": "address", "salle": "room"}, "note": "« Adresse » is feminine — « une adresse » — but « l' » never shows it. Store it as « une adresse »."}, {"fr": "Il travaille dans un immeuble de la rue de la Loi.", "en": "He works in an office block on rue de la Loi.", "gloss": {"immeuble": "office block / building"}, "note": "Masculine: « un immeuble ». Said as « l'immeuble » you would never know."}, {"fr": "Le problème, c'est le délai.", "en": "The problem is the deadline.", "gloss": {"délai": "deadline / time limit"}, "note": "« Problème » ends in -e, which English speakers read as feminine. It is masculine."}]}, {"id": "gl-gender-A2-02", "heading": "Endings that mean feminine", "body": "About four nouns in five can be guessed from the last few letters, and these are the endings worth learning first because they cover most office and administrative vocabulary. Learn the ending together with its exception in the same breath — a rule you later discover was false does more damage than no rule.", "table": {"cols": ["Ending", "Examples", "Watch out"], "rows": [["-tion / -sion", "la réunion, la décision, la Commission", "Reliable. No exception you will meet."], ["-té", "la sécurité, la qualité, la difficulté", "le côté, l'été, le comité, le traité, le député are masculine"], ["-ette", "la baguette, la chaussette, l'aubette (BE)", "le squelette is the odd one out"], ["-ance / -ence", "la connaissance, l'expérience, l'agence", "le silence is masculine"], ["-ure", "la signature, la lecture, la voiture", "le murmure is masculine"], ["-ie", "la boulangerie, la friterie (BE), la sortie", "le parapluie and un incendie are masculine"]]}, "examples": [{"fr": "La réunion de service commence à neuf heures.", "en": "The team meeting starts at nine.", "gloss": {"réunion": "meeting"}, "note": "-tion is the safest ending in the language: always feminine."}, {"fr": "Il faut la signature du chef d'unité avant vendredi.", "en": "You need the head of unit's signature before Friday.", "gloss": {"signature": "signature", "chef": "head"}, "note": "-ure: feminine. Also « la lecture », « la nature », « la culture »."}, {"fr": "J'attends le 71 sous l'aubette.", "en": "I'm waiting for the 71 in the bus shelter.", "gloss": {"aubette": "bus shelter (Belgian)"}, "note": "Belgian French: « une aubette » is a bus shelter; in France it is « un abribus », masculine. The -ette tells you the Belgian word is feminine."}]}, {"id": "gl-gender-A2-03", "heading": "Endings that mean masculine", "body": "The masculine endings are just as usable, and two of them cause almost all the errors: -age, because « la page » and « la plage » look identical to « le stage »; and -eau, because « l'eau » is feminine. Note also that a final -e proves nothing. « Le problème », « le système », « le programme » and « le silence » all end in -e and are all masculine; the -e rule you may have been taught at A1 is only about adjectives.", "table": {"cols": ["Ending", "Examples", "Watch out"], "rows": [["-ment", "le paiement, le bâtiment, le règlement", "la jument (mare) is the only common exception"], ["-age", "le stage, le message, le voyage", "la page, la plage, l'image, la cage are feminine"], ["-eau", "le bureau, le tableau, le niveau", "l'eau and la peau are feminine"], ["-isme", "le tourisme, l'organisme, le mécanisme", "No exceptions."], ["-oir", "le couloir, le trottoir, le devoir", "-oire is mixed: le laboratoire but la mémoire, l'histoire"], ["-ème", "le problème, le système, le thème", "le programme and le diplôme are masculine too, despite the -e"]]}, "examples": [{"fr": "Le paiement par Bancontact n'a pas fonctionné.", "en": "The Bancontact payment didn't go through.", "gloss": {"paiement": "payment"}, "note": "-ment: masculine. Bancontact is the Belgian card system — « la carte bleue » is French, not Belgian."}, {"fr": "Mon stage à la Commission dure cinq mois.", "en": "My traineeship at the Commission lasts five months.", "gloss": {"stage": "traineeship / internship"}, "note": "-age: masculine. But « la page » and « la plage » are feminine — those two you simply memorise."}, {"fr": "Cet organisme s'occupe des pensions.", "en": "This body deals with pensions.", "gloss": {"organisme": "body / organisation"}, "note": "-isme: masculine, with no exceptions. Before a vowel the masculine « ce » becomes « cet », not « cette »."}]}, {"id": "gl-gender-A2-04", "heading": "The exceptions you will actually meet", "body": "A short list is worth more than a long one. These are the words that break the endings above and that you will use in a normal Brussels week. Learn them as a block, because each one will otherwise trip you every time it appears.", "table": {"cols": ["Word", "Gender", "Why it catches you"], "rows": [["le musée, le lycée", "masculine", "-ée is normally feminine: la journée, l'année, la soirée"], ["la page, la plage, l'image", "feminine", "-age is normally masculine: le stage, le message"], ["l'eau, la peau", "feminine", "-eau is normally masculine: le bureau, le tableau"], ["le problème, le système", "masculine", "the final -e looks feminine to an English eye"], ["la fin, la main", "feminine", "-in words are usually masculine: le matin, le jardin, le vin"], ["le GSM (BE)", "masculine", "Belgian for a mobile phone; in France « le portable »"], ["un chicon (BE)", "masculine", "Belgian for chicory; in France « une endive », feminine"]]}, "examples": [{"fr": "L'eau du robinet est bonne à Bruxelles.", "en": "The tap water is good in Brussels.", "gloss": {"robinet": "tap"}, "note": "« Bonne », not « bon » — l'eau is feminine even though it ends in -eau."}, {"fr": "Le musée Magritte est fermé le lundi.", "en": "The Magritte Museum is closed on Mondays.", "gloss": {"fermé": "closed"}, "note": "Masculine, against the -ée pattern. Same for « le lycée »."}, {"fr": "Ouvrez le rapport à la page 12.", "en": "Open the report at page 12.", "gloss": {"page": "page"}, "note": "Feminine, against the -age pattern."}, {"fr": "Je n'ai plus de batterie sur mon GSM.", "en": "My mobile is out of battery.", "gloss": {"GSM": "mobile phone (Belgian)"}, "note": "In Belgium the phone is « le GSM », masculine. Say « portable » in Paris and « GSM » in Brussels and you will be understood both times."}]}, {"id": "gl-gender-A2-05", "heading": "The plural: you write it, you don't hear it", "body": "The regular plural adds -s, and that -s is silent. « Le document » and « les documents » sound different only because of the article: /lə/ against /le/. This is the trap for English speakers, who listen for the noun and hear nothing, then leave the -s out in writing. In speech the article carries the whole plural; in writing you must still put the -s on the noun, and on every adjective with it. Two endings are irregular even at this level: -eau and -eu add -x instead of -s (le bureau → les bureaux, le jeu → les jeux). Nouns in -al and -ail change more radically, and you will meet those at B1.", "table": {"cols": ["Singular", "Plural", "Rule"], "rows": [["le document", "les documents", "add -s (silent)"], ["la réunion", "les réunions", "add -s (silent)"], ["le bureau", "les bureaux", "-eau adds -x, never -s"], ["le jeu", "les jeux", "-eu adds -x"], ["le journal", "les journaux", "-al becomes -aux — see the B1 chapter"]]}, "examples": [{"fr": "Les documents sont sur le bureau de Sophie.", "en": "The documents are on Sophie's desk.", "gloss": {"documents": "documents"}, "note": "Only « les » is audible. The -s is written and silent."}, {"fr": "J'ai deux réunions demain matin.", "en": "I have two meetings tomorrow morning.", "gloss": {"réunions": "meetings"}, "note": "« Deux » already says plural, but the -s is still required in writing. Leaving it out is the single most common written error at A2."}, {"fr": "Les bureaux du service sont au troisième étage.", "en": "The department's offices are on the third floor.", "gloss": {"bureaux": "offices", "étage": "floor"}, "note": "« Les bureaus » does not exist: -eau takes -x."}]}, {"id": "gl-gender-A2-06", "heading": "Nouns in -s, -x or -z never change", "body": "If the singular already ends in -s, -x or -z, the plural adds nothing at all. English speakers add an -s anyway and write « les prixs », which looks as wrong to a French reader as « the pricess » looks to you. Here again only the article moves, and in speech nothing moves at all: « le bus » and « les bus » differ by one vowel and nothing else, so context does the work.", "table": {"cols": ["Singular", "Plural"], "rows": [["le prix", "les prix"], ["le pays", "les pays"], ["le bus", "les bus"], ["le choix", "les choix"], ["la voix", "les voix"], ["le nez", "les nez"]]}, "examples": [{"fr": "Les prix ont augmenté chez Delhaize.", "en": "Prices have gone up at Delhaize.", "gloss": {"prix": "price(s)", "augmenté": "gone up"}, "note": "Identical in the singular and the plural. « Les prixs » is never correct."}, {"fr": "Tous les bus de la STIB passent par là.", "en": "All the STIB buses go past there.", "gloss": {"bus": "bus(es)"}, "note": "« Les bus », never « les buss ». STIB/MIVB is the Brussels transport operator."}, {"fr": "Nous avons deux choix possibles.", "en": "We have two possible options.", "gloss": {"choix": "choice(s)"}, "note": "The adjective still agrees — « possibles » with an -s — even though the noun does not change."}]}], "recognise": [{"id": "gr-gender-A2-01", "level": "A2", "format": "cloze", "q": "___ réunion de service commence à neuf heures.", "options": ["La", "Le", "Les", "L'"], "a": 0, "trap": "Le — English has no gender, so learners default to masculine", "expl": "Nouns in -tion are feminine without exception: la réunion, la décision, la Commission."}, {"id": "gr-gender-A2-02", "level": "A2", "format": "cloze", "q": "Il faut signer ___ document avant vendredi.", "options": ["le", "la", "les", "l'"], "a": 0, "trap": "la — « document » ends in a nasal vowel that sounds like nothing in English, so learners guess", "expl": "-ment is masculine: le document, le paiement, le bâtiment, le règlement. The only common exception is « la jument », a mare."}, {"id": "gr-gender-A2-03", "level": "A2", "format": "cloze", "q": "___ sécurité du bâtiment est contrôlée chaque mois.", "options": ["La", "Le", "L'", "Les"], "a": 0, "trap": "Le — the noun is abstract, and learners default to masculine for abstractions", "expl": "-té is feminine: la sécurité, la qualité, la difficulté. Watch the masculine exceptions: le côté, l'été, le comité, le traité."}, {"id": "gr-gender-A2-04", "level": "A2", "format": "cloze", "q": "Nous attendons ___ signature du chef d'unité.", "options": ["la", "le", "les", "l'"], "a": 0, "trap": "le — abstract office nouns feel masculine to an English speaker", "expl": "-ure is feminine: la signature, la lecture, la voiture, la nature. « Le murmure » is the exception nobody needs."}, {"id": "gr-gender-A2-05", "level": "A2", "format": "cloze", "q": "Je prends ___ bus 71 pour aller au bureau.", "options": ["le", "la", "l'", "les"], "a": 0, "trap": "la — « la ligne 71 » and « la station » are feminine, and learners carry that gender over to the vehicle", "expl": "The vehicles are masculine — le bus, le tram, le métro — while the network words are feminine: la ligne, la station, la correspondance."}, {"id": "gr-gender-A2-06", "level": "A2", "format": "cloze", "q": "L'eau du robinet est ___ à Bruxelles.", "options": ["bonne", "bon", "bons", "bonnes"], "a": 0, "trap": "bon — « eau » ends in -eau, which is otherwise masculine (le bureau, le tableau)", "expl": "« L'eau » is feminine, so the adjective is « bonne ». L'eau and la peau are the two everyday exceptions to -eau."}, {"id": "gr-gender-A2-07", "level": "A2", "format": "cloze", "q": "___ documents sont déjà sur votre bureau.", "options": ["Les", "Le", "La", "L'"], "a": 0, "trap": "Le — the -s of « documents » is silent, so nothing in the noun forces the plural", "expl": "In speech the article is the only audible marker of the plural. « Le document » and « les documents » differ only in that first word."}, {"id": "gr-gender-A2-08", "level": "A2", "format": "collocation", "q": "Which plural is correct? — le prix", "options": ["les prix", "les prixs", "les prixes", "le prix"], "a": 0, "trap": "les prixs — the English reflex of adding -s to everything", "expl": "A noun already ending in -s, -x or -z adds nothing: le prix → les prix, le pays → les pays, le nez → les nez."}, {"id": "gr-gender-A2-09", "level": "A2", "format": "cloze", "q": "Ouvrez le rapport à ___ page 12.", "options": ["la", "le", "l'", "les"], "a": 0, "trap": "le — -age is normally masculine (le stage, le message, le voyage)", "expl": "« La page » is one of the four -age words that are feminine: la page, la plage, l'image, la cage."}, {"id": "gr-gender-A2-10", "level": "A2", "format": "cloze", "q": "___ musée Magritte est fermé le lundi.", "options": ["Le", "La", "L'", "Les"], "a": 0, "trap": "La — -ée is normally feminine (la journée, l'année, la soirée)", "expl": "« Le musée » and « le lycée » are masculine, against the -ée pattern. Learn them as a pair."}], "drills": [{"id": "gd-gender-A2-01", "level": "A2", "format": "cloze", "q": "___ assurance couvre aussi le vélo.", "options": ["Cette", "Cet", "Ce", "Ces"], "a": 0, "trap": "Cet — the right shape before a vowel, but only for masculine nouns", "expl": "-ance is feminine, so « cette assurance ». « Cet » is the masculine form used before a vowel (cet organisme, cet immeuble)."}, {"id": "gd-gender-A2-02", "level": "A2", "format": "cloze", "q": "La ___ page du rapport manque.", "options": ["dernière", "dernier", "derniers", "dernières"], "a": 0, "trap": "dernier — learners apply the masculine -age rule and forget « la page » is an exception", "expl": "« La page » is feminine, so the adjective is « dernière ». Compare « le dernier message », masculine."}, {"id": "gd-gender-A2-03", "level": "A2", "format": "collocation", "q": "Which plural is correct? — le bureau", "options": ["les bureaux", "les bureaus", "les bureau", "le bureaux"], "a": 0, "trap": "les bureaus — the English -s plural, which is what learners write nine times out of ten", "expl": "Nouns in -eau take -x: le bureau → les bureaux, le tableau → les tableaux, le niveau → les niveaux."}, {"id": "gd-gender-A2-04", "level": "A2", "format": "collocation", "q": "Which plural is correct? — le pays", "options": ["les pays", "les payss", "les payes", "le pays"], "a": 0, "trap": "les payes — « la paye » is a real word (wages), so the form looks plausible", "expl": "« Pays » already ends in -s, so nothing is added. Only the article changes: le pays → les pays."}, {"id": "gd-gender-A2-05", "level": "A2", "format": "cloze", "q": "L'adresse que vous m'avez donnée est ___.", "options": ["correcte", "correct", "corrects", "correctes"], "a": 0, "trap": "correct — « l'adresse » hides its gender behind the elided article, so learners default to masculine", "expl": "« Une adresse » is feminine, so « correcte » with an -e. This is exactly why you learn vowel-initial nouns with un/une."}, {"id": "gd-gender-A2-06", "level": "A2", "format": "cloze", "q": "___ organisme s'occupe des pensions en Belgique.", "options": ["Cet", "Cette", "Ce", "Ces"], "a": 0, "trap": "Cette — the noun starts with a vowel, so learners reach for the feminine form", "expl": "-isme is masculine with no exceptions. Before a vowel the masculine « ce » becomes « cet »: cet organisme, cet immeuble."}, {"id": "gd-gender-A2-07", "level": "A2", "format": "cloze", "q": "Cette crème protège ___ peau du soleil.", "options": ["la", "le", "l'", "les"], "a": 0, "trap": "le — -eau is otherwise masculine (le bureau, le manteau, le cadeau)", "expl": "« La peau » and « l'eau » are the two feminine -eau nouns. Everything else in -eau is masculine."}, {"id": "gd-gender-A2-08", "level": "A2", "format": "cloze", "q": "___ problème principal, c'est le délai.", "options": ["Le", "La", "Les", "L'"], "a": 0, "trap": "La — the final -e reads as feminine to an English eye", "expl": "Nouns in -ème are masculine: le problème, le système, le thème. So are le programme and le diplôme. A final -e proves nothing about a noun."}, {"id": "gd-gender-A2-09", "level": "A2", "format": "cloze", "q": "J'ai acheté ___ baguette à la boulangerie de la place.", "options": ["une", "un", "des", "de"], "a": 0, "trap": "un — English « a » carries no gender, so it is a coin toss unless you know the ending", "expl": "-ette is feminine: une baguette, une chaussette, une aubette. « Le squelette » is the only exception worth knowing."}, {"id": "gd-gender-A2-10", "level": "A2", "format": "collocation", "q": "Which pairing is correct?", "options": ["le stage / la plage", "la stage / le plage", "le stage / le plage", "la stage / la plage"], "a": 0, "trap": "le stage / le plage — the -age rule applied to both, which is the natural but wrong move", "expl": "-age is masculine as a rule (le stage, le message, le voyage), but la page, la plage, l'image and la cage are feminine."}, {"id": "gd-gender-A2-11", "level": "A2", "format": "cloze", "q": "___ lycée français de Bruxelles se trouve à Uccle.", "options": ["Le", "La", "L'", "Les"], "a": 0, "trap": "La — -ée is usually feminine, as in la journée, l'année, la soirée", "expl": "« Le lycée » and « le musée » break the -ée pattern and are masculine."}, {"id": "gd-gender-A2-12", "level": "A2", "format": "collocation", "q": "Which plural is correct? — le choix", "options": ["les choix", "les choixs", "les choixes", "le choix"], "a": 0, "trap": "le choix — spelt identically, so only the article shows whether it is one option or several", "expl": "Nouns in -x are invariable: le choix → les choix, la voix → les voix. The article is the whole plural."}, {"id": "gd-gender-A2-13", "level": "A2", "format": "cloze", "q": "Il m'attend dans ___ couloir du deuxième étage.", "options": ["le", "la", "l'", "les"], "a": 0, "trap": "la — French words for rooms and places are often feminine (la salle, la porte, la cuisine), so learners generalise", "expl": "-oir is masculine: le couloir, le trottoir, le miroir, le devoir. Careful with -oire, which is mixed: le laboratoire but la mémoire."}, {"id": "gd-gender-A2-14", "level": "A2", "format": "cloze", "q": "___ nouveaux collègues arrivent lundi.", "options": ["Les", "Le", "La", "L'"], "a": 0, "trap": "Le — the -s of « collègues » is silent, so learners forget the sentence is plural at all", "expl": "The plural is audible in « les » and in « nouveaux », never in the noun itself. Write the -s on the noun anyway."}, {"id": "gd-gender-A2-15", "level": "A2", "format": "cloze", "q": "___ Commission a publié son rapport annuel.", "options": ["La", "Le", "Les", "L'"], "a": 0, "trap": "Le — English « the Commission » gives no clue, and institutions feel masculine by default", "expl": "-ion is feminine, so la Commission, la Direction, la Décision. Compare « le Conseil » and « le Parlement », which are masculine for other reasons."}, {"id": "gd-gender-A2-16", "level": "A2", "format": "cloze", "q": "___ paiement par Bancontact n'a pas fonctionné.", "options": ["Le", "La", "Les", "L'"], "a": 0, "trap": "La — the word ends in a vowel sound, which learners hear as feminine", "expl": "-ment is masculine: le paiement, le bâtiment, le règlement, le gouvernement. Bancontact is the Belgian card system; « la carte bleue » is French, not Belgian."}], "write": [{"id": "gw-gender-A2-01", "prompt": "the meeting (definite article)", "answer": "la réunion", "accept": ["la réunion"], "hint": "-tion", "expl": "Nouns in -tion are feminine: la réunion."}, {"id": "gw-gender-A2-02", "prompt": "the document (definite article)", "answer": "le document", "accept": ["le document"], "hint": "-ment", "expl": "Nouns in -ment are masculine: le document."}, {"id": "gw-gender-A2-03", "prompt": "a bag — what you ask for at the Delhaize checkout (indefinite article)", "answer": "un sac", "accept": ["un sac"], "hint": "masculine", "expl": "« Un sac » is masculine. At the till you say « Je voudrais un sac, s'il vous plaît »."}, {"id": "gw-gender-A2-04", "prompt": "the water (definite article)", "answer": "l'eau", "accept": ["l'eau"], "hint": "the article elides, but the gender is still feminine", "expl": "« L'eau » is feminine — « une eau plate » — even though -eau is otherwise masculine."}, {"id": "gw-gender-A2-05", "prompt": "the museum (definite article)", "answer": "le musée", "accept": ["le musée"], "hint": "-ée, but masculine", "expl": "« Le musée » breaks the -ée pattern, like « le lycée »."}, {"id": "gw-gender-A2-06", "prompt": "the page (definite article)", "answer": "la page", "accept": ["la page"], "hint": "-age, but feminine", "expl": "« La page » is one of the feminine -age nouns, with la plage, l'image and la cage."}, {"id": "gw-gender-A2-07", "prompt": "the prices — plural (definite article)", "answer": "les prix", "accept": ["les prix"], "hint": "already ends in -x", "expl": "Nouns ending in -s, -x or -z do not change: le prix → les prix."}, {"id": "gw-gender-A2-08", "prompt": "the offices — plural (definite article)", "answer": "les bureaux", "accept": ["les bureaux"], "hint": "-eau", "expl": "-eau takes -x in the plural: le bureau → les bureaux."}, {"id": "gw-gender-A2-09", "prompt": "the security / safety (definite article)", "answer": "la sécurité", "accept": ["la sécurité"], "hint": "-té", "expl": "Nouns in -té are feminine: la sécurité, la qualité. Not le côté, l'été, le comité."}, {"id": "gw-gender-A2-10", "prompt": "the building (definite article)", "answer": "le bâtiment", "accept": ["le bâtiment"], "hint": "-ment", "expl": "Masculine: le bâtiment, like le paiement and le règlement."}, {"id": "gw-gender-A2-11", "prompt": "the buses — plural (definite article)", "answer": "les bus", "accept": ["les bus"], "hint": "already ends in -s", "expl": "« Le bus » ends in -s, so the plural adds nothing: les bus."}, {"id": "gw-gender-A2-12", "prompt": "two meetings (with the number)", "answer": "deux réunions", "accept": ["deux réunions"], "hint": "the -s is silent but compulsory", "expl": "The number already says plural, but the written -s on the noun is still required."}], "apply": [{"id": "ga-gender-A2-01", "situation": "You are at the Delhaize checkout and you have no bag.", "task": "Ask for a bag, politely, with the right article.", "accept": ["je voudrais un sac s'il vous plaît", "un sac s'il vous plaît", "je peux avoir un sac s'il vous plaît", "je voudrais un sac", "est-ce que je peux avoir un sac s'il vous plaît", "je prends un sac s'il vous plaît"], "model": "Je voudrais un sac, s'il vous plaît.", "expl": "« Un sac » — masculine. Note that in Belgium the cashier will hand it over saying « s'il vous plaît », which here means « here you go », not « please »."}, {"id": "ga-gender-A2-02", "situation": "You are at the counter of the commune in Ixelles.", "task": "Say that you have an appointment at nine o'clock.", "accept": ["j'ai un rendez-vous à neuf heures", "j'ai rendez-vous à neuf heures", "bonjour j'ai un rendez-vous à neuf heures", "bonjour j'ai rendez-vous à neuf heures", "j'ai un rendez-vous à 9h", "j'ai un rendez-vous à neuf heures ce matin"], "model": "Bonjour, j'ai un rendez-vous à neuf heures.", "expl": "« Un rendez-vous » is masculine. « J'ai rendez-vous » without the article is also standard and slightly more idiomatic."}, {"id": "ga-gender-A2-03", "situation": "You are writing a one-line message to your head of unit.", "task": "Tell her the meeting is postponed to Thursday.", "accept": ["la réunion est reportée à jeudi", "la réunion est reportée à jeudi matin", "la réunion est repoussée à jeudi", "la réunion a été reportée à jeudi", "la réunion est décalée à jeudi", "je vous informe que la réunion est reportée à jeudi"], "model": "La réunion est reportée à jeudi.", "expl": "« La réunion » is feminine, so the participle agrees: « reportée » with an -e."}, {"id": "ga-gender-A2-04", "situation": "You are at a STIB stop in Etterbeek and you are not sure about the route.", "task": "Ask whether the 71 goes to Flagey.", "accept": ["excusez-moi est-ce que le 71 va à flagey", "est-ce que le 71 va à flagey", "est-ce que le bus 71 va à flagey", "le 71 va à flagey", "le bus 71 va bien à flagey", "est-ce que ce bus va à flagey", "pardon est-ce que le 71 va à flagey", "excusez-moi est-ce que le bus 71 va à flagey"], "model": "Excusez-moi, est-ce que le 71 va à Flagey ?", "expl": "« Le bus », « le tram », « le métro » are masculine, so a numbered line is « le 71 », « le 81 »."}, {"id": "ga-gender-A2-05", "situation": "A colleague asks where the department has moved to.", "task": "Say that the offices are on the third floor.", "accept": ["les bureaux sont au troisième étage", "les bureaux sont au 3e étage", "les bureaux se trouvent au troisième étage", "nos bureaux sont au troisième étage", "les bureaux du service sont au troisième étage", "ils sont au troisième étage"], "model": "Les bureaux sont au troisième étage.", "expl": "« Le bureau » → « les bureaux » with -x, and « l'étage » is masculine, hence « au troisième étage »."}, {"id": "ga-gender-A2-06", "situation": "You are in a café near Schuman and the waiter asks what you would like.", "task": "Order a coffee and still water.", "accept": ["un café et une eau plate s'il vous plaît", "je voudrais un café et une eau plate", "un café et de l'eau plate s'il vous plaît", "je prends un café et une eau plate", "un café et une bouteille d'eau plate s'il vous plaît", "je voudrais un café et une eau plate s'il vous plaît"], "model": "Un café et une eau plate, s'il vous plaît.", "expl": "« Un café » is masculine, « une eau » feminine — the -eau exception. « Plate » agrees with « eau », so it takes an -e."}]},
  "gender-B1": {"slug": "gender", "level": "B1", "title": "Le genre et le pluriel des noms", "summary": "The irregular plurals (-al, -ail, -eu, -ou), compound nouns, the words that change meaning with their gender, and how job titles are feminised in Belgium.", "why": "At B1 the gender errors that remain are the expensive ones: writing « les travails » in a note, or « le tour du Midi » when you mean the building. And in Brussels you will address a « bourgmestre », a « cheffe d'unité » and an « échevine » — Belgian administrative French feminises job titles by decree, and getting that wrong in a letter reads as careless.", "lesson": [{"id": "gl-gender-B1-01", "heading": "-al becomes -aux — except when it doesn't", "body": "Nouns ending in -al drop the -al and take -aux: le journal → les journaux. This is not a spelling curiosity, it is a different-sounding word, so an English speaker who writes « les journals » is also saying something no French ear recognises. The exceptions are a small closed list, and they are exactly the sociable words you will use in Brussels: bal, carnaval, festival, récital, régal, chacal. Those simply add -s.", "table": {"cols": ["Singular", "Plural", "Note"], "rows": [["le journal", "les journaux", "regular"], ["le tribunal", "les tribunaux", "regular"], ["le canal", "les canaux", "regular"], ["le total", "les totaux", "regular"], ["le festival", "les festivals", "exception — adds -s"], ["le carnaval", "les carnavals", "exception — adds -s"], ["le bal", "les bals", "exception — adds -s"]]}, "examples": [{"fr": "Tous les journaux belges ont publié le communiqué.", "en": "Every Belgian newspaper published the press release.", "gloss": {"journaux": "newspapers", "communiqué": "press release"}, "note": "Le journal → les journaux. Never « les journals », and never the misspelling « les journeaux »."}, {"fr": "Les tribunaux belges appliquent le règlement européen.", "en": "The Belgian courts apply the European regulation.", "gloss": {"tribunaux": "courts", "règlement": "regulation"}, "note": "Same pattern, and a word you will meet in every legal text."}, {"fr": "Bruxelles accueille plusieurs festivals en été.", "en": "Brussels hosts several festivals in the summer.", "gloss": {"accueille": "hosts", "festivals": "festivals"}, "note": "Exception: festivals, carnavals, bals, récitals all take a plain -s. Couleur Café is « un festival », « des festivals »."}]}, {"id": "gl-gender-B1-02", "heading": "-ail: seven words go to -aux, the rest add -s", "body": "This is the mirror image of the last rule, and learners over-correct here more than anywhere else: having learnt travail → travaux they write « des détaux » for details. Only a closed list of seven -ail nouns takes -aux — bail, corail, émail, soupirail, travail, vantail, vitrail — and of those you will realistically use two: travail and bail. Everything else in -ail is regular: détail → détails, portail → portails, rail → rails, éventail → éventails.", "table": {"cols": ["Singular", "Plural", "Where you meet it"], "rows": [["le travail", "les travaux", "roadworks signs all over Brussels"], ["le bail", "les baux", "the nine-year Belgian lease: un bail de neuf ans"], ["le vitrail", "les vitraux", "churches, museums"], ["le détail", "les détails", "regular -s"], ["le portail", "les portails", "regular -s"], ["le rail", "les rails", "regular -s"]]}, "examples": [{"fr": "Les travaux de la rue Belliard durent depuis deux ans.", "en": "The roadworks on rue Belliard have been going on for two years.", "gloss": {"travaux": "roadworks / works"}, "note": "« Travaux » in the plural means roadworks. « Le travail » in the singular is work in general or a job."}, {"fr": "En Belgique, les baux de résidence principale sont de neuf ans.", "en": "In Belgium, main-residence leases run for nine years.", "gloss": {"baux": "leases"}, "note": "Belgian housing law: the standard lease is « un bail de neuf ans ». The plural « les baux » catches everyone."}, {"fr": "Je vous envoie les détails par mail cet après-midi.", "en": "I'll send you the details by email this afternoon.", "gloss": {"détails": "details"}, "note": "Regular: -ail + s. « Des détaux » does not exist."}]}, {"id": "gl-gender-B1-03", "heading": "-eu, -au, -eau take -x; -ou takes -s, with seven rebels", "body": "Three endings take -x where English expects -s: -eau (bureau → bureaux), -au (tuyau → tuyaux) and -eu (jeu → jeux). Two -eu words refuse: pneu → pneus and bleu → bleus. Nouns in -ou are the opposite: they are regular (trou → trous, clou → clous, sou → sous) apart from a famous list of seven that take -x. The seven are worth memorising as a phrase, because they come up in exams: bijou, caillou, chou, genou, hibou, joujou, pou.", "table": {"cols": ["Ending", "Plural", "Examples", "Exceptions"], "rows": [["-eau", "-eaux", "le bureau → les bureaux", "none"], ["-au", "-aux", "le tuyau → les tuyaux", "le landau → les landaus"], ["-eu", "-eux", "le jeu → les jeux, le cheveu → les cheveux", "le pneu → les pneus, le bleu → les bleus"], ["-ou", "-ous", "le trou → les trous, le clou → les clous", "bijou, caillou, chou, genou, hibou, joujou, pou → -oux"]]}, "examples": [{"fr": "Les feux ne fonctionnent pas au carrefour.", "en": "The traffic lights aren't working at the junction.", "gloss": {"feux": "traffic lights", "carrefour": "junction"}, "note": "Le feu → les feux. In the plural « les feux » is normally the traffic lights."}, {"fr": "J'ai changé les pneus avant l'hiver.", "en": "I changed the tyres before the winter.", "gloss": {"pneus": "tyres"}, "note": "Exception: pneu takes -s. Belgian winter tyres are not compulsory, unlike in Germany."}, {"fr": "Elle a acheté des choux au marché du Châtelain.", "en": "She bought some cabbages at the Châtelain market.", "gloss": {"choux": "cabbages", "marché": "market"}, "note": "Chou is one of the seven -ou nouns taking -x. The Châtelain market in Ixelles runs on Wednesday afternoons."}]}, {"id": "gl-gender-B1-04", "heading": "Compound nouns: only what can be plural becomes plural", "body": "A compound noun pluralises the parts that are nouns or adjectives, and leaves everything else alone. A verb inside a compound never changes, and a noun introduced by « de » or « à » stays singular if the sense is singular — each chef heads one unit, so it is « des chefs d'unité ». The English-speaker error is to put an -s on the end of the whole thing, as if it were one word: « des rendez-vouss », « des chefs d'unités ». Say the compound out loud in its parts and ask which parts could logically be plural.", "table": {"cols": ["Singular", "Plural", "Why"], "rows": [["un chou-fleur", "des choux-fleurs", "noun + noun: both agree"], ["un État membre", "des États membres", "noun + noun: both agree"], ["un chef d'unité", "des chefs d'unité", "only the head noun; each chef has one unit"], ["une carte d'identité", "des cartes d'identité", "only the head noun"], ["un rendez-vous", "des rendez-vous", "verb + pronoun: nothing can change"], ["une pomme de terre", "des pommes de terre", "only the head noun"], ["un gratte-ciel", "des gratte-ciel", "verb + noun, and there is only one sky"]]}, "examples": [{"fr": "Les vingt-sept États membres ont approuvé le texte.", "en": "The twenty-seven Member States approved the text.", "gloss": {"membres": "member"}, "note": "Both words are nouns, so both take the -s. This exact phrase appears in every Council document."}, {"fr": "Les chefs d'unité se réunissent le mardi matin.", "en": "The heads of unit meet on Tuesday mornings.", "gloss": {"chefs": "heads"}, "note": "« D'unité » stays singular: each of them heads one unit."}, {"fr": "J'ai deux rendez-vous cette semaine à la commune.", "en": "I have two appointments at the commune this week.", "gloss": {"rendez-vous": "appointments"}, "note": "Completely invariable. Only « deux » shows the plural."}]}, {"id": "gl-gender-B1-05", "heading": "Same word, two genders, two meanings", "body": "A small set of nouns exists in both genders with unrelated meanings, and here the article is not decoration — it is the word. « Je cherche un livre » is a book; « j'ai perdu une livre » is a pound. English speakers get caught because they think of the article as grammar and the noun as meaning, so they let the article slide. In these words the article carries the meaning outright.", "table": {"cols": ["Masculine", "Feminine", "Example"], "rows": [["le livre — the book", "la livre — the pound (weight or sterling)", "un livre de 300 pages / 500 grammes, soit une livre"], ["le poste — the job, the set", "la poste — the post office, the mail", "un poste d'assistant / je passe à la poste"], ["le tour — the turn, the trip", "la tour — the tower", "c'est mon tour / la tour du Midi"], ["le mode — the way, the method", "la mode — fashion", "le mode d'emploi / c'est à la mode"], ["le critique — the reviewer (person)", "la critique — the criticism, the review", "un critique sévère / une critique sévère"], ["le mémoire — the dissertation", "la mémoire — memory", "j'ai écrit un mémoire / j'ai une bonne mémoire"], ["le manche — the handle", "la manche — the sleeve", "le manche du couteau / les manches de la chemise"]]}, "examples": [{"fr": "La tour du Midi est le plus haut bâtiment de Belgique.", "en": "The Tour du Midi is the tallest building in Belgium.", "gloss": {"tour": "tower", "bâtiment": "building"}, "note": "Feminine for the building. « Le tour » would be a turn or a circuit: « le Tour de France », « c'est ton tour »."}, {"fr": "Il a obtenu un poste d'assistant à la Commission.", "en": "He got an assistant post at the Commission.", "gloss": {"poste": "post / position"}, "note": "Masculine for a job. « Je passe à la poste » is the post office — in Belgium, bpost."}, {"fr": "J'ai écrit un mémoire sur la politique de cohésion.", "en": "I wrote a dissertation on cohesion policy.", "gloss": {"mémoire": "dissertation"}, "note": "Masculine for a written submission or a thesis; « la mémoire » is memory, including a computer's."}]}, {"id": "gl-gender-B1-06", "heading": "Job titles, and how Belgium feminises them", "body": "Belgium settled this question long before France did: a 1993 decree of the French Community requires feminised job titles in official texts, so in Brussels you write la directrice, la cheffe d'unité, la professeure, l'auteure, une échevine, and Madame la Ministre. France resisted « cheffe » and « auteure » for years and still hesitates over « autrice », so do not be surprised to see the masculine used for women in French texts — but in a Belgian letter or a note to your hierarchy, feminise. Two forms are peculiarly Belgian: le/la bourgmestre is the mayor of a commune (France says « le maire ») and l'échevin/l'échevine is a member of the commune's executive (France says « adjoint au maire »).", "table": {"cols": ["Pattern", "Masculine", "Feminine", "Note"], "rows": [["-teur → -trice", "un traducteur, un directeur", "une traductrice, une directrice", "the largest group"], ["-eur → -euse", "un chercheur, un vendeur", "une chercheuse, une vendeuse", "when a verb exists: chercher, vendre"], ["-ien → -ienne", "un technicien", "une technicienne", "the n doubles"], ["-er → -ère", "un infirmier, un boulanger", "une infirmière, une boulangère", "grave accent added"], ["already in -e", "un fonctionnaire, un juriste", "une fonctionnaire, une juriste", "only the article changes"], ["irregular", "un chef, un auteur, un professeur", "une cheffe, une auteure, une professeure", "the Belgian forms; France varies"], ["Belgian titles", "le bourgmestre, l'échevin", "la bourgmestre, l'échevine", "commune, not mairie"]]}, "examples": [{"fr": "Elle est traductrice au Conseil depuis dix ans.", "en": "She has been a translator at the Council for ten years.", "gloss": {"traductrice": "translator (f)"}, "note": "-teur becomes -trice. Note also that no article follows « est » with a job title."}, {"fr": "Ma cheffe d'unité est en mission à Luxembourg.", "en": "My head of unit is on mission in Luxembourg.", "gloss": {"cheffe": "head (f)", "mission": "official trip"}, "note": "« Cheffe » is standard in Belgium and now accepted in France too. « Ma chef » is still heard, but do not write it."}, {"fr": "La bourgmestre a signé l'arrêté communal hier.", "en": "The mayor signed the communal order yesterday.", "gloss": {"bourgmestre": "mayor (Belgian)", "arrêté": "order / by-law"}, "note": "Belgian French. In France this person is « le maire » and the office is « la mairie »; in Belgium it is « la commune » and « la maison communale »."}]}], "recognise": [{"id": "gr-gender-B1-01", "level": "B1", "format": "cloze", "q": "Tous les ___ belges ont publié le communiqué.", "options": ["journaux", "journals", "journeaux", "journal"], "a": 0, "trap": "journals — the English plural, which is what almost every learner writes first", "expl": "-al becomes -aux: le journal → les journaux. « Journeaux » is the classic misspelling: there is no e."}, {"id": "gr-gender-B1-02", "level": "B1", "format": "cloze", "q": "Bruxelles accueille plusieurs ___ de musique en été.", "options": ["festivals", "festivaux", "festivales", "festival"], "a": 0, "trap": "festivaux — the -al → -aux rule looks like it must apply here", "expl": "Bal, carnaval, festival, récital, régal and chacal are the -al nouns that keep a plain -s."}, {"id": "gr-gender-B1-03", "level": "B1", "format": "cloze", "q": "Les ___ de la rue Belliard durent depuis deux ans.", "options": ["travaux", "travails", "travailles", "travail"], "a": 0, "trap": "travails — most -ail nouns really do add -s (des détails, des portails)", "expl": "Travail is one of the seven -ail nouns going to -aux. In the plural « les travaux » means roadworks."}, {"id": "gr-gender-B1-04", "level": "B1", "format": "cloze", "q": "Je vous envoie les ___ par mail cet après-midi.", "options": ["détails", "détaux", "détailles", "détail"], "a": 0, "trap": "détaux — over-correction after learning travail → travaux", "expl": "Only bail, corail, émail, soupirail, travail, vantail and vitrail take -aux. Détail, portail and rail are regular."}, {"id": "gr-gender-B1-05", "level": "B1", "format": "cloze", "q": "Les ___ tricolores ne fonctionnent pas au carrefour.", "options": ["feux", "feus", "feuxs", "feu"], "a": 0, "trap": "feus — the English -s reflex applied to a noun in -eu", "expl": "-eu takes -x: le feu → les feux, le jeu → les jeux, le cheveu → les cheveux."}, {"id": "gr-gender-B1-06", "level": "B1", "format": "cloze", "q": "J'ai fait changer les ___ de la voiture avant l'hiver.", "options": ["pneus", "pneux", "pneaux", "pneu"], "a": 0, "trap": "pneux — the -eu → -eux rule looks like it should apply", "expl": "Pneu and bleu are the two -eu nouns that take -s: des pneus, des bleus."}, {"id": "gr-gender-B1-07", "level": "B1", "format": "cloze", "q": "Elle a acheté des ___ au marché du Châtelain.", "options": ["choux", "chous", "choues", "chou"], "a": 0, "trap": "chous — most -ou nouns are regular (des trous, des clous), so this looks right", "expl": "Bijou, caillou, chou, genou, hibou, joujou and pou are the seven -ou nouns taking -x."}, {"id": "gr-gender-B1-08", "level": "B1", "format": "cloze", "q": "J'ai emprunté ___ livre à la bibliothèque de la commune.", "options": ["un", "une", "du", "des"], "a": 0, "trap": "une — « une livre » is a real word, but it means a pound", "expl": "« Un livre » is a book; « une livre » is a pound in weight or in sterling. The article carries the meaning."}, {"id": "gr-gender-B1-09", "level": "B1", "format": "cloze", "q": "Je passe à ___ poste pour envoyer le recommandé.", "options": ["la", "le", "l'", "les"], "a": 0, "trap": "le — « le poste » exists, but it is a job or a television set", "expl": "« La poste » is the postal service, bpost in Belgium. « Un poste » is a position: un poste d'assistant."}, {"id": "gr-gender-B1-10", "level": "B1", "format": "cloze", "q": "Sophie est ___ au Conseil depuis dix ans.", "options": ["traductrice", "traducteuse", "traductresse", "traducteur"], "a": 0, "trap": "traducteur — using the masculine for a woman, still common in French texts but not in Belgian ones", "expl": "-teur becomes -trice: traductrice, directrice, administratrice. -euse is for verbs: chercheur → chercheuse."}], "drills": [{"id": "gd-gender-B1-01", "level": "B1", "format": "cloze", "q": "Il y a plusieurs ___ en Wallonie au mois de février.", "options": ["carnavals", "carnavaux", "carnavales", "carnaval"], "a": 0, "trap": "carnavaux — the -al → -aux rule, correctly learnt and wrongly applied", "expl": "Carnaval is on the exception list with bal, festival, récital and régal: plain -s. The Binche carnival is « le carnaval de Binche »."}, {"id": "gd-gender-B1-02", "level": "B1", "format": "cloze", "q": "Les ___ belges appliquent directement le règlement européen.", "options": ["tribunaux", "tribunals", "tribuneaux", "tribunales"], "a": 0, "trap": "tribunals — the English word « tribunals » exists, which makes the wrong form feel safe", "expl": "Regular -al: le tribunal → les tribunaux, like le journal, le canal, le total, le signal."}, {"id": "gd-gender-B1-03", "level": "B1", "format": "cloze", "q": "Les ___ de l'immeuble ont gelé pendant la vague de froid.", "options": ["tuyaux", "tuyaus", "tuyeaux", "tuyau"], "a": 0, "trap": "tuyaus — the -s reflex; -au behaves like -eau and takes -x", "expl": "-au → -aux: le tuyau → les tuyaux. Only « le landau » takes -s."}, {"id": "gd-gender-B1-04", "level": "B1", "format": "cloze", "q": "En Belgique, les ___ de résidence principale sont de neuf ans.", "options": ["baux", "bails", "bailles", "baus"], "a": 0, "trap": "bails — the regular -ail plural, which is right for détail but not for bail", "expl": "Bail is one of the seven -ail nouns taking -aux: un bail → des baux. Belgian leases for a main residence run nine years."}, {"id": "gd-gender-B1-05", "level": "B1", "format": "collocation", "q": "Which plural is correct? — un rendez-vous", "options": ["des rendez-vous", "des rendez-vouses", "des rendezs-vous", "des rendez-vouss"], "a": 0, "trap": "des rendezs-vous — trying to pluralise the verb part of the compound", "expl": "A verb inside a compound never agrees, and « vous » is a pronoun. The whole thing is invariable: only the article shows the plural."}, {"id": "gd-gender-B1-06", "level": "B1", "format": "cloze", "q": "Les vingt-sept ___ ont approuvé le texte du Conseil.", "options": ["États membres", "États membre", "État membres", "États-membres"], "a": 0, "trap": "États membre — treating « membre » as an invariable label rather than a noun", "expl": "Both parts are nouns, so both take the -s: des États membres. There is no hyphen in the official spelling."}, {"id": "gd-gender-B1-07", "level": "B1", "format": "cloze", "q": "Les ___ se réunissent le mardi matin.", "options": ["chefs d'unité", "chefs d'unités", "chef d'unités", "chefs d'unitées"], "a": 0, "trap": "chefs d'unités — putting the plural on both nouns, as English does with « heads of units »", "expl": "Only the head noun agrees; « d'unité » stays singular because each chef heads one unit. Same for « des cartes d'identité »."}, {"id": "gd-gender-B1-08", "level": "B1", "format": "cloze", "q": "Delhaize vend des ___ bio toute l'année.", "options": ["choux-fleurs", "chou-fleurs", "choux-fleur", "choux-fleures"], "a": 0, "trap": "chou-fleurs — pluralising only the second half, the way an English compound works", "expl": "In a noun + noun compound both parts agree: un chou-fleur → des choux-fleurs, un État membre → des États membres."}, {"id": "gd-gender-B1-09", "level": "B1", "format": "cloze", "q": "___ tour du Midi est le plus haut bâtiment de Belgique.", "options": ["La", "Le", "L'", "Les"], "a": 0, "trap": "Le — « le tour » is extremely common, but it means a turn or a circuit", "expl": "The building is « la tour ». « Le tour » is a turn or a trip: c'est mon tour, le Tour de France, faire le tour du quartier."}, {"id": "gd-gender-B1-10", "level": "B1", "format": "cloze", "q": "Lisez ___ mode d'emploi avant d'utiliser l'imprimante.", "options": ["le", "la", "l'", "les"], "a": 0, "trap": "la — « la mode » is the word everyone knows, and it means fashion", "expl": "« Le mode » is a way of doing something: le mode d'emploi, le mode de vie, le mode de scrutin."}, {"id": "gd-gender-B1-11", "level": "B1", "format": "cloze", "q": "Le rapport a reçu ___ critique très sévère de la Cour des comptes.", "options": ["une", "un", "de la", "des"], "a": 0, "trap": "un — « un critique » is correct French, but it is a person, a reviewer", "expl": "« Une critique » is the criticism or the review itself; « un critique » is the human being who writes it."}, {"id": "gd-gender-B1-12", "level": "B1", "format": "cloze", "q": "J'ai écrit ___ mémoire sur la politique de cohésion.", "options": ["un", "une", "du", "des"], "a": 0, "trap": "une — « la mémoire » is the everyday word, meaning memory", "expl": "« Un mémoire » is a dissertation or a formal written submission; « la mémoire » is memory, including a computer's."}, {"id": "gd-gender-B1-13", "level": "B1", "format": "cloze", "q": "Elle est ___ à l'ULB depuis la fin de son doctorat.", "options": ["chercheuse", "chercheure", "chercheresse", "chercheur"], "a": 0, "trap": "chercheur — the masculine left unchanged for a woman", "expl": "When the noun matches a verb (chercher), -eur becomes -euse: chercheuse, vendeuse, serveuse. -trice is for -teur: traductrice."}, {"id": "gd-gender-B1-14", "level": "B1", "format": "collocation", "q": "Anne is a lawyer. Which form does a Belgian official letter use?", "options": ["une avocate", "une avocat", "une avocatrice", "une avocateuse"], "a": 0, "trap": "une avocat — leaving the masculine noun after a feminine article, which Belgian administrative French does not allow", "expl": "Simple -e feminisation: avocat → avocate, étudiant → étudiante. Belgium has required feminised job titles in official texts since 1993."}, {"id": "gd-gender-B1-15", "level": "B1", "format": "cloze", "q": "Elle est ___ à la STIB, elle répare les rames de métro.", "options": ["technicienne", "techniciene", "techniciène", "technicien"], "a": 0, "trap": "technicien — the masculine form used for a woman", "expl": "-ien doubles the n before the -e: technicienne, informaticienne, pharmacienne."}, {"id": "gd-gender-B1-16", "level": "B1", "format": "cloze", "q": "___ poste belge s'appelle bpost depuis 2010.", "options": ["La", "Le", "L'", "Les"], "a": 0, "trap": "Le — « le poste » is a job or a set, and it is the form learners have usually met first", "expl": "The postal service is feminine: la poste. « Un poste » is a position (un poste d'assistant) or a device (un poste de radio)."}], "write": [{"id": "gw-gender-B1-01", "prompt": "the newspapers — plural of « le journal » (with the definite article)", "answer": "les journaux", "accept": ["les journaux"], "hint": "-al", "expl": "-al becomes -aux: le journal → les journaux."}, {"id": "gw-gender-B1-02", "prompt": "the festivals — plural of « le festival » (with the definite article)", "answer": "les festivals", "accept": ["les festivals"], "hint": "an exception", "expl": "Bal, carnaval, festival, récital and régal keep a plain -s."}, {"id": "gw-gender-B1-03", "prompt": "the roadworks — plural of « le travail » (with the definite article)", "answer": "les travaux", "accept": ["les travaux"], "hint": "-ail, one of the seven", "expl": "Travail → travaux. In the plural the word normally means roadworks."}, {"id": "gw-gender-B1-04", "prompt": "the details — plural of « le détail » (with the definite article)", "answer": "les détails", "accept": ["les détails"], "hint": "-ail, but regular", "expl": "Only seven -ail nouns take -aux; détail is not one of them."}, {"id": "gw-gender-B1-05", "prompt": "the leases — plural of « le bail » (with the definite article)", "answer": "les baux", "accept": ["les baux"], "hint": "-ail, one of the seven", "expl": "Un bail → des baux. The Belgian main-residence lease runs for nine years."}, {"id": "gw-gender-B1-06", "prompt": "the tyres — plural of « le pneu » (with the definite article)", "answer": "les pneus", "accept": ["les pneus"], "hint": "-eu, but an exception", "expl": "Pneu and bleu take -s; every other -eu noun takes -x."}, {"id": "gw-gender-B1-07", "prompt": "the jewels — plural of « le bijou » (with the definite article)", "answer": "les bijoux", "accept": ["les bijoux"], "hint": "-ou, one of the seven", "expl": "Bijou, caillou, chou, genou, hibou, joujou, pou take -x. All other -ou nouns take -s."}, {"id": "gw-gender-B1-08", "prompt": "two appointments (with the number)", "answer": "deux rendez-vous", "accept": ["deux rendez-vous"], "hint": "invariable compound", "expl": "« Rendez-vous » never changes: only the number or the article shows the plural."}, {"id": "gw-gender-B1-09", "prompt": "the Member States (with the definite article)", "answer": "les États membres", "accept": ["les états membres"], "hint": "both halves are nouns", "expl": "Both parts agree: des États membres, les États membres. No hyphen."}, {"id": "gw-gender-B1-10", "prompt": "the heads of unit (with the definite article)", "answer": "les chefs d'unité", "accept": ["les chefs d'unité"], "hint": "only one half can be plural", "expl": "« D'unité » stays singular — each chef heads a single unit."}, {"id": "gw-gender-B1-11", "prompt": "the tower (definite article) — the building, not a turn", "answer": "la tour", "accept": ["la tour"], "hint": "the gender is the meaning", "expl": "La tour = the tower. Le tour = a turn or a trip."}, {"id": "gw-gender-B1-12", "prompt": "she is a translator (no article after the verb)", "answer": "elle est traductrice", "accept": ["elle est traductrice"], "hint": "-teur → -trice", "expl": "Feminine of traducteur, and French drops the article after être with a job title."}], "apply": [{"id": "ga-gender-B1-01", "situation": "You will be late for a 9.00 meeting because of the roadworks on rue Belliard.", "task": "Write one line to your head of unit explaining why.", "accept": ["je serai en retard à cause des travaux rue belliard", "je serai en retard à cause des travaux de la rue belliard", "j'arriverai en retard à cause des travaux rue belliard", "désolé je serai en retard à cause des travaux rue belliard", "je vais être en retard à cause des travaux dans la rue belliard", "je serai un peu en retard à cause des travaux rue belliard"], "model": "Je serai en retard à cause des travaux rue Belliard.", "expl": "« Les travaux » — travail is one of the seven -ail nouns taking -aux, and in the plural it means roadworks."}, {"id": "ga-gender-B1-02", "situation": "You are on the phone to your landlord in Saint-Gilles.", "task": "Say that your lease ends in September.", "accept": ["mon bail se termine en septembre", "mon bail finit en septembre", "le bail se termine en septembre", "mon bail se termine fin septembre", "mon bail arrive à échéance en septembre", "le bail prend fin en septembre"], "model": "Mon bail se termine en septembre.", "expl": "« Un bail » is masculine; the plural, « des baux », is the form that catches people out."}, {"id": "ga-gender-B1-03", "situation": "A colleague is drafting a letter to the bourgmestre of your commune, who is a woman, and has typed « Monsieur le Bourgmestre ».", "task": "Write the correct Belgian opening line of the letter.", "accept": ["madame la bourgmestre", "madame la bourgmestre de la commune", "à madame la bourgmestre", "chère madame la bourgmestre"], "model": "Madame la Bourgmestre,", "expl": "Belgian administrative French feminises job titles: « la bourgmestre ». And it is « bourgmestre » in Belgium, not « maire »."}, {"id": "ga-gender-B1-04", "situation": "In an EPSO interview you are asked about your studies.", "task": "Say that you wrote a dissertation on cohesion policy.", "accept": ["j'ai écrit un mémoire sur la politique de cohésion", "j'ai rédigé un mémoire sur la politique de cohésion", "j'ai fait un mémoire sur la politique de cohésion", "mon mémoire portait sur la politique de cohésion", "j'ai écrit un mémoire sur la politique de cohésion de l'union européenne", "j'ai rédigé un mémoire portant sur la politique de cohésion"], "model": "J'ai rédigé un mémoire sur la politique de cohésion.", "expl": "« Un mémoire » is the dissertation; « la mémoire » would be memory. Here the article is the whole meaning."}, {"id": "ga-gender-B1-05", "situation": "You are telling a visitor where the meeting is.", "task": "Say that the meeting is in the Tour du Midi, on the twelfth floor.", "accept": ["la réunion est dans la tour du midi au douzième étage", "la réunion a lieu dans la tour du midi au douzième étage", "la réunion est à la tour du midi au douzième étage", "la réunion se tient dans la tour du midi au douzième étage", "c'est dans la tour du midi au douzième étage", "la réunion a lieu à la tour du midi au 12e étage"], "model": "La réunion a lieu dans la tour du Midi, au douzième étage.", "expl": "« La tour » for the building. « Le tour » would mean a turn or a circuit."}, {"id": "ga-gender-B1-06", "situation": "You are at the bpost counter with a parcel slip.", "task": "Ask whether your parcel is at the post office.", "accept": ["est-ce que mon colis est à la poste", "mon colis est à la poste", "bonjour est-ce que mon colis est à la poste", "je voudrais savoir si mon colis est à la poste", "est-ce que mon colis est arrivé à la poste", "je viens chercher un colis à la poste"], "model": "Bonjour, est-ce que mon colis est à la poste ?", "expl": "« La poste » is the postal service. « Le poste » would be a job or a radio set."}]},
  "articles-A2": {"slug": "articles", "level": "A2", "title": "Les articles et les partitifs", "summary": "Definite, indefinite and partitive articles: when to say le, un or du, why French puts an article where English puts nothing, and what happens after a negative.", "why": "This is the most frequent error English speakers make in French, and it appears in almost every sentence you write. « J'aime café » and « je n'ai pas de la monnaie » are both instantly recognisable as foreign, and both are fixed by two short rules.", "lesson": [{"id": "gl-articles-A2-01", "heading": "French almost never leaves a noun bare", "body": "English lets a noun stand alone: « I'd like coffee », « meetings are boring », « I have money ». French does not. Except in a few fixed cases you will meet later, every noun in a French sentence carries a determiner, and you must choose one of three families before you can even start the sentence. The English-speaker error is not choosing the wrong article — it is leaving the article out altogether, because in English the sentence sounded complete without it.", "table": {"cols": ["Family", "Masculine", "Feminine", "Before a vowel", "Plural"], "rows": [["definite — the", "le bureau", "la réunion", "l'accord, l'adresse", "les bureaux"], ["indefinite — a / some", "un bureau", "une réunion", "un accord, une adresse", "des bureaux"], ["partitive — an unmeasured amount", "du café", "de la soupe", "de l'eau", "des légumes"]]}, "examples": [{"fr": "Je voudrais un café, s'il vous plaît.", "en": "I'd like a coffee, please.", "gloss": {"voudrais": "would like"}, "note": "One cup, so « un ». « Je voudrais café » is not a sentence in French."}, {"fr": "Les réunions du lundi matin sont trop longues.", "en": "Monday morning meetings are too long.", "gloss": {"réunions": "meetings", "longues": "long"}, "note": "English needs no article here; French does. Leaving out « les » is the error to watch."}]}, {"id": "gl-articles-A2-02", "heading": "le café, un café, du café — three different sentences", "body": "This one table removes most of the confusion. « Le » points at coffee as a whole category or at one specific coffee already mentioned. « Un » counts one of them. « Du » takes an unmeasured amount out of the mass. English uses the bare noun for the first and third of those, which is why you must decide consciously in French what you decide automatically in English.", "table": {"cols": ["French", "What it does", "English"], "rows": [["J'aime le café.", "coffee as a whole category", "I like coffee."], ["Je voudrais un café.", "one cup of it", "I'd like a coffee."], ["Je bois du café le matin.", "an unmeasured amount of it", "I drink coffee in the morning."], ["Le café est froid.", "this particular one, already known", "The coffee is cold."]]}, "examples": [{"fr": "J'aime le café, mais je préfère le thé.", "en": "I like coffee, but I prefer tea.", "gloss": {"préfère": "prefer"}, "note": "A general taste always takes the definite article, never « du »."}, {"fr": "Le matin, je bois du café avant de partir.", "en": "In the morning I drink coffee before leaving.", "gloss": {"bois": "drink"}, "note": "Here it is an amount, so the partitive « du »."}, {"fr": "Un café et une eau plate, s'il vous plaît.", "en": "A coffee and a still water, please.", "gloss": {"plate": "still (not sparkling)"}, "note": "Ordering at the counter you count cups and glasses, so un / une."}]}, {"id": "gl-articles-A2-03", "heading": "Where French has an article and English has none", "body": "These are the places English speakers systematically forget the article, because in English the sentence works without one. Learn them as a list: general likes and dislikes, habits with a day of the week, abstract nouns and languages as the subject, and countries. The day-of-the-week rule is worth reading twice, because the presence of the article changes the meaning: « le lundi » is every Monday, « lundi » on its own is this coming Monday.", "table": {"cols": ["Case", "French", "English"], "rows": [["general like / dislike", "J'aime les frites.", "I like chips."], ["habit, every week", "Le lundi, je télétravaille.", "On Mondays I work from home."], ["one specific day", "Lundi, je télétravaille.", "On Monday I'm working from home."], ["abstract noun as subject", "La patience est utile ici.", "Patience is useful here."], ["a language you study", "J'apprends le néerlandais.", "I'm learning Dutch."], ["a country", "La Belgique a trois langues officielles.", "Belgium has three official languages."]]}, "examples": [{"fr": "Je déteste les réunions à seize heures.", "en": "I hate meetings at four o'clock.", "gloss": {"déteste": "hate"}, "note": "After aimer, adorer, détester and préférer, always the definite article."}, {"fr": "Le lundi, je travaille à la maison.", "en": "On Mondays I work from home.", "gloss": {"lundi": "Monday"}, "note": "Every Monday. Drop « le » and you are talking about one specific Monday."}, {"fr": "Le français est obligatoire pour ce poste à la Commission.", "en": "French is compulsory for this post at the Commission.", "gloss": {"obligatoire": "compulsory"}, "note": "A language as the subject of the sentence takes « le »."}]}, {"id": "gl-articles-A2-04", "heading": "The partitive: du, de la, de l'", "body": "The partitive is the article you use for a quantity you are not counting: some bread, some water, some patience. It is built from « de » plus the definite article, so it agrees with the noun's gender — which is the practical reason gender matters. Two things go wrong for English speakers. First, they translate « some » as optional and drop it: « je voudrais pain ». Second, they use « du » for everything, because « du » was the first form they learnt; « du soupe » gives you away immediately, since la soupe is feminine.", "table": {"cols": ["Noun", "Partitive", "Example"], "rows": [["masculine", "du", "du pain, du travail, du monde"], ["feminine", "de la", "de la soupe, de la patience, de la monnaie"], ["starts with a vowel", "de l'", "de l'eau, de l'argent, de l'huile"], ["plural", "des", "des légumes, des frites, des collègues"]]}, "examples": [{"fr": "Il reste de la soupe pour ce soir.", "en": "There's some soup left for tonight.", "gloss": {"reste": "is left"}, "note": "« La soupe » is feminine, so « de la », never « du »."}, {"fr": "Je bois de l'eau plate au bureau.", "en": "I drink still water at the office.", "gloss": {"eau": "water"}, "note": "Before a vowel both du and de la become « de l' », whatever the gender."}, {"fr": "Il y a du monde au marché le samedi matin.", "en": "The market is busy on Saturday mornings.", "gloss": {"monde": "people (in « du monde »)"}, "note": "« Du monde » means a crowd of people. « Le monde » means the world — the article changes the word."}]}, {"id": "gl-articles-A2-05", "heading": "After a negative, un / une / du / de la all become de", "body": "This is the rule that makes a sentence sound native or foreign in one word. Whenever a negative kills off the thing itself, the article collapses to a bare « de » (or « d' » before a vowel): « j'ai de la monnaie » becomes « je n'ai pas de monnaie ». The English-speaker error is to negate the verb and leave the article standing: « je n'ai pas de la monnaie ». Two exceptions save you from over-applying it. The definite article never changes, because a general taste survives the negative: « je n'aime pas le café ». And after the verb être nothing changes either: « ce n'est pas un problème ».", "table": {"cols": ["Positive", "Negative", "What happened"], "rows": [["J'ai de la monnaie.", "Je n'ai pas de monnaie.", "de la → de"], ["Il y a du lait.", "Il n'y a plus de lait.", "du → de"], ["Nous avons une imprimante.", "Nous n'avons pas d'imprimante.", "une → d' before a vowel"], ["Il y a des places.", "Il n'y a plus de places.", "des → de"], ["J'aime le café.", "Je n'aime pas le café.", "le stays — definite articles never change"], ["C'est un problème.", "Ce n'est pas un problème.", "un stays — after être nothing changes"]]}, "examples": [{"fr": "Je n'ai pas de monnaie, désolé.", "en": "I don't have any change, sorry.", "gloss": {"monnaie": "change (coins)"}, "note": "« La monnaie » is the coins you get back; money in general is « l'argent »."}, {"fr": "Il n'y a plus de tickets au distributeur.", "en": "There are no tickets left in the machine.", "gloss": {"distributeur": "machine / dispenser"}, "note": "« Ne… plus » is a negative too, so the same collapse to « de ». STIB tickets are bought with a MOBIB card or at the machine."}, {"fr": "Ce n'est pas un problème, on peut décaler la réunion.", "en": "That's not a problem, we can move the meeting.", "gloss": {"décaler": "to move / shift"}, "note": "After « ce n'est pas », the article stays. This exception saves the sentence."}]}, {"id": "gl-articles-A2-06", "heading": "à and de melt into the article", "body": "« À le » and « de les » simply do not exist in written or spoken French: they contract. This is mechanical, so the only real difficulty is spotting that a contraction is needed at all. Note the double life of « du »: in « je bois du café » it is a partitive, and in « le bureau du chef » it is de + le. You do not need to tell them apart to write them correctly, but it explains why the same two letters appear everywhere. In Brussels the phrase you will use most is « à la commune » — the Belgian local authority is « la commune » and its building is « la maison communale », not « la mairie ».", "table": {"cols": ["Combination", "Becomes", "Example"], "rows": [["à + le", "au", "Je vais au bureau."], ["à + les", "aux", "J'ai parlé aux collègues."], ["à + la", "à la (no change)", "Je vais à la commune."], ["à + l'", "à l' (no change)", "Je suis à l'aéroport."], ["de + le", "du", "Le bureau du chef d'unité."], ["de + les", "des", "Les horaires des trains."], ["de + la", "de la (no change)", "La porte de la salle."]]}, "examples": [{"fr": "Je vais au bureau en vélo tous les jours.", "en": "I cycle to the office every day.", "gloss": {"vélo": "bike"}, "note": "« À le bureau » is impossible: it contracts to « au »."}, {"fr": "Il faut la signature du chef d'unité.", "en": "The head of unit's signature is needed.", "gloss": {"signature": "signature"}, "note": "Here « du » is de + le, not a partitive."}, {"fr": "Je dois passer à la commune pour ma carte d'identité.", "en": "I have to go to the commune for my ID card.", "gloss": {"commune": "commune (Belgian local authority)"}, "note": "Belgian French: you go « à la commune ». In France you would go « à la mairie »."}]}], "recognise": [{"id": "gr-articles-A2-01", "level": "A2", "format": "cloze", "q": "J'aime ___ café, mais je préfère le thé.", "options": ["le", "du", "un", "de"], "a": 0, "trap": "du — « I like coffee » has no article in English, and « du » feels like the missing « some »", "expl": "After aimer, adorer, détester and préférer, French names the whole category with the definite article: j'aime le café."}, {"id": "gr-articles-A2-02", "level": "A2", "format": "cloze", "q": "Le matin, je bois ___ eau avant de partir.", "options": ["de l'", "de la", "du", "l'"], "a": 0, "trap": "de la — « eau » is feminine, so « de la » looks right until you notice the vowel", "expl": "Before a vowel both « du » and « de la » become « de l' »: de l'eau, de l'argent, de l'huile."}, {"id": "gr-articles-A2-03", "level": "A2", "format": "cloze", "q": "Il n'y a plus ___ lait dans le frigo.", "options": ["de", "du", "le", "un"], "a": 0, "trap": "du — the positive sentence really is « il y a du lait »", "expl": "« Ne… plus » is a negative, so the partitive collapses to a bare « de »."}, {"id": "gr-articles-A2-04", "level": "A2", "format": "cloze", "q": "Je n'ai pas ___ monnaie, désolé.", "options": ["de", "de la", "la", "une"], "a": 0, "trap": "de la — the article learners keep from the positive sentence « j'ai de la monnaie »", "expl": "After a negative, du / de la / des / un / une all become « de ». « La monnaie » is coins; money in general is « l'argent »."}, {"id": "gr-articles-A2-05", "level": "A2", "format": "cloze", "q": "___ lundi, je travaille à la maison.", "options": ["Le", "Un", "Du", "Des"], "a": 0, "trap": "Un — « un lundi » means one Monday among others, which is not what a routine means", "expl": "« Le lundi » = every Monday. With no article at all, « lundi » means this coming Monday."}, {"id": "gr-articles-A2-06", "level": "A2", "format": "cloze", "q": "Je vais ___ bureau en vélo tous les jours.", "options": ["au", "à le", "à la", "aux"], "a": 0, "trap": "à le — the logical form, which French simply does not allow", "expl": "à + le contracts to « au », à + les to « aux ». « À le » never appears in French."}, {"id": "gr-articles-A2-07", "level": "A2", "format": "cloze", "q": "Elle revient ___ Luxembourg demain soir.", "options": ["du", "de le", "de la", "des"], "a": 0, "trap": "de le — again the logical form, which does not exist", "expl": "de + le contracts to « du ». « Le Luxembourg » is masculine, so coming back from it is « du Luxembourg »."}, {"id": "gr-articles-A2-08", "level": "A2", "format": "cloze", "q": "Tu veux ___ soupe ? Il en reste.", "options": ["de la", "du", "de l'", "des"], "a": 0, "trap": "du — the partitive learners reach for by default, whatever the gender", "expl": "The partitive agrees with the noun: « la soupe » is feminine, so « de la soupe »."}, {"id": "gr-articles-A2-09", "level": "A2", "format": "cloze", "q": "Pour la réunion, il faut ___ chaises supplémentaires.", "options": ["des", "de la", "du", "le"], "a": 0, "trap": "de la — the partitive, which never goes with a countable plural", "expl": "Plural and countable: « des chaises ». Du and de la only introduce a mass you are not counting."}, {"id": "gr-articles-A2-10", "level": "A2", "format": "cloze", "q": "Nous n'avons pas ___ imprimante dans ce bureau.", "options": ["d'", "une", "de l'", "de la"], "a": 0, "trap": "une — the article from the positive sentence « nous avons une imprimante »", "expl": "Un and une also collapse to « de » after a negative, and « de » becomes « d' » before a vowel."}], "drills": [{"id": "gd-articles-A2-01", "level": "A2", "format": "collocation", "q": "You are ordering one cup at the counter. Which is right?", "options": ["un café", "du café", "le café", "de café"], "a": 0, "trap": "du café — correct French, but it means an unmeasured amount, not one cup", "expl": "Counting cups takes « un ». « Du café » is the substance; « le café » is coffee as a category or the specific cup already on the table."}, {"id": "gd-articles-A2-02", "level": "A2", "format": "cloze", "q": "Je déteste ___ réunions du lundi matin.", "options": ["les", "des", "de", "du"], "a": 0, "trap": "des — English « I hate Monday meetings » has no article, so « des » feels like the smallest addition", "expl": "A general dislike names the whole category: détester + le / la / les. « Je déteste des réunions » would mean some unspecified meetings."}, {"id": "gd-articles-A2-03", "level": "A2", "format": "cloze", "q": "Il y a ___ neige sur les trottoirs ce matin.", "options": ["de la", "du", "de l'", "des"], "a": 0, "trap": "du — the default partitive, ignoring that « la neige » is feminine", "expl": "The partitive agrees in gender: de la neige, du verglas, de la pluie."}, {"id": "gd-articles-A2-04", "level": "A2", "format": "cloze", "q": "Il n'y a pas ___ neige cette année à Bruxelles.", "options": ["de", "de la", "la", "du"], "a": 0, "trap": "de la — keeping the article from the positive sentence", "expl": "Negative: the partitive collapses to « de », whatever the gender of the noun."}, {"id": "gd-articles-A2-05", "level": "A2", "format": "cloze", "q": "Je n'aime pas ___ bières trappistes, je préfère les blondes.", "options": ["les", "de", "des", "de la"], "a": 0, "trap": "de — the « pas de » rule correctly learnt and wrongly applied to a definite article", "expl": "The « pas de » rule only touches un / une / du / de la / des. A general taste keeps its definite article: je n'aime pas les bières."}, {"id": "gd-articles-A2-06", "level": "A2", "format": "cloze", "q": "Elle travaille ___ commune d'Ixelles depuis trois ans.", "options": ["à la", "au", "à l'", "aux"], "a": 0, "trap": "au — au is à + le, and learners use it as a general-purpose « at the »", "expl": "« La commune » is feminine, so « à la commune ». In Belgium the local authority is la commune, not la mairie."}, {"id": "gd-articles-A2-07", "level": "A2", "format": "cloze", "q": "Il faut la signature ___ chef d'unité avant vendredi.", "options": ["du", "de le", "de la", "des"], "a": 0, "trap": "de le — the uncontracted form, which is never written", "expl": "de + le = du. Here « du » is a contraction, not a partitive, though it is spelt identically."}, {"id": "gd-articles-A2-08", "level": "A2", "format": "cloze", "q": "J'ai déjà parlé ___ collègues néerlandophones du service.", "options": ["aux", "à les", "à la", "au"], "a": 0, "trap": "à les — the form the rule seems to predict; French contracts it to « aux »", "expl": "à + les = aux. Compare « au bureau » (à + le) and « à la commune », which does not contract."}, {"id": "gd-articles-A2-09", "level": "A2", "format": "cloze", "q": "Je prends ___ tram 81 tous les matins.", "options": ["le", "un", "du", "de"], "a": 0, "trap": "un — English says « I take a tram », but a numbered line is a specific thing", "expl": "A named line takes the definite article: le 81, le 71, le métro 5. « Un tram » would mean any tram at all."}, {"id": "gd-articles-A2-10", "level": "A2", "format": "cloze", "q": "Elle met ___ crème dans son café.", "options": ["de la", "du", "de l'", "des"], "a": 0, "trap": "du — the reflex partitive, though « la crème » is feminine", "expl": "An unmeasured amount of a feminine noun: de la crème, de la soupe, de la patience."}, {"id": "gd-articles-A2-11", "level": "A2", "format": "cloze", "q": "Je ne bois jamais ___ café après seize heures.", "options": ["de", "du", "le", "un"], "a": 0, "trap": "du — the positive is « je bois du café », and « jamais » does not look like a negative to an English eye", "expl": "« Ne… jamais » is a negative like « ne… pas », so the partitive collapses to « de »."}, {"id": "gd-articles-A2-12", "level": "A2", "format": "cloze", "q": "Ce n'est pas ___ problème, on peut décaler la réunion.", "options": ["un", "de", "du", "le"], "a": 0, "trap": "de — the « pas de » rule applied where it does not reach", "expl": "After the verb être the article never changes: ce n'est pas un problème, ce n'est pas du café."}, {"id": "gd-articles-A2-13", "level": "A2", "format": "cloze", "q": "___ français est obligatoire pour ce poste.", "options": ["Le", "Du", "Un", "De"], "a": 0, "trap": "Du — learners treat a language as a mass noun, as they would « du pain »", "expl": "A language, like any abstract noun used as a subject, takes the definite article: le français, le néerlandais, la patience."}, {"id": "gd-articles-A2-14", "level": "A2", "format": "cloze", "q": "J'achète toujours ___ légumes au marché du dimanche.", "options": ["des", "les", "du", "de la"], "a": 0, "trap": "les — « les légumes » would be vegetables as a category, not the ones in your bag", "expl": "Buying an unspecified quantity of countable things takes « des »: des légumes, des œufs, des tomates."}, {"id": "gd-articles-A2-15", "level": "A2", "format": "cloze", "q": "Je n'ai pas ___ collègues néerlandophones dans mon service.", "options": ["de", "des", "les", "de la"], "a": 0, "trap": "des — the article from the positive sentence « j'ai des collègues »", "expl": "« Des » collapses to « de » after a negative exactly like du and de la."}, {"id": "gd-articles-A2-16", "level": "A2", "format": "cloze", "q": "Il y a ___ monde au marché le samedi matin.", "options": ["du", "le", "de la", "des"], "a": 0, "trap": "le — « le monde » is a real phrase, but it means the world", "expl": "« Du monde » means people, a crowd. « Il y a le monde » would say the world itself is at the market."}], "write": [{"id": "gw-articles-A2-01", "prompt": "I like coffee. (a general taste)", "answer": "j'aime le café", "accept": ["j'aime le café"], "hint": "the whole category", "expl": "Aimer, adorer, détester and préférer take the definite article, never the partitive."}, {"id": "gw-articles-A2-02", "prompt": "on Mondays — every Monday", "answer": "le lundi", "accept": ["le lundi"], "hint": "one word makes it a habit", "expl": "« Le lundi » = every Monday; « lundi » alone = this coming Monday."}, {"id": "gw-articles-A2-03", "prompt": "some water (partitive)", "answer": "de l'eau", "accept": ["de l'eau"], "hint": "the noun starts with a vowel", "expl": "Before a vowel du and de la both become « de l' »."}, {"id": "gw-articles-A2-04", "prompt": "some soup (partitive)", "answer": "de la soupe", "accept": ["de la soupe"], "hint": "feminine", "expl": "The partitive agrees with the noun: la soupe → de la soupe."}, {"id": "gw-articles-A2-05", "prompt": "I don't have any change. (coins, at the till)", "answer": "je n'ai pas de monnaie", "accept": ["je n'ai pas de monnaie"], "hint": "what happens to « de la » after a negative", "expl": "« J'ai de la monnaie » → « je n'ai pas de monnaie ». The partitive collapses to « de »."}, {"id": "gw-articles-A2-06", "prompt": "There's no coffee left.", "answer": "il n'y a plus de café", "accept": ["il n'y a plus de café"], "hint": "« ne… plus » is a negative too", "expl": "Every negative collapses the partitive: pas de, plus de, jamais de."}, {"id": "gw-articles-A2-07", "prompt": "to the office (à + le bureau)", "answer": "au bureau", "accept": ["au bureau"], "hint": "contraction", "expl": "à + le = au. « À le bureau » does not exist."}, {"id": "gw-articles-A2-08", "prompt": "the head of unit's signature (de + le chef d'unité)", "answer": "la signature du chef d'unité", "accept": ["la signature du chef d'unité"], "hint": "contraction", "expl": "de + le = du. Here « du » is a contraction, not a partitive."}, {"id": "gw-articles-A2-09", "prompt": "I spoke to the colleagues. (à + les collègues)", "answer": "j'ai parlé aux collègues", "accept": ["j'ai parlé aux collègues"], "hint": "contraction", "expl": "à + les = aux. « À les » is never written."}, {"id": "gw-articles-A2-10", "prompt": "I'd like a coffee, please. (ordering one cup)", "answer": "je voudrais un café, s'il vous plaît", "accept": ["je voudrais un café s'il vous plaît", "je voudrais un café, s'il vous plaît", "je voudrais un café"], "hint": "you are counting cups", "expl": "One cup, so « un café ». « Du café » would be the substance."}, {"id": "gw-articles-A2-11", "prompt": "I hate meetings. (in general)", "answer": "je déteste les réunions", "accept": ["je déteste les réunions"], "hint": "the whole category", "expl": "General dislike: the definite article, even though English has none."}, {"id": "gw-articles-A2-12", "prompt": "It isn't a problem.", "answer": "ce n'est pas un problème", "accept": ["ce n'est pas un problème"], "hint": "the exception to « pas de »", "expl": "After être the article survives the negative: ce n'est pas un problème."}], "apply": [{"id": "ga-articles-A2-01", "situation": "You are at the Delhaize till and the cashier asks for €4.20 in cash. You only have a fifty.", "task": "Say that you don't have any change.", "accept": ["je n'ai pas de monnaie", "désolé je n'ai pas de monnaie", "je suis désolé je n'ai pas de monnaie", "je n'ai pas de monnaie désolé", "excusez-moi je n'ai pas de monnaie", "je n'ai pas de monnaie je peux payer par bancontact"], "model": "Désolé, je n'ai pas de monnaie.", "expl": "« J'ai de la monnaie » → « je n'ai pas de monnaie ». In Belgium you would usually add « je peux payer par Bancontact ? »."}, {"id": "ga-articles-A2-02", "situation": "A colleague offers to bring you something from the canteen.", "task": "Ask for a coffee and some water.", "accept": ["un café et de l'eau s'il te plaît", "un café et de l'eau", "je veux bien un café et de l'eau", "un café et de l'eau s'il vous plaît", "je prendrais bien un café et de l'eau", "je voudrais un café et de l'eau"], "model": "Un café et de l'eau, s'il te plaît.", "expl": "« Un café » counts one cup; « de l'eau » is an unmeasured amount, and « eau » starts with a vowel."}, {"id": "ga-articles-A2-03", "situation": "Your head of unit asks when you are in the office.", "task": "Say that on Mondays you work from home.", "accept": ["le lundi je travaille à la maison", "le lundi je télétravaille", "je travaille à la maison le lundi", "le lundi je suis en télétravail", "je télétravaille le lundi", "le lundi je travaille de chez moi"], "model": "Le lundi, je travaille à la maison.", "expl": "« Le lundi » makes it a weekly habit. Without the article it would mean only this coming Monday."}, {"id": "ga-articles-A2-04", "situation": "You are on the phone to the commune of Ixelles about your ID card.", "task": "Say you have to come to the commune tomorrow morning.", "accept": ["je dois passer à la commune demain matin", "je dois venir à la commune demain matin", "je passe à la commune demain matin", "je dois aller à la commune demain matin", "je viendrai à la commune demain matin", "je dois me rendre à la commune demain matin"], "model": "Je dois passer à la commune demain matin.", "expl": "« La commune » is feminine and does not contract: à la commune. Belgian French — in France it would be « à la mairie »."}, {"id": "ga-articles-A2-05", "situation": "A colleague asks whether you want to keep the 16.00 slot for a weekly meeting.", "task": "Say politely that you don't like meetings at four o'clock.", "accept": ["je n'aime pas les réunions à seize heures", "je n'aime pas trop les réunions à seize heures", "je n'aime pas les réunions à 16h", "honnêtement je n'aime pas les réunions à seize heures", "je préfère éviter les réunions à seize heures", "je n'aime pas beaucoup les réunions à seize heures"], "model": "Je n'aime pas trop les réunions à seize heures.", "expl": "The « pas de » rule does not touch the definite article: after aimer it stays « les réunions »."}, {"id": "ga-articles-A2-06", "situation": "You are at the bakery on your commune's main square.", "task": "Ask for a baguette and some bread rolls.", "accept": ["je voudrais une baguette et des pistolets s'il vous plaît", "une baguette et des pistolets s'il vous plaît", "je voudrais une baguette et des pistolets", "bonjour je voudrais une baguette et des pistolets s'il vous plaît", "une baguette et des petits pains s'il vous plaît", "je prends une baguette et des pistolets s'il vous plaît"], "model": "Bonjour, je voudrais une baguette et des pistolets, s'il vous plaît.", "expl": "One baguette you count: « une ». The rolls are countable and unspecified in number: « des ». Belgian French: « un pistolet » is a round bread roll — in France you would ask for « un petit pain »."}]},
  "articles-B1": {"slug": "articles", "level": "B1", "title": "Les articles et les partitifs", "summary": "Quantity expressions with de, « de bons résultats », articles with countries and languages, the places French drops the article, and the definite article in dates and with the body.", "why": "These are the article rules that show up in written work: « beaucoup des collègues » in an EPSO essay, « je suis un fonctionnaire » in an interview, « mon mal de ma tête » in a doctor's surgery in Ixelles. Each one is small, and each one is visible to a native reader in the first line.", "lesson": [{"id": "gl-articles-B1-01", "heading": "After a quantity, the article vanishes", "body": "Anything that measures a quantity — beaucoup, peu, trop, assez, plus, moins, un kilo, une tasse, une bouteille, un tas — is followed by a bare « de », with no article at all: beaucoup de collègues, un kilo de tomates. English speakers write « beaucoup des collègues » because they hear « of the » inside « of ». « Beaucoup des » does exist, but it means « many of the » with a specified group: « beaucoup des collègues de mon service » — many of the colleagues in my particular unit. If you are not pointing at a defined group, use « de ». Four expressions keep the article and you should learn them as a block: bien des, la plupart des, la moitié du / des, la majorité des.", "table": {"cols": ["Expression", "Correct", "Not"], "rows": [["beaucoup", "beaucoup de réunions", "beaucoup des réunions"], ["assez / trop / peu", "assez de temps, trop de mails", "assez du temps"], ["a measure", "un kilo de tomates, une tasse de café", "un kilo des tomates"], ["bien", "bien des collègues", "bien de collègues"], ["la plupart", "la plupart des collègues", "la plupart de collègues"], ["la moitié", "la moitié du rapport", "la moitié de rapport"]]}, "examples": [{"fr": "Il y a beaucoup de monde dans le tram à huit heures.", "en": "The tram is very busy at eight o'clock.", "gloss": {"monde": "people"}, "note": "« Du monde » on its own is right, but after « beaucoup » the article disappears: beaucoup de monde."}, {"fr": "Nous n'avons pas assez de personnel pour ce dossier.", "en": "We don't have enough staff for this file.", "gloss": {"personnel": "staff", "dossier": "file / case"}, "note": "Two rules at once: assez de, and a negative — both point to a bare « de »."}, {"fr": "La plupart des collègues sont déjà en congé.", "en": "Most of the colleagues are already on leave.", "gloss": {"congé": "leave"}, "note": "« La plupart » is the exception that keeps « des ». The verb after it is plural: sont, not est."}]}, {"id": "gl-articles-B1-02", "heading": "des becomes de before an adjective", "body": "When an adjective stands in front of a plural noun, « des » is reduced to « de »: des résultats but de bons résultats. This is the single easiest way to make a written sentence look B2 rather than B1, and it is worth a mark in the EPSO written test. Spoken French is relaxed about it and you will hear « des bons résultats » every day in the office; in writing, use « de ». The exception is a handful of pairs that French treats as one word: des jeunes gens, des petits pois, des petites annonces, des grands-parents.", "table": {"cols": ["No adjective", "With an adjective in front", "Note"], "rows": [["des résultats", "de bons résultats", "written standard"], ["des règles", "de nouvelles règles", "written standard"], ["des difficultés", "de grandes difficultés", "written standard"], ["des collègues sympathiques", "des collègues sympathiques", "adjective after the noun: des stays"], ["des petits pois", "des petits pois", "fixed compound: des stays"]]}, "examples": [{"fr": "L'unité a obtenu de bons résultats cette année.", "en": "The unit got good results this year.", "gloss": {"obtenu": "got / obtained"}, "note": "Adjective before a plural noun: « de », not « des »."}, {"fr": "Le service a pris de nouvelles mesures pour le télétravail.", "en": "The department has taken new measures on teleworking.", "gloss": {"mesures": "measures"}, "note": "Same rule. Note that « des nouvelles mesures » is perfectly normal in speech."}, {"fr": "Il y a des collègues néerlandophones dans presque chaque unité.", "en": "There are Dutch-speaking colleagues in nearly every unit.", "gloss": {"néerlandophones": "Dutch-speaking"}, "note": "The adjective comes after the noun here, so « des » is untouched."}]}, {"id": "gl-articles-B1-03", "heading": "Countries and languages", "body": "Countries carry an article in French when they are the subject or object of a sentence — « la Belgique est petite » — but that article disappears or transforms as soon as you say in, to or from. Feminine countries (almost all those ending in -e) take « en » and « de »; masculine ones take « au » and « du »; plurals take « aux » and « des ». Cities take « à » and « de » with no article, unless the article is part of the name: à La Haye, au Caire. For languages, the article stays everywhere except immediately after the verb parler: je parle français, but j'apprends le néerlandais and le français est obligatoire.", "table": {"cols": ["Country", "Naming it", "in / to", "from"], "rows": [["feminine", "la Belgique, la France, la Grèce", "en Belgique", "de Belgique"], ["masculine", "le Portugal, le Luxembourg, le Danemark", "au Portugal", "du Portugal"], ["plural", "les Pays-Bas, les États-Unis", "aux Pays-Bas", "des Pays-Bas"], ["masculine, starts with a vowel", "l'Italie (f), l'Iran (m)", "en Iran, en Italie", "d'Iran, d'Italie"], ["city", "Bruxelles, Luxembourg", "à Bruxelles", "de Bruxelles"], ["city with an article", "La Haye, Le Caire", "à La Haye, au Caire", "de La Haye, du Caire"]]}, "examples": [{"fr": "Je travaille en Belgique depuis trois ans.", "en": "I've been working in Belgium for three years.", "gloss": {"depuis": "for / since"}, "note": "Feminine country: « en », and the article is gone. Never « en la Belgique »."}, {"fr": "Elle part au Portugal la semaine prochaine.", "en": "She's off to Portugal next week.", "gloss": {"part": "is leaving"}, "note": "Masculine country: à + le = au."}, {"fr": "Nous avons une réunion à La Haye jeudi.", "en": "We have a meeting in The Hague on Thursday.", "gloss": {"Haye": "Hague"}, "note": "A city takes « à », even when the article is part of the name — and the article keeps its capital letter."}, {"fr": "J'apprends le néerlandais à la Maison des Langues.", "en": "I'm learning Dutch at the language centre.", "gloss": {"néerlandais": "Dutch"}, "note": "The article stays after apprendre and étudier. Only « parler » drops it: je parle néerlandais."}]}, {"id": "gl-articles-B1-04", "heading": "Where French drops the article altogether", "body": "There is a short list of places where French, unusually, uses a bare noun, and English speakers hesitate precisely because the English sentence has an article there. The big one is the job title: after être, devenir, rester and comme, a profession takes no article — « je suis fonctionnaire », never « je suis un fonctionnaire ». As soon as you switch to « c'est », the article comes back: « c'est un fonctionnaire », « c'est une excellente traductrice ». The others are mechanical: after « en », after « sans », and in noun + de + noun compounds where the second noun describes a type rather than a specific thing.", "table": {"cols": ["Case", "French", "English"], "rows": [["job after être / devenir", "Elle est traductrice.", "She is a translator."], ["but with c'est", "C'est une traductrice.", "She's a translator."], ["after comme", "Il travaille comme stagiaire.", "He works as a trainee."], ["after en", "Je suis en réunion. / en français / en congé", "I'm in a meeting. / in French / on leave"], ["after sans", "Sans problème. / sans voiture", "No problem. / without a car"], ["noun + de + noun", "une salle de réunion, un chef d'unité", "a meeting room, a head of unit"]]}, "examples": [{"fr": "Elle est traductrice au Conseil depuis dix ans.", "en": "She has been a translator at the Council for ten years.", "gloss": {"traductrice": "translator (f)"}, "note": "No article after « est » with a profession. Adding « une » here is the classic English-speaker error."}, {"fr": "Je suis en réunion jusqu'à midi.", "en": "I'm in a meeting until midday.", "gloss": {"midi": "midday"}, "note": "« En réunion » is a status, with no article. « Dans la réunion » would mean physically inside it."}, {"fr": "J'ai trouvé le bâtiment sans problème.", "en": "I found the building without any trouble.", "gloss": {"trouvé": "found"}, "note": "« Sans » normally takes a bare noun: sans problème, sans argent, sans rendez-vous."}]}, {"id": "gl-articles-B1-05", "heading": "Dates and body parts take the definite article", "body": "Two everyday places where French inserts an article that English does not. Dates: « le 3 septembre », and in the heading of a letter « Bruxelles, le 12 mars 2026 » — that comma and that « le » are the standard Belgian and French letter format, and an EPSO written task will expect them. Body parts: French uses the definite article where English uses a possessive, because the person is already identified by the verb or the pronoun. « J'ai mal à la tête », not « à ma tête »; « elle s'est cassé le bras », not « son bras ». Saying « j'ai mal à ma tête » is understood but marks you out immediately.", "table": {"cols": ["French", "English", "Note"], "rows": [["La réunion aura lieu le 3 septembre.", "The meeting will be held on 3 September.", "no « on », but a « le »"], ["Bruxelles, le 12 mars 2026", "Brussels, 12 March 2026", "letter heading"], ["Il vient le lundi 3 septembre.", "He's coming on Monday 3 September.", "one article for the whole date"], ["J'ai mal à la tête / au dos / aux dents.", "I have a headache / backache / toothache.", "definite article, not a possessive"], ["Elle s'est cassé le bras.", "She broke her arm.", "the reflexive already says whose"], ["Il a les yeux bleus.", "He has blue eyes.", "description of the body: les"]]}, "examples": [{"fr": "La réunion aura lieu le 3 septembre à neuf heures.", "en": "The meeting will take place on 3 September at nine.", "gloss": {"aura": "will have (aura lieu = will take place)"}, "note": "No preposition for the date, but an article: « le 3 septembre »."}, {"fr": "J'ai mal à la tête depuis ce matin.", "en": "I've had a headache since this morning.", "gloss": {"mal": "pain / ache"}, "note": "« À ma tête » is the error. The « j' » has already said whose head it is."}, {"fr": "Il s'est cassé le bras en tombant sur le trottoir.", "en": "He broke his arm falling on the pavement.", "gloss": {"cassé": "broke", "tombant": "falling"}, "note": "With a reflexive verb, the body part takes the definite article."}]}, {"id": "gl-articles-B1-06", "heading": "French repeats the article; English shares one", "body": "English is happy to write « the Council and Commission » and let one « the » cover both nouns. French repeats the determiner in front of every noun in the list: « le Conseil et la Commission », « les États membres et les institutions », « mon frère et ma sœur ». This matters in EU writing more than anywhere else, because institutional lists are long and a missing article is conspicuous. The rule extends to possessives and to « ce »: repeat them all.", "examples": [{"fr": "Le Conseil et la Commission ont publié un communiqué commun.", "en": "The Council and Commission published a joint press release.", "gloss": {"commun": "joint / shared"}, "note": "Two articles, and they are not the same one: le Conseil is masculine, la Commission feminine."}, {"fr": "Les États membres et les institutions doivent appliquer le texte.", "en": "The Member States and institutions must apply the text.", "gloss": {"doivent": "must"}, "note": "« Les États membres et institutions » would read as an error to a French drafter."}, {"fr": "J'ai prévenu ma cheffe d'unité et mon collègue du service juridique.", "en": "I told my head of unit and my colleague in the legal department.", "gloss": {"prévenu": "warned / told"}, "note": "Possessives repeat too, and each agrees with its own noun: ma cheffe, mon collègue."}]}], "recognise": [{"id": "gr-articles-B1-01", "level": "B1", "format": "cloze", "q": "Il y a beaucoup ___ monde dans le tram à huit heures.", "options": ["de", "du", "des", "de la"], "a": 0, "trap": "du — « du monde » is correct on its own, so it feels right after beaucoup too", "expl": "A quantity word is followed by a bare « de »: beaucoup de monde, beaucoup de travail, beaucoup de réunions."}, {"id": "gr-articles-B1-02", "level": "B1", "format": "cloze", "q": "J'ai acheté un kilo ___ tomates au marché.", "options": ["de", "des", "de la", "du"], "a": 0, "trap": "des — English « a kilo of tomatoes » makes learners look for « of the »", "expl": "A measure behaves like beaucoup: un kilo de, une tasse de, une bouteille de, un litre de."}, {"id": "gr-articles-B1-03", "level": "B1", "format": "cloze", "q": "L'unité a obtenu ___ bons résultats cette année.", "options": ["de", "des", "du", "de la"], "a": 0, "trap": "des — right with no adjective (des résultats) and normal in speech, but not in writing", "expl": "An adjective in front of a plural noun turns « des » into « de »: de bons résultats, de nouvelles règles."}, {"id": "gr-articles-B1-04", "level": "B1", "format": "cloze", "q": "Je travaille ___ Belgique depuis trois ans.", "options": ["en", "au", "à", "dans"], "a": 0, "trap": "au — the right form for a masculine country (au Portugal), which la Belgique is not", "expl": "Feminine countries take « en » and lose their article: en Belgique, en France, en Grèce."}, {"id": "gr-articles-B1-05", "level": "B1", "format": "collocation", "q": "Which sentence says « She is a translator »?", "options": ["Elle est traductrice.", "Elle est une traductrice.", "Elle est la traductrice.", "Elle est de traductrice."], "a": 0, "trap": "Elle est une traductrice — English needs « a », so learners supply « une »", "expl": "After être, devenir, rester and comme, a profession takes no article. With « c'est » the article comes back: c'est une traductrice."}, {"id": "gr-articles-B1-06", "level": "B1", "format": "cloze", "q": "La réunion aura lieu ___ 3 septembre.", "options": ["le", "à", "au", "en"], "a": 0, "trap": "à — English « on 3 September » makes learners look for a preposition", "expl": "A date takes the definite article and no preposition: le 3 septembre, le lundi 3 septembre."}, {"id": "gr-articles-B1-07", "level": "B1", "format": "cloze", "q": "J'ai mal ___ tête depuis ce matin.", "options": ["à la", "à ma", "au", "à l'"], "a": 0, "trap": "à ma — English says « my head », so the possessive feels compulsory", "expl": "Body parts take the definite article: j'ai mal à la tête, au dos, aux dents. The « j' » already says whose."}, {"id": "gr-articles-B1-08", "level": "B1", "format": "cloze", "q": "J'apprends ___ néerlandais depuis mon arrivée à Bruxelles.", "options": ["le", "du", "de", "un"], "a": 0, "trap": "du — learners treat a language as a mass, like « du pain »", "expl": "A language keeps its article everywhere except straight after parler: j'apprends le néerlandais, but je parle néerlandais."}, {"id": "gr-articles-B1-09", "level": "B1", "format": "cloze", "q": "___ des collègues sont déjà en congé au mois d'août.", "options": ["La plupart", "Beaucoup", "Peu", "Assez"], "a": 0, "trap": "Beaucoup — the obvious quantity word, and the one learners wrongly pair with « des »", "expl": "La plupart, la moitié and la majorité always keep « des ». « Beaucoup des » is only possible when you point at a defined group (beaucoup des collègues de mon service); with no group defined the form is « beaucoup de collègues », so beaucoup, peu and assez cannot fill this gap."}, {"id": "gr-articles-B1-10", "level": "B1", "format": "cloze", "q": "Mon collègue revient ___ Pays-Bas ce soir.", "options": ["des", "de", "du", "de la"], "a": 0, "trap": "de — right for a feminine country (je viens de Belgique), wrong for a plural one", "expl": "Plural countries take « aux » and « des »: aux Pays-Bas, des Pays-Bas, aux États-Unis, des États-Unis."}], "drills": [{"id": "gd-articles-B1-01", "level": "B1", "format": "cloze", "q": "Il y a trop ___ réunions dans cette direction générale.", "options": ["de", "des", "du", "de la"], "a": 0, "trap": "des — the plural noun makes « des » look obligatory", "expl": "Trop, assez, beaucoup, peu, moins and plus are all followed by a bare « de », whatever the noun."}, {"id": "gd-articles-B1-02", "level": "B1", "format": "cloze", "q": "Nous n'avons pas assez ___ personnel pour traiter ce dossier.", "options": ["de", "du", "de la", "des"], "a": 0, "trap": "du — « du personnel » is correct on its own, and the negative also points at « de »", "expl": "Two rules agree here: « assez de » drops the article, and a negative would drop it anyway."}, {"id": "gd-articles-B1-03", "level": "B1", "format": "cloze", "q": "___ collègues pensent la même chose, mais personne ne le dit.", "options": ["Bien des", "Bien de", "Bien du", "Bien les"], "a": 0, "trap": "Bien de — every other quantity word takes « de », so this looks like the pattern", "expl": "« Bien » is the quantity word that keeps the article: bien des collègues, bien du travail, bien de la patience."}, {"id": "gd-articles-B1-04", "level": "B1", "format": "cloze", "q": "Il a relu ___ rapport en une heure.", "options": ["la moitié du", "la moitié de", "la moitié des", "la moitié le"], "a": 0, "trap": "la moitié de — the « beaucoup de » pattern applied to an expression that does not follow it", "expl": "La moitié, la plupart and la majorité keep the article after « de »: la moitié du rapport, la plupart des collègues."}, {"id": "gd-articles-B1-05", "level": "B1", "format": "cloze", "q": "Le service a pris ___ nouvelles mesures pour le télétravail.", "options": ["de", "des", "du", "de la"], "a": 0, "trap": "des — what everybody says out loud, and what an examiner will still mark", "expl": "Adjective before a plural noun: des becomes de. « De nouvelles mesures », « de bons résultats », « de grandes difficultés »."}, {"id": "gd-articles-B1-06", "level": "B1", "format": "cloze", "q": "Il y a ___ jeunes gens dans la file devant Actiris.", "options": ["des", "de", "du", "de la"], "a": 0, "trap": "de — the « de + adjective » rule looks like it applies, since « jeunes » comes first", "expl": "A few adjective + noun pairs are felt as single words and keep « des »: des jeunes gens, des petits pois, des petites annonces."}, {"id": "gd-articles-B1-07", "level": "B1", "format": "cloze", "q": "Elle part ___ Portugal la semaine prochaine.", "options": ["au", "en", "à", "aux"], "a": 0, "trap": "en — the form for feminine countries, which learners apply to every country", "expl": "Masculine countries take à + le = au: au Portugal, au Danemark, au Luxembourg."}, {"id": "gd-articles-B1-08", "level": "B1", "format": "cloze", "q": "Elle rentre ___ Grèce dimanche soir.", "options": ["de", "de la", "du", "des"], "a": 0, "trap": "de la — « la Grèce » really is feminine, so keeping the article feels logical", "expl": "Feminine countries drop the article after « de »: de Grèce, de France, de Belgique. Masculine ones keep it: du Portugal."}, {"id": "gd-articles-B1-09", "level": "B1", "format": "cloze", "q": "Nous avons une réunion ___ La Haye jeudi prochain.", "options": ["à", "en", "au", "dans"], "a": 0, "trap": "au — the name contains « La », which makes learners look for a contraction", "expl": "Cities take « à », even when an article is part of the name: à La Haye, à La Rochelle. Only « le » contracts: au Caire, au Havre."}, {"id": "gd-articles-B1-10", "level": "B1", "format": "cloze", "q": "Le rapport doit être rédigé ___ français et en anglais.", "options": ["en", "dans le", "au", "le"], "a": 0, "trap": "dans le — a literal translation of « in the French language »", "expl": "« En » plus a language, with no article: en français, en néerlandais, en anglais."}, {"id": "gd-articles-B1-11", "level": "B1", "format": "cloze", "q": "Je suis ___ réunion jusqu'à midi, je vous rappelle après.", "options": ["en", "dans la", "à la", "à une"], "a": 0, "trap": "dans la — grammatical, but it means physically inside a particular meeting", "expl": "« En » plus a bare noun states a status: en réunion, en congé, en mission, en formation."}, {"id": "gd-articles-B1-12", "level": "B1", "format": "cloze", "q": "— Qui est-ce ? — ___ un collègue de la DG BUDG.", "options": ["C'est", "Il est", "Elle est", "Ce sont"], "a": 0, "trap": "Il est — correct only with a bare noun: « il est fonctionnaire », never « il est un collègue »", "expl": "With an article or any determiner you need « c'est »; « il est » is used with a bare profession: il est fonctionnaire."}, {"id": "gd-articles-B1-13", "level": "B1", "format": "cloze", "q": "En haut de la lettre, on écrit : Bruxelles, ___ 12 mars 2026.", "options": ["le", "à", "du", "en"], "a": 0, "trap": "à — English « on 12 March » invites a preposition where French wants an article", "expl": "The standard Belgian and French letter heading is « Ville, le + date »: Bruxelles, le 12 mars 2026."}, {"id": "gd-articles-B1-14", "level": "B1", "format": "cloze", "q": "Il s'est cassé ___ bras en tombant sur le trottoir.", "options": ["le", "son", "un", "du"], "a": 0, "trap": "son — English « his arm » makes the possessive feel compulsory", "expl": "With a reflexive verb the body part takes the definite article: il s'est cassé le bras, je me lave les mains."}, {"id": "gd-articles-B1-15", "level": "B1", "format": "collocation", "q": "Which is correct in a Council document?", "options": ["le Conseil et la Commission", "le Conseil et Commission", "les Conseil et Commission", "le Conseil et le Commission"], "a": 0, "trap": "le Conseil et Commission — English shares one « the » across both nouns; French does not", "expl": "French repeats the article before each noun, and each one agrees: le Conseil (m), la Commission (f)."}, {"id": "gd-articles-B1-16", "level": "B1", "format": "cloze", "q": "J'ai trouvé le bâtiment ___ problème, il est juste en face de la station.", "options": ["sans", "sans un", "sans le", "sans du"], "a": 0, "trap": "sans un — English « without a problem » supplies an article French does not want", "expl": "« Sans » takes a bare noun: sans problème, sans argent, sans voiture, sans rendez-vous."}], "write": [{"id": "gw-articles-B1-01", "prompt": "a lot of work", "answer": "beaucoup de travail", "accept": ["beaucoup de travail"], "hint": "quantity", "expl": "A quantity word takes a bare « de »: beaucoup de travail, never « beaucoup du travail »."}, {"id": "gw-articles-B1-02", "prompt": "not enough time", "answer": "pas assez de temps", "accept": ["pas assez de temps"], "hint": "quantity, and a negative", "expl": "« Assez de » drops the article, and so would the negative on its own."}, {"id": "gw-articles-B1-03", "prompt": "a kilo of tomatoes", "answer": "un kilo de tomates", "accept": ["un kilo de tomates"], "hint": "a measure", "expl": "Measures behave like beaucoup: un kilo de, une bouteille de, une tasse de."}, {"id": "gw-articles-B1-04", "prompt": "good results — plural, with the adjective in front", "answer": "de bons résultats", "accept": ["de bons résultats"], "hint": "what happens to « des »", "expl": "An adjective before a plural noun reduces « des » to « de »."}, {"id": "gw-articles-B1-05", "prompt": "most of the colleagues", "answer": "la plupart des collègues", "accept": ["la plupart des collègues"], "hint": "the exception that keeps its article", "expl": "La plupart, la moitié and la majorité keep « des » / « du »."}, {"id": "gw-articles-B1-06", "prompt": "in Belgium", "answer": "en Belgique", "accept": ["en belgique"], "hint": "feminine country", "expl": "Feminine countries take « en » and lose the article."}, {"id": "gw-articles-B1-07", "prompt": "to Portugal", "answer": "au Portugal", "accept": ["au portugal"], "hint": "masculine country", "expl": "Masculine countries take à + le = au."}, {"id": "gw-articles-B1-08", "prompt": "from the Netherlands", "answer": "des Pays-Bas", "accept": ["des pays-bas"], "hint": "plural country", "expl": "Plural countries take « aux » for in/to and « des » for from."}, {"id": "gw-articles-B1-09", "prompt": "She is a translator. (after the verb être)", "answer": "elle est traductrice", "accept": ["elle est traductrice"], "hint": "no article", "expl": "A profession after être, devenir, rester or comme takes no article."}, {"id": "gw-articles-B1-10", "prompt": "I have a headache.", "answer": "j'ai mal à la tête", "accept": ["j'ai mal à la tête"], "hint": "body part", "expl": "Body parts take the definite article, not a possessive: « à ma tête » is the error."}, {"id": "gw-articles-B1-11", "prompt": "the heading of a letter written in Brussels on 12 March 2026", "answer": "Bruxelles, le 12 mars 2026", "accept": ["bruxelles le 12 mars 2026", "bruxelles, le 12 mars 2026"], "hint": "city, comma, article, date", "expl": "The fixed format is « Ville, le + date ». No preposition, but an article."}, {"id": "gw-articles-B1-12", "prompt": "I'm in a meeting until midday.", "answer": "je suis en réunion jusqu'à midi", "accept": ["je suis en réunion jusqu'à midi"], "hint": "en + bare noun", "expl": "« En réunion » is a status and takes no article; « dans la réunion » would be physical."}], "apply": [{"id": "ga-articles-B1-01", "situation": "Your head of unit asks how the file is going.", "task": "Say that there is a lot of work but you don't have enough staff.", "accept": ["il y a beaucoup de travail mais nous n'avons pas assez de personnel", "il y a beaucoup de travail mais on n'a pas assez de personnel", "il y a beaucoup de travail mais nous manquons de personnel", "nous avons beaucoup de travail mais pas assez de personnel", "on a beaucoup de travail mais pas assez de personnel", "il y a beaucoup de travail et nous n'avons pas assez de personnel"], "model": "Il y a beaucoup de travail, mais nous n'avons pas assez de personnel.", "expl": "« Beaucoup de » and « assez de » both drop the article. « Beaucoup du travail » is the error to avoid."}, {"id": "ga-articles-B1-02", "situation": "You are writing the closing line of an annual report for your unit.", "task": "Say that the unit obtained good results this year.", "accept": ["l'unité a obtenu de bons résultats cette année", "l'unité a obtenu de très bons résultats cette année", "notre unité a obtenu de bons résultats cette année", "l'unité a enregistré de bons résultats cette année", "cette année l'unité a obtenu de bons résultats", "l'unité a obtenu de bons résultats en 2026"], "model": "L'unité a obtenu de bons résultats cette année.", "expl": "Adjective before a plural noun: « de bons résultats ». In speech you will hear « des bons », but not in a written report."}, {"id": "ga-articles-B1-03", "situation": "At an EPSO interview you are asked where you have worked.", "task": "Say that you have been working in Belgium for three years and that before that you were in Greece.", "accept": ["je travaille en belgique depuis trois ans et avant j'étais en grèce", "je travaille en belgique depuis trois ans avant j'étais en grèce", "je travaille en belgique depuis trois ans et avant cela j'étais en grèce", "je travaille en belgique depuis trois ans et auparavant j'étais en grèce", "cela fait trois ans que je travaille en belgique et avant j'étais en grèce", "je travaille en belgique depuis trois ans et avant je travaillais en grèce"], "model": "Je travaille en Belgique depuis trois ans ; avant, j'étais en Grèce.", "expl": "Both countries are feminine, so « en » and no article. Note that « depuis » goes with the present tense in French."}, {"id": "ga-articles-B1-04", "situation": "You are introducing a colleague to a visitor.", "task": "Say that she is a translator and that she works at the Council.", "accept": ["elle est traductrice et elle travaille au conseil", "elle est traductrice elle travaille au conseil", "elle est traductrice et travaille au conseil", "c'est une traductrice et elle travaille au conseil", "elle est traductrice au conseil", "elle est traductrice et elle travaille au conseil de l'union européenne"], "model": "Elle est traductrice et elle travaille au Conseil.", "expl": "No article after « est » with a profession; « c'est une traductrice » is the other correct pattern. « Au Conseil » is à + le."}, {"id": "ga-articles-B1-05", "situation": "You are at the doctor's in Ixelles.", "task": "Say that you have had a headache since Monday.", "accept": ["j'ai mal à la tête depuis lundi", "j'ai mal à la tête depuis lundi matin", "j'ai mal à la tête depuis lundi dernier", "j'ai des maux de tête depuis lundi", "j'ai mal à la tête depuis lundi et ça ne passe pas", "depuis lundi j'ai mal à la tête"], "model": "J'ai mal à la tête depuis lundi.", "expl": "The definite article with a body part: « à la tête », never « à ma tête »."}, {"id": "ga-articles-B1-06", "situation": "You are drafting the first line of a formal note in Brussels on 12 March 2026, addressed to the Council and the Commission.", "task": "Write the date heading and then say that the note concerns the Council and the Commission.", "accept": ["bruxelles le 12 mars 2026 cette note concerne le conseil et la commission", "bruxelles le 12 mars 2026 la note concerne le conseil et la commission", "bruxelles le 12 mars 2026 la présente note concerne le conseil et la commission", "bruxelles le 12 mars 2026 cette note porte sur le conseil et la commission", "bruxelles le 12 mars 2026 la présente note s'adresse au conseil et à la commission"], "model": "Bruxelles, le 12 mars 2026. La présente note concerne le Conseil et la Commission.", "expl": "« Ville, le + date » for the heading, and an article repeated in front of each institution: le Conseil et la Commission."}]},
  "pronouns-B1": {"slug": "pronouns", "level": "B1", "title": "Les pronoms compléments — COD, COI, y, en", "summary": "Stop repeating the noun: le/la/les, lui/leur, y and en, and where each one sits in the sentence.", "why": "Every note you write at the Commission comes back to the same dossier, the same colleague, the same meeting. Until you can pronominalise them you either repeat the noun (which reads as A2) or drop it (which reads as wrong). « Je lui téléphone » versus « je le téléphone » is the single clearest B1/B2 marker in a written note.", "lesson": [{"id": "gl-pronouns-B1-01", "heading": "Direct or indirect? The French verb decides, not the English one", "body": "A direct object follows its verb with nothing in between: « j'attends le bus ». An indirect object is introduced by « à »: « je téléphone à ma cheffe d'unité ». Which pronoun you use depends entirely on which of those the FRENCH verb takes — and French and English disagree constantly. English says «wait FOR the bus», but « attendre » takes no preposition at all; English says «phone him» with no preposition, but « téléphoner À quelqu'un » is indirect. So never reason from the English sentence: look at whether the French verb needs « à ». If it does, the person becomes lui/leur; if it does not, the person or thing becomes le/la/les.", "table": {"cols": ["French verb", "Example", "Object type", "The English trap"], "rows": [["attendre qqn / qqch", "j'attends le bus 71", "direct → le / la / les", "English adds « for »"], ["écouter qqn / qqch", "j'écoute la cheffe d'unité", "direct → le / la / les", "English adds « to »"], ["regarder, chercher, aider, remercier", "j'aide mon collègue", "direct → le / la / les", "no preposition in French either"], ["payer qqch", "je paie l'abonnement STIB", "direct → le / la / les", "English « pay for »"], ["téléphoner à qqn", "je téléphone à Marc", "indirect → lui / leur", "English has no « to »"], ["répondre à qqn / à qqch", "je réponds au chef / au mail", "indirect → lui / y", "English « answer the mail »"], ["demander, dire, écrire, envoyer à qqn", "j'écris à mes collègues", "indirect → lui / leur", "English « write them »"], ["plaire, ressembler, obéir à qqn", "la proposition plaît au chef", "indirect → lui / leur", "English uses a direct object"]]}, "examples": [{"fr": "J'attends le bus 71 devant la commune ; je l'attends depuis dix minutes.", "en": "I'm waiting for the 71 in front of the commune; I've been waiting for it for ten minutes.", "gloss": {"l'attends": "am waiting for it", "commune": "local council / town hall"}, "note": "« Attendre » never takes « pour ». The bus is a direct object, so it becomes l'."}, {"fr": "Je téléphone à Madame Peeters le lundi ; je lui téléphone toujours avant midi.", "en": "I phone Mrs Peeters on Mondays; I always phone her before midday.", "gloss": {"lui": "to him / to her"}, "note": "« Téléphoner à » is indirect, so the pronoun is lui — never « je la téléphone »."}, {"fr": "Le chef d'unité a demandé le rapport, donc je le prépare pour vendredi.", "en": "The head of unit asked for the report, so I'm preparing it for Friday.", "gloss": {"chef d'unité": "head of unit", "le prépare": "am preparing it"}, "note": "« Préparer quelque chose » — direct, so le."}]}, {"id": "gl-pronouns-B1-02", "heading": "le, la, les — the direct object pronouns", "body": "Le replaces a masculine noun, la a feminine one, les any plural, and both le and la shorten to l' in front of a vowel or a silent h. What they replace is a noun that already has a determiner in front of it: « le dossier », « ma note », « ces documents ». There is also a neutral le that stands for a whole idea rather than a noun, used after savoir, croire, dire, espérer: « Oui, je le sais » = yes, I know that. English speakers regularly leave this one out, because English says just «I know»; in a written note « je le sais » is what a native puts.", "examples": [{"fr": "Ce dossier est urgent : je le relis ce soir et je l'envoie demain matin.", "en": "This file is urgent: I'm re-reading it tonight and sending it tomorrow morning.", "gloss": {"le relis": "am re-reading it", "l'envoie": "am sending it"}, "note": "Same noun, two pronouns: le before a consonant, l' before a vowel."}, {"fr": "La note de synthèse ? Je la termine avant la réunion de quatorze heures.", "en": "The summary note? I'm finishing it before the two o'clock meeting.", "gloss": {"note de synthèse": "summary note", "la termine": "am finishing it"}, "note": "Feminine noun, feminine pronoun — the pronoun copies the gender of the noun it replaces."}, {"fr": "La réunion est reportée à jeudi. — Oui, je le sais, le secrétariat m'a prévenu.", "en": "The meeting is moved to Thursday. — Yes, I know, the secretariat let me know.", "gloss": {"reportée": "postponed", "je le sais": "I know (that)"}, "note": "This le is neutral: it stands for the whole fact, not for a noun."}]}, {"id": "gl-pronouns-B1-03", "heading": "lui and leur — one form for him, her and them", "body": "For indirect objects there are only two forms in the third person: lui for one person, leur for several. Lui means «to him» AND «to her» — the gender is simply invisible, which is exactly why English speakers get it wrong: they look for a feminine form and write « je la réponds » or « je elle écris ». And leur as a pronoun never takes an -s; « leurs » with an -s is the possessive «their» (leurs bureaux). Note also that lui/leur only stand for people (or organisations treated as people): for a thing after « à » you need y, which comes two sections down.", "table": {"cols": ["Who", "Direct object (COD)", "Indirect object (COI)"], "rows": [["him (Marc)", "je le vois", "je lui parle"], ["her (Mme Peeters)", "je la vois", "je lui parle"], ["them (mes collègues)", "je les vois", "je leur parle"], ["me / you (vous)", "il me voit / il vous voit", "il me parle / il vous parle"]]}, "examples": [{"fr": "Le chef d'unité attend une réponse : je lui écris cet après-midi.", "en": "The head of unit is waiting for an answer: I'll write to him this afternoon.", "gloss": {"lui écris": "am writing to him"}, "note": "Écrire À quelqu'un — indirect, so lui, whether the person is a man or a woman."}, {"fr": "Mes collègues du secrétariat sont patients, mais je leur dois une réponse.", "en": "My colleagues in the secretariat are patient, but I owe them an answer.", "gloss": {"leur dois": "owe them"}, "note": "Leur, never « leurs » — the -s form is the possessive adjective."}, {"fr": "Cette collègue travaille à la DG COMP ; je lui ai demandé son avis.", "en": "This colleague works at DG COMP; I asked her for her opinion.", "gloss": {"lui": "her (to her)", "avis": "opinion"}, "note": "Feminine person, and still lui — « demander à quelqu'un » is indirect."}]}, {"id": "gl-pronouns-B1-04", "heading": "Placement: in front of the verb, always — including in the negative", "body": "English puts the pronoun after the verb («I see it»); French puts it in front («je le vois»). Three consequences worth memorising as shapes. In the negative, ne … pas wraps around the pronoun AND the verb together: « je ne le vois pas ». In the passé composé the pronoun goes before the auxiliary, not before the participle: « je l'ai vu », never « j'ai le vu ». And when there is an infinitive, the pronoun goes in front of the verb it actually belongs to — which is the infinitive: « je vais le faire », « je ne vais pas le faire », « il faut le remplir ». The commonest English-speaker error is « je vais faire le », putting it where English would.", "table": {"cols": ["Structure", "French", "English"], "rows": [["present", "je le vois", "I see it"], ["negative", "je ne le vois pas", "I don't see it"], ["passé composé", "je l'ai vu", "I saw it"], ["negative passé composé", "je ne l'ai pas vu", "I didn't see it"], ["going to + infinitive", "je vais le faire", "I'm going to do it"], ["negative + infinitive", "je ne vais pas le faire", "I'm not going to do it"], ["il faut / on peut + infinitive", "il faut le remplir en ligne", "you have to fill it in online"]]}, "examples": [{"fr": "Le formulaire de la commune ? Il faut le remplir en ligne, pas au guichet.", "en": "The form from the commune? You have to fill it in online, not at the counter.", "gloss": {"le remplir": "fill it in", "guichet": "counter / desk"}, "note": "The pronoun belongs to remplir, so it sits in front of remplir."}, {"fr": "Je ne vais pas lui répondre aujourd'hui, je suis en réunion toute la journée.", "en": "I'm not going to answer him today, I'm in meetings all day.", "gloss": {"lui répondre": "answer him"}, "note": "Ne … pas wraps the conjugated verb only; lui stays glued to the infinitive."}, {"fr": "La note est partie ce matin : je l'ai envoyée avant neuf heures.", "en": "The note went out this morning: I sent it before nine.", "gloss": {"l'ai envoyée": "sent it"}, "note": "Before the auxiliary, never after. (The extra -e on envoyée is the agreement rule you meet at B2.)"}]}, {"id": "gl-pronouns-B1-05", "heading": "y — « à » plus a thing, and anywhere you are going", "body": "Y replaces « à » plus a thing, an idea or a place: « je vais à la commune » → « j'y vais »; « je réponds au mail » → « j'y réponds »; « je pense à cette réunion » → « j'y pense ». The exception check matters here: y never replaces « à » plus a PERSON. With most verbs a person after « à » becomes lui/leur, but with a small family of verbs — penser à, tenir à, s'intéresser à, faire attention à, s'habituer à — a person stays as « à » plus a stressed pronoun: « je pense à lui », « je pense à elle ». English speakers either use y for people (« j'y pense » about a colleague, which sounds like you are thinking about a place) or drop y altogether, because English lets you say «I'm going» with nothing after it. French cannot: « j'y vais », never « je vais » on its own.", "table": {"cols": ["Full form", "With a pronoun", "Why"], "rows": [["je vais à Ixelles", "j'y vais", "à + place"], ["je réponds au mail", "j'y réponds", "à + thing"], ["je pense à la réunion", "j'y pense", "à + thing"], ["je téléphone à Marc", "je lui téléphone", "à + person → lui"], ["je pense à Marc", "je pense à lui", "penser à + person keeps à + stressed pronoun"]]}, "examples": [{"fr": "Tu vas à la commune de Schaerbeek demain ? — Oui, j'y vais vers neuf heures.", "en": "Are you going to the Schaerbeek commune tomorrow? — Yes, I'm going there around nine.", "gloss": {"j'y vais": "I'm going there"}, "note": "« Oui, je vais » is not French. The y is compulsory."}, {"fr": "J'ai reçu le mail du secrétariat et j'y ai répondu tout de suite.", "en": "I got the email from the secretariat and I answered it straight away.", "gloss": {"j'y ai répondu": "answered it", "tout de suite": "straight away"}, "note": "Répondre à quelque chose → y; répondre à quelqu'un → lui."}, {"fr": "Mon entretien EPSO est en octobre et j'y pense tous les jours.", "en": "My EPSO interview is in October and I think about it every day.", "gloss": {"j'y pense": "I think about it", "entretien": "interview"}, "note": "A thing, so y. About a person it would be « je pense à lui »."}]}, {"id": "gl-pronouns-B1-06", "heading": "en — « de » plus a thing, and every quantity", "body": "En replaces « de » plus a noun, whatever the « de » is doing: « je parle de ce dossier » → « j'en parle »; « j'ai besoin du rapport » → « j'en ai besoin »; « je reviens de la commune » → « j'en reviens ». It also covers the partitive: « je prends du café » → « j'en prends ». The part English speakers never expect is the quantity rule. When you answer with a number or a quantity word, French keeps en in front of the verb and leaves the number at the end: « J'ai trois dossiers » → « J'en ai trois ». « J'ai trois » alone is not a sentence in French, any more than «I have three of» is in English. Same with beaucoup, plusieurs, assez, une dizaine: « j'en ai beaucoup ».", "table": {"cols": ["What « de » is doing", "Full form", "With en"], "rows": [["verb + de + thing", "je parle de ce dossier", "j'en parle"], ["expression with de", "j'ai besoin du rapport", "j'en ai besoin"], ["partitive", "je prends du café", "j'en prends"], ["a number", "j'ai trois dossiers", "j'en ai trois"], ["a quantity word", "j'ai beaucoup de travail", "j'en ai beaucoup"], ["de + place you come from", "je reviens de la commune", "j'en reviens"]]}, "examples": [{"fr": "Vous avez besoin du rapport annuel ? — Oui, j'en ai besoin pour lundi.", "en": "Do you need the annual report? — Yes, I need it for Monday.", "gloss": {"j'en ai besoin": "I need it"}, "note": "Avoir besoin DE, so en — never « je l'ai besoin »."}, {"fr": "Vous avez encore des tickets STIB ? — Oui, il m'en reste deux.", "en": "Have you still got STIB tickets? — Yes, I have two left.", "gloss": {"m'en reste": "I have left", "tickets": "tickets"}, "note": "The number stays at the end and en stays in front of the verb. Belgian numbers work the same way: « il m'en reste septante » (70) — in France you would hear soixante-dix."}, {"fr": "Du travail, j'en ai beaucoup cette semaine, mais j'en parlerai au chef d'unité.", "en": "Work — I've got a lot this week, but I'll mention it to the head of unit.", "gloss": {"j'en ai beaucoup": "I have a lot of it", "j'en parlerai": "I'll talk about it"}, "note": "Two different jobs for en in one sentence: a quantity, then « parler de »."}]}], "recognise": [{"id": "gr-pronouns-B1-01", "level": "B1", "format": "cloze", "q": "J'attends le bus 71 devant la commune. → Je ___ attends depuis dix minutes.", "options": ["en", "lui", "y", "l'"], "a": 3, "trap": "lui — English says «I'm waiting FOR the bus», which makes it feel indirect", "expl": "« Attendre » takes a direct object with no preposition, so the bus becomes l' (le before a vowel)."}, {"id": "gr-pronouns-B1-02", "level": "B1", "format": "cloze", "q": "Je téléphone à ma cheffe d'unité tous les lundis. → Je ___ téléphone tous les lundis.", "options": ["l'", "la", "lui", "y"], "a": 2, "trap": "la — she is a woman, so learners hunt for a feminine pronoun; lui covers both genders", "expl": "« Téléphoner À quelqu'un » is indirect, so lui — the same form for him and for her."}, {"id": "gr-pronouns-B1-03", "level": "B1", "format": "cloze", "q": "Tu connais ce dossier ? — Oui, je ___ connais bien.", "options": ["lui", "le", "y", "en"], "a": 1, "trap": "en — « connaître » looks like it needs « de » because English says «know about it»", "expl": "« Connaître quelque chose » is direct: a masculine noun becomes le."}, {"id": "gr-pronouns-B1-04", "level": "B1", "format": "cloze", "q": "Elle écrit à ses collègues du secrétariat. → Elle ___ écrit ce soir.", "options": ["leur", "les", "y", "en"], "a": 0, "trap": "les — English «she writes them» has no preposition, so it feels direct", "expl": "« Écrire à quelqu'un » is indirect; for several people the pronoun is leur, with no -s."}, {"id": "gr-pronouns-B1-05", "level": "B1", "format": "cloze", "q": "Tu vas à la commune de Schaerbeek demain ? — Oui, j'___ vais vers neuf heures.", "options": ["lui", "en", "le", "y"], "a": 3, "trap": "en — learners mix up the two little pronouns; en is « de », y is « à »", "expl": "Y stands for « à » plus a place. « Oui, je vais » on its own is not possible in French."}, {"id": "gr-pronouns-B1-06", "level": "B1", "format": "cloze", "q": "Vous avez besoin du rapport annuel ? — Oui, j'___ ai besoin pour lundi.", "options": ["le", "y", "en", "lui"], "a": 2, "trap": "le — «I need it» in English makes the report look like a direct object", "expl": "« Avoir besoin DE » — the de forces en, whatever the English does."}, {"id": "gr-pronouns-B1-07", "level": "B1", "format": "cloze", "q": "Son nom ? Je ne ___ vois pas sur la liste des participants.", "options": ["lui", "le", "y", "en"], "a": 1, "trap": "lui — the sentence mentions a person, but what you cannot see is his NAME", "expl": "« Voir quelque chose » is direct, and in the negative ne … pas wraps around le vois."}, {"id": "gr-pronouns-B1-08", "level": "B1", "format": "collocation", "q": "Which sentence puts the pronoun in the right place? (Ce formulaire, je vais…)", "options": ["Je vais le remplir demain.", "Je le vais remplir demain.", "Je vais remplir le demain.", "Je vais remplir-le demain."], "a": 0, "trap": "Je vais remplir le — exactly where English puts «it»", "expl": "The pronoun goes in front of the verb it belongs to, and here that verb is the infinitive remplir."}, {"id": "gr-pronouns-B1-09", "level": "B1", "format": "cloze", "q": "Tu prends du café à la machine ? — Oui, j'___ prends un avant la réunion.", "options": ["la", "y", "le", "en"], "a": 3, "trap": "le — the partitive « du café » is not « le café », and only en can replace it", "expl": "Du / de la / des all hide a « de », so the pronoun is en; the quantity « un » stays at the end."}], "drills": [{"id": "gd-pronouns-B1-01", "level": "B1", "format": "cloze", "q": "Ces documents sont prêts : je ___ envoie ce soir au secrétariat.", "options": ["y", "leur", "les", "en"], "a": 2, "trap": "leur — you send TO people, but here the documents are what is sent", "expl": "The documents are the direct object of envoyer, so les. Leur would be the people receiving them."}, {"id": "gd-pronouns-B1-02", "level": "B1", "format": "cloze", "q": "J'ai croisé Madame Peeters dans le couloir et je ___ ai dit bonjour.", "options": ["l'", "lui", "la", "y"], "a": 1, "trap": "l' — «I said hello to her» collapses in English to «I greeted her»", "expl": "« Dire quelque chose À quelqu'un »: bonjour is the direct object, the person is indirect → lui."}, {"id": "gd-pronouns-B1-03", "level": "B1", "format": "cloze", "q": "Ce rapport est urgent : le chef d'unité ___ a demandé pour vendredi.", "options": ["l'", "lui", "y", "en"], "a": 0, "trap": "lui — « demander à » is indirect, but only for the PERSON you ask", "expl": "You ask a person (lui) FOR a thing (le / l'). Here it is the report that was asked for."}, {"id": "gd-pronouns-B1-04", "level": "B1", "format": "cloze", "q": "Tes collègues attendent ta note depuis mardi. Ne ___ fais pas attendre plus longtemps !", "options": ["en", "leur", "y", "les"], "a": 3, "trap": "leur — a plural of people almost always pulls learners towards leur", "expl": "« Attendre quelqu'un » is direct, so les. Leur only appears with verbs that need « à »."}, {"id": "gd-pronouns-B1-05", "level": "B1", "format": "cloze", "q": "Je pense souvent à mon entretien EPSO. → J'___ pense souvent.", "options": ["le", "en", "y", "lui"], "a": 2, "trap": "en — English «think about» feels like «of», which pulls towards en", "expl": "« Penser À » plus a thing gives y. Only « parler de » type verbs give en."}, {"id": "gd-pronouns-B1-06", "level": "B1", "format": "cloze", "q": "Tu as parlé du problème de personnel à la réunion ? — Oui, j'___ ai parlé ce matin.", "options": ["y", "en", "le", "lui"], "a": 1, "trap": "le — «I talked about it» tempts a direct object in English", "expl": "« Parler DE quelque chose » → en. « Parler À quelqu'un » would give lui."}, {"id": "gd-pronouns-B1-07", "level": "B1", "format": "collocation", "q": "Which sentence is correct French for «I'm not going to answer him today»?", "options": ["Je ne vais pas lui répondre aujourd'hui.", "Je ne lui vais pas répondre aujourd'hui.", "Je ne vais lui pas répondre aujourd'hui.", "Je vais ne lui pas répondre aujourd'hui."], "a": 0, "trap": "Je ne lui vais pas répondre — the pronoun looks like it should hug the conjugated verb", "expl": "Ne … pas wraps the conjugated verb (vais); the pronoun belongs to the infinitive and travels with it."}, {"id": "gd-pronouns-B1-08", "level": "B1", "format": "cloze", "q": "Vous connaissez ce règlement intérieur ? — Non, je ne ___ connais pas très bien.", "options": ["en", "lui", "y", "le"], "a": 3, "trap": "y — a rule feels like something you refer «to», which suggests à", "expl": "Connaître is directly transitive: le. In the negative the pronoun stays inside ne … pas."}, {"id": "gd-pronouns-B1-09", "level": "B1", "format": "cloze", "q": "Il y a combien de réunions cette semaine ? — Il ___ a trois.", "options": ["y", "en y", "y en", "en"], "a": 2, "trap": "en y — the order feels arbitrary, so learners guess", "expl": "« Il y a » keeps its y, and the quantity adds en: y always comes before en. The number stays at the end."}, {"id": "gd-pronouns-B1-10", "level": "B1", "format": "collocation", "q": "Which sentence is correct French for «I often think about my sister»?", "options": ["J'y pense souvent.", "Je pense souvent à elle.", "Je lui pense souvent.", "J'en pense souvent."], "a": 1, "trap": "J'y pense souvent — the sentence has « à », so y looks automatic", "expl": "Y never replaces a person. After penser à, a person stays as « à » plus a stressed pronoun: à elle, à lui, à eux."}, {"id": "gd-pronouns-B1-11", "level": "B1", "format": "cloze", "q": "Ce formulaire de changement d'adresse ? Il faut ___ remplir sur internet, pas au guichet.", "options": ["le", "lui", "y", "en"], "a": 0, "trap": "y — « sur internet » names a place, which makes y feel right", "expl": "The pronoun replaces the form, the direct object of remplir, and sits in front of that infinitive."}, {"id": "gd-pronouns-B1-12", "level": "B1", "format": "cloze", "q": "Tu as répondu au mail du chef d'unité ? — Oui, j'___ ai répondu hier soir.", "options": ["lui", "en", "l'", "y"], "a": 3, "trap": "l' — English «I answered it» has no preposition at all", "expl": "« Répondre À quelque chose » → y. If you had answered the person, it would be « je lui ai répondu »."}, {"id": "gd-pronouns-B1-13", "level": "B1", "format": "cloze", "q": "Vous avez des tickets STIB ? — Oui, j'___ ai deux dans mon portefeuille.", "options": ["les", "y", "en", "le"], "a": 2, "trap": "les — with a plural noun already mentioned, les looks like the obvious pronoun", "expl": "As soon as a number answers the question, French needs en: « j'en ai deux ». « J'ai deux » is impossible."}, {"id": "gd-pronouns-B1-14", "level": "B1", "format": "cloze", "q": "Cette nouvelle collègue du service juridique ? Je ne ___ connais pas encore.", "options": ["lui", "la", "y", "en"], "a": 1, "trap": "lui — a person in the sentence makes lui look safe", "expl": "Connaître is direct, so a feminine person becomes la. Lui only follows verbs built with « à »."}, {"id": "gd-pronouns-B1-15", "level": "B1", "format": "cloze", "q": "Tu dois envoyer la note au chef d'unité avant midi. → Tu dois ___ envoyer la note avant midi.", "options": ["lui", "le", "la", "y"], "a": 0, "trap": "le — learners reach for a masculine pronoun because the chef is a man", "expl": "The note stays in the sentence, so only the person is replaced: « envoyer à quelqu'un » → lui."}, {"id": "gd-pronouns-B1-16", "level": "B1", "format": "collocation", "q": "Which sentence is correct French for «I phoned him this morning»?", "options": ["Je lui téléphoné ai ce matin.", "J'ai lui téléphoné ce matin.", "J'ai téléphoné lui ce matin.", "Je lui ai téléphoné ce matin."], "a": 3, "trap": "J'ai lui téléphoné — English puts the pronoun after the auxiliary «have»", "expl": "In a compound tense the pronoun goes in front of the auxiliary, never between avoir and the participle."}, {"id": "gd-pronouns-B1-17", "level": "B1", "format": "cloze", "q": "Notre bureau ferme à dix-sept heures — chacun ___ sait déjà.", "options": ["en", "y", "le", "lui"], "a": 2, "trap": "y — there is a place in the sentence, so y looks tempting", "expl": "This is the neutral le: it stands for the whole fact, not for a noun. « Chacun sait » without le sounds unfinished in writing."}], "write": [{"id": "gw-pronouns-B1-01", "prompt": "Rewrite with a pronoun: J'attends le bus 71.", "answer": "Je l'attends.", "accept": ["je l'attends"], "hint": "attendre takes no preposition", "expl": "Direct object, masculine, in front of a vowel → l'."}, {"id": "gw-pronouns-B1-02", "prompt": "Rewrite with a pronoun: Je téléphone à Madame Peeters.", "answer": "Je lui téléphone.", "accept": ["je lui téléphone"], "hint": "téléphoner À quelqu'un", "expl": "Indirect object: lui, for a woman as much as for a man."}, {"id": "gw-pronouns-B1-03", "prompt": "Rewrite with a pronoun: Elle écrit à ses collègues.", "answer": "Elle leur écrit.", "accept": ["elle leur écrit"], "hint": "several people, indirect", "expl": "Écrire à → leur, and the pronoun leur never takes an -s."}, {"id": "gw-pronouns-B1-04", "prompt": "Rewrite with a pronoun: Je vais à la commune de Schaerbeek.", "answer": "J'y vais.", "accept": ["j'y vais"], "hint": "à + a place", "expl": "Y replaces à plus a place, and it cannot be left out."}, {"id": "gw-pronouns-B1-05", "prompt": "Rewrite with a pronoun: Nous avons besoin de ce rapport.", "answer": "Nous en avons besoin.", "accept": ["nous en avons besoin", "on en a besoin"], "hint": "avoir besoin DE", "expl": "The de in the expression forces en, in front of the verb."}, {"id": "gw-pronouns-B1-06", "prompt": "Say in French, using a pronoun for « le dossier »: I don't see it on the list.", "answer": "Je ne le vois pas sur la liste.", "accept": ["je ne le vois pas sur la liste"], "hint": "ne … pas wraps around pronoun + verb", "expl": "Order: ne + pronoun + verb + pas."}, {"id": "gw-pronouns-B1-07", "prompt": "Say in French, using a pronoun for « la note »: I'm going to send it this evening.", "answer": "Je vais l'envoyer ce soir.", "accept": ["je vais l'envoyer ce soir"], "hint": "the pronoun belongs to the infinitive", "expl": "« Je vais envoyer la » is the classic English word order and is wrong."}, {"id": "gw-pronouns-B1-08", "prompt": "Say in French: I'm not going to answer him today.", "answer": "Je ne vais pas lui répondre aujourd'hui.", "accept": ["je ne vais pas lui répondre aujourd'hui"], "hint": "répondre À quelqu'un", "expl": "Ne … pas wraps vais; lui stays with répondre."}, {"id": "gw-pronouns-B1-09", "prompt": "Answer with a pronoun — Vous avez des tickets STIB ? (three)", "answer": "Oui, j'en ai trois.", "accept": ["oui j'en ai trois", "j'en ai trois"], "hint": "a number always needs en", "expl": "En in front of the verb, the number at the end."}, {"id": "gw-pronouns-B1-10", "prompt": "Rewrite with a pronoun: Je pense à la réunion de jeudi.", "answer": "J'y pense.", "accept": ["j'y pense"], "hint": "penser À plus a thing", "expl": "A thing after à becomes y."}, {"id": "gw-pronouns-B1-11", "prompt": "Rewrite with a pronoun: Je pense à mon collègue Marc.", "answer": "Je pense à lui.", "accept": ["je pense à lui"], "hint": "penser à plus a person is the exception", "expl": "Penser à keeps « à » plus a stressed pronoun for people: à lui, à elle, à eux."}, {"id": "gw-pronouns-B1-12", "prompt": "Rewrite with a pronoun: J'ai répondu au mail du secrétariat.", "answer": "J'y ai répondu.", "accept": ["j'y ai répondu"], "hint": "répondre à + a thing, passé composé", "expl": "Y for à plus a thing, and it goes before the auxiliary ai."}], "apply": [{"id": "ga-pronouns-B1-01", "situation": "Your head of unit asks whether you have phoned the colleagues at the Council secretariat. You did, this morning.", "task": "Answer in one sentence, replacing « les collègues du secrétariat » with a pronoun.", "accept": ["oui je leur ai téléphoné ce matin", "je leur ai téléphoné ce matin", "oui je leur ai téléphoné", "je leur ai téléphoné", "oui je leur ai déjà téléphoné", "je leur ai déjà téléphoné ce matin", "oui je leur ai téléphoné ce matin même"], "model": "Oui, je leur ai téléphoné ce matin.", "expl": "Téléphoner À quelqu'un → leur for several people, placed before the auxiliary ai."}, {"id": "ga-pronouns-B1-02", "situation": "A colleague asks if you are going to the commune of Ixelles tomorrow to collect a certificate.", "task": "Say yes and give a time, using a pronoun instead of repeating « à la commune ».", "accept": ["oui j'y vais demain matin", "j'y vais demain matin", "oui j'y vais demain", "j'y vais demain", "oui j'y vais vers neuf heures", "j'y vais vers dix heures", "oui j'y vais demain vers neuf heures"], "model": "Oui, j'y vais demain matin.", "expl": "Y replaces « à la commune ». Dropping it — « oui, je vais demain » — is not possible in French."}, {"id": "ga-pronouns-B1-03", "situation": "At the STIB counter at Bruxelles-Midi, the clerk asks whether you still have any tickets.", "task": "Say you have none left, using a pronoun.", "accept": ["non je n'en ai plus", "je n'en ai plus", "non il ne m'en reste plus", "il ne m'en reste plus", "non je n'en ai plus aucun", "non je n'en ai pas"], "model": "Non, je n'en ai plus.", "expl": "Quantity zero still needs en: « je n'en ai plus ». « Je n'ai plus » on its own is incomplete."}, {"id": "ga-pronouns-B1-04", "situation": "Your head of unit has already mentioned the summary note. You want to say when you will send it.", "task": "Write one sentence saying you are going to send it this evening, using a pronoun.", "accept": ["je vais l'envoyer ce soir", "je l'envoie ce soir", "je vais l'envoyer ce soir même", "je vais l'envoyer avant ce soir", "je l'envoie avant ce soir", "je vais vous l'envoyer ce soir"], "model": "Je vais l'envoyer ce soir.", "expl": "The pronoun goes in front of the infinitive envoyer, not after it."}, {"id": "ga-pronouns-B1-05", "situation": "A colleague asks whether you have read the dossier for tomorrow's working party. You have not yet.", "task": "Answer in one sentence with a pronoun.", "accept": ["non je ne l'ai pas encore lu", "je ne l'ai pas encore lu", "non pas encore je ne l'ai pas lu", "non je ne l'ai pas lu", "je ne l'ai pas lu pour l'instant", "non je vais le lire ce soir"], "model": "Non, je ne l'ai pas encore lu.", "expl": "In the passé composé the pronoun sits before the auxiliary, inside ne … pas."}, {"id": "ga-pronouns-B1-06", "situation": "In a meeting, someone asks how many candidates are on the reserve list. There are twelve.", "task": "Answer in one short sentence, using the right pronouns.", "accept": ["il y en a douze", "il y en a 12", "il y en a douze sur la liste", "je crois qu'il y en a douze", "il y en a douze pour le moment", "il y en a actuellement douze"], "model": "Il y en a douze.", "expl": "« Il y a » keeps y, and the quantity brings en: y before en, number at the end."}]},
  "pronouns-B2": {"slug": "pronouns", "level": "B2", "title": "Les pronoms compléments — deux pronoms, impératif, accord", "summary": "Two pronouns in one sentence and their fixed order, the imperative, past-participle agreement with a preceding direct object, and en with quantities.", "why": "This is where a note stops sounding translated. « Je vous les transmettrai dès que possible », « je le lui ai signalé », « les délais que le Conseil avait fixés » — an EPSO written test rewards exactly these, and an examiner spots a missing agreement or a reversed pronoun order in one reading.", "lesson": [{"id": "gl-pronouns-B2-01", "heading": "Two pronouns at once — the order is fixed, and it is not the English one", "body": "When two pronouns meet in front of the verb, French uses one fixed sequence: me/te/se/nous/vous, then le/la/les, then lui/leur, then y, then en. Read the table left to right and take at most one item from each column. English says «give it to me», thing first; French says « donne-le-moi » only in the imperative — everywhere else it is « il me le donne », person first. The rule of thumb that actually works: a first- or second-person pronoun (me, te, nous, vous) always comes first; but when both pronouns are third person, the thing comes before the person — « je le lui donne », never « je lui le donne ». One combination is simply banned: me/te/nous/vous can never sit next to lui/leur. « Il me leur a présenté » does not exist; French says « il m'a présenté à eux », with the person as a stressed pronoun after the verb.", "table": {"cols": ["Position", "Pronouns", "Example"], "rows": [["1", "me, te, se, nous, vous", "il me le donne / je te le prépare"], ["2", "le, la, les", "je le lui donne"], ["3", "lui, leur", "je le lui donne / je les leur envoie"], ["4", "y", "je t'y retrouve"], ["5", "en", "il y en a trois / je lui en parle"]]}, "examples": [{"fr": "Le chef d'unité veut la note traduite : je la lui envoie avant midi.", "en": "The head of unit wants the note translated: I'm sending it to him before midday.", "gloss": {"la lui envoie": "am sending it to him", "traduite": "translated"}, "note": "Both third person, so thing (la) before person (lui)."}, {"fr": "Tu me demandes le dossier ? D'accord, je te le prépare pour ce soir.", "en": "You're asking me for the file? Fine, I'll get it ready for you tonight.", "gloss": {"te le prépare": "am getting it ready for you"}, "note": "A second-person pronoun always goes first: te le, never le te."}, {"fr": "Des places pour la formation ? Il y en a encore trois.", "en": "Places on the training course? There are still three left.", "gloss": {"y en": "there … of them"}, "note": "Y always precedes en, and en is always last of all."}, {"fr": "Il m'a présenté à eux au début de la réunion.", "en": "He introduced me to them at the start of the meeting.", "gloss": {"m'a présenté": "introduced me", "à eux": "to them"}, "note": "« Il me leur a présenté » is impossible: me/te/nous/vous never meet lui/leur."}]}, {"id": "gl-pronouns-B2-02", "heading": "Where the pair sits: compound tenses, infinitives, negatives", "body": "The pair never splits. In the passé composé both pronouns go in front of the auxiliary: « je le lui ai donné ». With an infinitive both go in front of the infinitive: « je vais le lui donner ». In the negative, ne … pas closes around the conjugated verb with the pronouns inside: « je ne le lui ai pas donné », « je ne vais pas le lui donner ». The English-speaker error is to strand one of them — « je le vais lui donner », or « je vais lui le donner » — usually because English can put «it» and «to him» on either side of the verb.", "table": {"cols": ["Structure", "French", "English"], "rows": [["present", "je le lui donne", "I give it to him"], ["passé composé", "je le lui ai donné", "I gave it to him"], ["negative passé composé", "je ne le lui ai pas donné", "I didn't give it to him"], ["+ infinitive", "je vais le lui donner", "I'm going to give it to him"], ["negative + infinitive", "je ne vais pas le lui donner", "I'm not going to give it to him"], ["affirmative imperative", "donnez-le-lui", "give it to him"], ["negative imperative", "ne le lui donnez pas", "don't give it to him"]]}, "examples": [{"fr": "Ces notes, je les lui ai transmises hier après la réunion du groupe de travail.", "en": "Those notes — I passed them on to him yesterday after the working party meeting.", "gloss": {"les lui ai transmises": "passed them on to him", "groupe de travail": "working party"}, "note": "Both pronouns before the auxiliary, and transmises agrees with les."}, {"fr": "Je ne vais pas le lui annoncer par mail : je préfère lui téléphoner.", "en": "I'm not going to tell him by email: I'd rather phone him.", "gloss": {"le lui annoncer": "tell him (it)"}, "note": "Both pronouns travel together to the front of the infinitive."}]}, {"id": "gl-pronouns-B2-03", "heading": "The imperative — the only place pronouns go after the verb", "body": "In an affirmative order the pronouns move behind the verb, joined by hyphens, and me/te become moi/toi: « Donnez-le-moi ». In that position the order flips to the English one: direct object first, then the person — « envoyez-la-nous », « dis-le-lui ». The moment the order becomes negative, everything snaps back to the normal pre-verb order with me and te restored: « Ne me le donnez pas ». Two spelling details worth knowing because they look like typos: moi + en contracts to m'en (« donnez-m'en deux »), and an -er verb takes back its -s in front of y or en (« vas-y », « parles-en au chef »). The English-speaker error is to write « donnez-moi-le » — logical, since English says «give me it», but not French.", "table": {"cols": ["", "Affirmative", "Negative"], "rows": [["one pronoun", "donnez-le", "ne le donnez pas"], ["me → moi", "donnez-le-moi", "ne me le donnez pas"], ["two third-person", "dites-le-lui", "ne le lui dites pas"], ["with nous", "envoyez-la-nous", "ne nous l'envoyez pas"], ["moi + en → m'en", "donnez-m'en deux", "ne m'en donnez pas"], ["-er verb + y / en", "vas-y, parles-en", "n'y va pas, n'en parle pas"]]}, "examples": [{"fr": "La version finale, envoyez-la-moi dès qu'elle est prête, s'il vous plaît.", "en": "The final version — send it to me as soon as it's ready, please.", "gloss": {"envoyez-la-moi": "send it to me", "dès qu'elle est prête": "as soon as it's ready"}, "note": "Direct object first, then the person, all hyphenated."}, {"fr": "Ce chiffre n'est pas encore public : ne le leur communiquez pas avant vendredi.", "en": "That figure isn't public yet: don't pass it on to them before Friday.", "gloss": {"le leur communiquez": "pass it on to them", "chiffre": "figure"}, "note": "Negative imperative = ordinary order, in front of the verb."}, {"fr": "Il reste des exemplaires du rapport ? Donnez-m'en deux, s'il vous plaît.", "en": "Are there copies of the report left? Give me two, please.", "gloss": {"Donnez-m'en": "give me … of them", "exemplaires": "copies"}, "note": "Moi + en is written m'en; the number stays at the end."}]}, {"id": "gl-pronouns-B2-04", "heading": "Past-participle agreement with a preceding direct object", "body": "With avoir the participle normally does not move: « j'ai reçu les notes ». But if the direct object has been moved in FRONT of the verb, the participle agrees with it in gender and number. There are only three ways an object gets in front: as a pronoun (« je les ai reçues »), as the relative que (« les notes que j'ai reçues »), or in a question with quel (« quelles notes avez-vous reçues ? »). Two checks that stop most mistakes. An indirect object never triggers agreement: « je leur ai téléphoné », never téléphonés. And en never triggers it either: « des candidatures, nous en avons reçu plus de cent » — reçu stays flat. The English-speaker error is agreeing with the subject («elle a reçue») or agreeing with everything in sight; the question to ask is only ever whether a DIRECT object stands to the left of the participle.", "table": {"cols": ["Sentence", "Object", "Agreement?", "Why"], "rows": [["j'ai reçu les notes", "after the verb", "no → reçu", "nothing precedes"], ["je les ai reçues", "les, before", "yes → reçues", "preceding direct object"], ["les notes que j'ai reçues", "que, before", "yes → reçues", "que is the direct object"], ["quelles notes avez-vous reçues ?", "quelles notes, before", "yes → reçues", "fronted direct object"], ["je leur ai téléphoné", "leur, indirect", "no → téléphoné", "indirect objects never agree"], ["j'en ai reçu trois", "en", "no → reçu", "en never triggers agreement"], ["elle a signé le document", "after the verb", "no → signé", "the subject is irrelevant with avoir"]]}, "examples": [{"fr": "Les notes du groupe de travail ? Je les ai reçues ce matin et je les ai déjà lues.", "en": "The working party's notes? I got them this morning and I've already read them.", "gloss": {"les ai reçues": "received them", "les ai déjà lues": "have already read them"}, "note": "Feminine plural object in front, so reçues and lues both take -es."}, {"fr": "Les délais que le Conseil avait fixés n'ont pas été respectés.", "en": "The deadlines the Council had set were not met.", "gloss": {"délais": "deadlines", "fixés": "set"}, "note": "Que stands for « les délais », masculine plural, so fixés."}, {"fr": "Des candidatures, nous en avons reçu plus de cent cette année.", "en": "Applications — we've had more than a hundred this year.", "gloss": {"en avons reçu": "have received … of them"}, "note": "En blocks agreement: reçu, never reçues."}, {"fr": "Je leur ai écrit lundi, mais ils ne m'ont pas encore répondu.", "en": "I wrote to them on Monday, but they haven't answered me yet.", "gloss": {"leur ai écrit": "wrote to them", "m'ont pas encore répondu": "haven't answered me yet"}, "note": "Both objects are indirect, so both participles stay flat."}]}, {"id": "gl-pronouns-B2-05", "heading": "en with quantities and expressions of quantity", "body": "Whenever a number or a quantity word answers the question, French keeps en in front of the verb and leaves the quantity at the end: « J'en ai trois », « il en reste beaucoup », « nous en avons reçu une vingtaine ». It works the same with an adjective (« j'en ai une autre »), with assez and trop (« j'en ai assez »), and in questions (« Combien en voulez-vous ? »). The English error is simply dropping en, because English says «I have three» with nothing in the middle; « j'ai trois » is not a sentence. In Belgium you will hear the quantity itself said differently — septante and nonante rather than soixante-dix and quatre-vingt-dix — but the pronoun rule is identical: « il y en a nonante ».", "table": {"cols": ["Question", "Answer", "Note"], "rows": [["Vous avez combien de dossiers ?", "J'en ai trois.", "number at the end"], ["Il reste des places ?", "Il en reste beaucoup.", "quantity word at the end"], ["Vous voulez d'autres copies ?", "Oui, j'en veux une autre.", "adjective after en"], ["Combien de réponses ?", "Nous en avons reçu nonante.", "Belgian nonante = 90"], ["Vous avez assez de temps ?", "Non, je n'en ai pas assez.", "negative keeps en inside ne … pas"]]}, "examples": [{"fr": "Combien de dossiers avez-vous traités cette semaine ? — J'en ai traité douze.", "en": "How many files have you handled this week? — I've handled twelve.", "gloss": {"en ai traité": "handled … of them", "traités": "handled"}, "note": "Agreement in the question (traités, after « combien de dossiers »), none after en."}, {"fr": "Il y a encore des places pour la formation linguistique ? — Il y en a nonante.", "en": "Are there still places on the language training? — There are ninety.", "gloss": {"y en a": "there are … of them", "nonante": "ninety (Belgian French)"}, "note": "In France you would hear quatre-vingt-dix; in Brussels, nonante."}]}, {"id": "gl-pronouns-B2-06", "heading": "What this buys you in a note", "body": "Pronouns are not decoration in administrative French: they are how you avoid repeating a noun that the reader already has in mind, which is precisely what an EPSO marker means by cohesion. Compare a B1 paragraph with its B2 rewrite and you will see two nouns disappear and the sentence get shorter, not vaguer. The one caution: a pronoun must have exactly one possible antecedent. If a paragraph has mentioned both « la note » and « la proposition », « je vous la transmets » is ambiguous and you must name the noun again — clarity beats elegance in a note.", "table": {"cols": ["B1 version", "B2 rewrite"], "rows": [["J'ai reçu les conclusions. Je vais envoyer les conclusions au chef d'unité.", "J'ai reçu les conclusions ; je les lui transmets aujourd'hui."], ["Nous avons parlé du problème au chef d'unité.", "Nous lui en avons parlé."], ["Envoyez la version finale à moi quand elle est prête.", "Envoyez-la-moi dès qu'elle est prête."], ["Il y a douze candidats sur la liste de réserve.", "Il y en a douze."]]}, "examples": [{"fr": "J'ai reçu les conclusions du groupe de travail ; je vous les transmets dès qu'elles sont traduites.", "en": "I have received the working party's conclusions; I'll pass them on to you as soon as they are translated.", "gloss": {"vous les transmets": "pass them on to you", "dès qu'elles sont traduites": "as soon as they are translated"}, "note": "Vous before les — a second-person pronoun always comes first."}, {"fr": "Le problème de délai a été signalé au chef d'unité : nous lui en avons parlé mardi.", "en": "The deadline problem has been flagged to the head of unit: we spoke to him about it on Tuesday.", "gloss": {"lui en avons parlé": "spoke to him about it", "délai": "deadline"}, "note": "Lui before en — en is always the last pronoun of the group."}]}], "recognise": [{"id": "gr-pronouns-B2-01", "level": "B2", "format": "cloze", "q": "Tu me passes le dossier ? — Oui, je ___ passe tout de suite.", "options": ["le lui", "le te", "lui le", "te le"], "a": 3, "trap": "le te — English «I'll pass it to you» puts the thing first", "expl": "Me/te/nous/vous always come before le/la/les."}, {"id": "gr-pronouns-B2-02", "level": "B2", "format": "cloze", "q": "Ces documents, le chef d'unité les attendait : je ___ ai envoyés hier.", "options": ["leur les", "lui les", "les lui", "les leurs"], "a": 2, "trap": "lui les — person first feels natural because that is what happens with me and te", "expl": "Two third-person pronouns: the thing comes first, so les lui."}, {"id": "gr-pronouns-B2-03", "level": "B2", "format": "collocation", "q": "You want the file handed to you now. Which order is correct?", "options": ["Donnez-moi-le maintenant.", "Donnez-le-moi maintenant.", "Me le donnez maintenant.", "Donnez-me-le maintenant."], "a": 1, "trap": "Donnez-moi-le — English «give me it» in French clothes", "expl": "In an affirmative imperative the direct object comes first and me becomes moi: donnez-le-moi."}, {"id": "gr-pronouns-B2-04", "level": "B2", "format": "cloze", "q": "C'est encore confidentiel : ne ___ communiquez pas avant vendredi.", "options": ["me le", "le me", "moi le", "le moi"], "a": 0, "trap": "le moi — learners keep the imperative order they have just learnt", "expl": "A negative imperative goes back to the normal pre-verb order, and moi becomes me again."}, {"id": "gr-pronouns-B2-05", "level": "B2", "format": "cloze", "q": "Les notes du groupe de travail ? Je les ai ___ ce matin.", "options": ["reçue", "reçu", "reçus", "reçues"], "a": 3, "trap": "reçu — the flat form is right after avoir in most sentences", "expl": "Les stands for « les notes », a direct object placed before the verb, so the participle agrees: reçues."}, {"id": "gr-pronouns-B2-06", "level": "B2", "format": "cloze", "q": "Mes collègues attendaient une réponse : je leur ai ___ hier soir.", "options": ["téléphonée", "téléphonés", "téléphoné", "téléphonées"], "a": 2, "trap": "téléphonés — a plural pronoun in front makes agreement look automatic", "expl": "Leur is an indirect object, and indirect objects never cause agreement."}, {"id": "gr-pronouns-B2-07", "level": "B2", "format": "cloze", "q": "Des candidats sur la liste de réserve ? Il ___ a nonante.", "options": ["en y", "y en", "y", "en"], "a": 1, "trap": "en y — the two small pronouns are easy to swap", "expl": "Y always precedes en, and « il y a » keeps its y. Nonante is Belgian for ninety."}, {"id": "gr-pronouns-B2-08", "level": "B2", "format": "cloze", "q": "Combien de dossiers avez-vous traités ? — J'___ ai traité douze.", "options": ["en", "y", "les", "le"], "a": 0, "trap": "les — the dossiers are plural and already known, so les looks right", "expl": "A number in the answer forces en. Note that after en the participle stays flat: traité."}, {"id": "gr-pronouns-B2-09", "level": "B2", "format": "collocation", "q": "Which imperative is correctly written?", "options": ["Vas-en tout de suite !", "Va-y tout de suite !", "Y va tout de suite !", "Vas-y tout de suite !"], "a": 3, "trap": "Va-y — the tu imperative of aller really is « va », so the extra -s looks wrong", "expl": "An -er verb takes its -s back in front of y or en: vas-y, parles-en, manges-en."}], "drills": [{"id": "gd-pronouns-B2-01", "level": "B2", "format": "cloze", "q": "Le chef d'unité veut la note traduite. Je vais ___ envoyer avant midi.", "options": ["le lui", "lui la", "la lui", "la leur"], "a": 2, "trap": "lui la — putting the person first, which is right with me/te but wrong here", "expl": "Two third-person pronouns: le/la/les first, lui/leur second. Both go in front of the infinitive."}, {"id": "gd-pronouns-B2-02", "level": "B2", "format": "cloze", "q": "Tu as parlé du problème de délai à tes collègues ? — Oui, je ___ ai parlé ce matin.", "options": ["en leur", "leur en", "les en", "leur y"], "a": 1, "trap": "en leur — en feels like it should be next to parler, its own verb", "expl": "En is always the last pronoun of the group, so leur en. « Parler DE quelque chose À quelqu'un »."}, {"id": "gd-pronouns-B2-03", "level": "B2", "format": "cloze", "q": "Il reste des places pour la formation linguistique ? — Oui, il ___ reste trois.", "options": ["y en", "en y", "en", "y"], "a": 0, "trap": "en on its own — « il reste » looks impersonal enough without y", "expl": "« Il y reste » plus a quantity gives il y en reste: y before en, the number at the end."}, {"id": "gd-pronouns-B2-04", "level": "B2", "format": "cloze", "q": "Les journalistes réclament ces chiffres, mais ils sont sous embargo : ne ___ communiquez pas avant vendredi.", "options": ["leur en", "leur les", "les leurs", "les leur"], "a": 3, "trap": "leur les — putting the person first, which is only right with me/te/nous/vous", "expl": "Direct object before indirect object in front of the verb, and a negative imperative keeps them there."}, {"id": "gd-pronouns-B2-05", "level": "B2", "format": "collocation", "q": "There are copies of the report left and you want two. Which is correct?", "options": ["Donnez-me-en deux, s'il vous plaît.", "Donnez-moi-en deux, s'il vous plaît.", "Donnez-m'en deux, s'il vous plaît.", "Donnez-en-moi deux, s'il vous plaît."], "a": 2, "trap": "Donnez-moi-en — the regular imperative form of moi, which contracts here", "expl": "Moi + en is always written m'en: donnez-m'en, apportez-m'en, envoyez-m'en."}, {"id": "gd-pronouns-B2-06", "level": "B2", "format": "cloze", "q": "Les remarques que le chef d'unité m'a ___ sur la note sont utiles.", "options": ["fait", "faites", "faits", "faite"], "a": 1, "trap": "fait — the flat form after avoir, which is right whenever nothing precedes", "expl": "Que stands for « les remarques », feminine plural and direct, placed before the verb: faites."}, {"id": "gd-pronouns-B2-07", "level": "B2", "format": "cloze", "q": "Des candidatures pour ce poste, nous en avons ___ plus de cent.", "options": ["reçu", "reçues", "reçus", "reçue"], "a": 0, "trap": "reçues — « candidatures » is feminine plural, so agreement looks obligatory", "expl": "En never triggers agreement, however plural the noun behind it is."}, {"id": "gd-pronouns-B2-08", "level": "B2", "format": "cloze", "q": "Quelles conclusions le groupe de travail a-t-il ___ de cette évaluation ?", "options": ["tirée", "tiré", "tirés", "tirées"], "a": 3, "trap": "tiré — in a question the object is easy to overlook", "expl": "« Quelles conclusions » is the direct object and stands in front of the verb, so the participle agrees."}, {"id": "gd-pronouns-B2-09", "level": "B2", "format": "cloze", "q": "La cheffe d'unité a ___ les documents ce matin avant la réunion.", "options": ["signées", "signés", "signé", "signée"], "a": 2, "trap": "signée — agreeing with the subject, which avoir never does", "expl": "The direct object comes after the verb, so no agreement at all: signé."}, {"id": "gd-pronouns-B2-10", "level": "B2", "format": "cloze", "q": "Les conclusions sont prêtes : je ___ enverrai dès qu'elles seront traduites.", "options": ["les vous", "vous les", "vous leur", "leur vous"], "a": 1, "trap": "les vous — English «send them to you» keeps the thing first", "expl": "Vous belongs to the first column, so it precedes les."}, {"id": "gd-pronouns-B2-11", "level": "B2", "format": "cloze", "q": "Rendez-vous devant le Berlaymont : je ___ retrouve à neuf heures.", "options": ["t'y", "y te", "te y", "y t'"], "a": 0, "trap": "y te — y feels like it belongs next to the place it replaces", "expl": "Te comes from column 1 and y from column 4, so te y — written t'y before a vowel."}, {"id": "gd-pronouns-B2-12", "level": "B2", "format": "collocation", "q": "Ask your assistant (vous) to send you and your team the final version. Which is correct?", "options": ["Envoyez-la-à-nous dès qu'elle est prête.", "Envoyez-nous-la dès qu'elle est prête.", "Nous l'envoyez dès qu'elle est prête.", "Envoyez-la-nous dès qu'elle est prête."], "a": 3, "trap": "Envoyez-nous-la — you hear it spoken, but the written standard is the other order", "expl": "In an affirmative imperative the direct object comes first: envoyez-la-nous, dites-le-lui, rendez-les-moi."}, {"id": "gd-pronouns-B2-13", "level": "B2", "format": "cloze", "q": "Le chef d'unité est en réunion toute la matinée : ne ___ parlez pas maintenant.", "options": ["le lui", "en lui", "lui en", "lui le"], "a": 2, "trap": "en lui — en looks as if it should stay glued to parler", "expl": "« Parler de quelque chose à quelqu'un » gives lui en, and a negative imperative keeps the pronouns in front."}, {"id": "gd-pronouns-B2-14", "level": "B2", "format": "collocation", "q": "Which sentence is correct French for «he introduced me to them»?", "options": ["Il me leur a présenté.", "Il m'a présenté à eux.", "Il leur m'a présenté.", "Il m'a présenté leur."], "a": 1, "trap": "Il me leur a présenté — it obeys the order table, but the combination itself is banned", "expl": "Me/te/nous/vous can never stand next to lui/leur; the person moves after the verb as « à eux »."}, {"id": "gd-pronouns-B2-15", "level": "B2", "format": "cloze", "q": "Combien de fois lui avez-vous ___ au sujet de ce dossier ?", "options": ["écrit", "écrits", "écrite", "écrites"], "a": 0, "trap": "écrits — a pronoun before the participle makes agreement look automatic", "expl": "Lui is indirect. Only a preceding DIRECT object causes agreement."}, {"id": "gd-pronouns-B2-16", "level": "B2", "format": "cloze", "q": "Le chef d'unité voulait ces notes de synthèse : je ___ ai transmises hier.", "options": ["leur les", "lui les", "les leur", "les lui"], "a": 3, "trap": "les leur — one head of unit, so the plural leur is wrong however plural the notes are", "expl": "Thing before person (les lui), and the participle agrees with les: transmises."}, {"id": "gd-pronouns-B2-17", "level": "B2", "format": "collocation", "q": "Vous voulez combien de copies ? Which answer is correct French?", "options": ["J'y veux trois, merci.", "Je veux trois, merci.", "J'en veux trois, merci.", "Je les veux trois, merci."], "a": 2, "trap": "Je veux trois — a word-for-word copy of «I want three»", "expl": "A quantity answer always keeps en in front of the verb; the number stays at the end."}], "write": [{"id": "gw-pronouns-B2-01", "prompt": "Rewrite with two pronouns: Je donne le dossier à Madame Peeters.", "answer": "Je le lui donne.", "accept": ["je le lui donne"], "hint": "both third person", "expl": "Thing before person: le lui."}, {"id": "gw-pronouns-B2-02", "prompt": "Rewrite with two pronouns: Il envoie les documents aux collègues du secrétariat.", "answer": "Il les leur envoie.", "accept": ["il les leur envoie"], "hint": "plural thing, plural person", "expl": "Les (direct) before leur (indirect)."}, {"id": "gw-pronouns-B2-03", "prompt": "Rewrite with two pronouns: Tu me montres la note de synthèse ?", "answer": "Tu me la montres ?", "accept": ["tu me la montres"], "hint": "me comes from the first column", "expl": "Me/te/nous/vous always precede le/la/les."}, {"id": "gw-pronouns-B2-04", "prompt": "Tell a colleague (vous) to send you the final version — affirmative imperative, two pronouns.", "answer": "Envoyez-la-moi.", "accept": ["envoyez-la-moi"], "hint": "hyphens, and me becomes moi", "expl": "Affirmative imperative: verb, direct object, then the person."}, {"id": "gw-pronouns-B2-05", "prompt": "Now the negative: tell them (vous) not to send it to you before Friday.", "answer": "Ne me l'envoyez pas avant vendredi.", "accept": ["ne me l'envoyez pas avant vendredi"], "hint": "negative imperative = ordinary order", "expl": "The pronouns go back in front of the verb and moi becomes me again."}, {"id": "gw-pronouns-B2-06", "prompt": "Ask for two of them (des exemplaires du rapport), speaking to a colleague as vous.", "answer": "Donnez-m'en deux.", "accept": ["donnez-m'en deux", "donnez-m'en deux s'il vous plaît"], "hint": "moi + en contracts", "expl": "Moi + en is written m'en, and the number stays at the end."}, {"id": "gw-pronouns-B2-07", "prompt": "Complete with the right participle form: les notes que j'ai ___ ce matin (recevoir).", "answer": "les notes que j'ai reçues ce matin", "accept": ["les notes que j'ai reçues ce matin", "les notes que j'ai reçues"], "hint": "que is a direct object standing in front", "expl": "Que stands for « les notes », feminine plural, so reçues."}, {"id": "gw-pronouns-B2-08", "prompt": "Rewrite with a pronoun: J'ai reçu les notes ce matin.", "answer": "Je les ai reçues ce matin.", "accept": ["je les ai reçues ce matin"], "hint": "the pronoun moves the object in front", "expl": "Preceding direct object → agreement: reçues."}, {"id": "gw-pronouns-B2-09", "prompt": "Rewrite with a pronoun: J'ai téléphoné aux collègues du secrétariat hier.", "answer": "Je leur ai téléphoné hier.", "accept": ["je leur ai téléphoné hier"], "hint": "indirect object", "expl": "Leur, and no agreement at all on téléphoné."}, {"id": "gw-pronouns-B2-10", "prompt": "Answer with a pronoun — Vous avez combien de dossiers en cours ? (three)", "answer": "J'en ai trois.", "accept": ["j'en ai trois"], "hint": "quantities need en", "expl": "En in front of the verb, the number at the end."}, {"id": "gw-pronouns-B2-11", "prompt": "Rewrite with a pronoun: Il reste trois places pour la formation.", "answer": "Il en reste trois.", "accept": ["il en reste trois"], "hint": "de + noun is hidden in « des places »", "expl": "En covers the noun, the number stays."}, {"id": "gw-pronouns-B2-12", "prompt": "Rewrite with two pronouns: Je vais parler du problème au chef d'unité.", "answer": "Je vais lui en parler.", "accept": ["je vais lui en parler"], "hint": "en is always last", "expl": "Lui (à + person) then en (de + thing), both in front of the infinitive."}], "apply": [{"id": "ga-pronouns-B2-01", "situation": "You are drafting a note to your head of unit. The working party's conclusions are with the translators.", "task": "Write one sentence saying you will forward them to him as soon as they are translated, using two pronouns.", "accept": ["je vous les transmettrai dès qu'elles seront traduites", "je vous les enverrai dès qu'elles seront traduites", "je vous les transmettrai dès qu'elles seront disponibles", "je vous les transmettrai dès leur traduction", "je vous les ferai parvenir dès qu'elles seront traduites", "je vous les transmets dès qu'elles sont traduites"], "model": "Je vous les transmettrai dès qu'elles seront traduites.", "expl": "Vous (column 1) before les (column 2). After « dès que » a future event takes the future in French, not the present."}, {"id": "ga-pronouns-B2-02", "situation": "A colleague asks how many replies the public consultation received. There were ninety-two.", "task": "Answer in one sentence with en, in Belgian French.", "accept": ["nous en avons reçu nonante-deux", "on en a reçu nonante-deux", "nous en avons reçu quatre-vingt-douze", "j'en ai reçu nonante-deux", "il y en a eu nonante-deux", "nous en avons reçu nonante-deux au total"], "model": "Nous en avons reçu nonante-deux.", "expl": "En blocks agreement (reçu, not reçues). Nonante-deux is the Belgian form; France says quatre-vingt-douze."}, {"id": "ga-pronouns-B2-03", "situation": "You are writing a short email to your assistant about the final version of the note.", "task": "Ask her to send it to you as soon as it is ready — affirmative imperative, two pronouns.", "accept": ["envoyez-la-moi dès qu'elle est prête", "envoyez-la-moi dès qu'elle sera prête", "envoyez-la-moi dès que possible", "merci de me l'envoyer dès qu'elle est prête", "pourriez-vous me l'envoyer dès qu'elle est prête", "transmettez-la-moi dès qu'elle est prête"], "model": "Envoyez-la-moi dès qu'elle est prête.", "expl": "Affirmative imperative: direct object first, hyphens, me → moi. In the polite « merci de me l'envoyer » the infinitive puts the pronouns back in front."}, {"id": "ga-pronouns-B2-04", "situation": "You are writing the assessment paragraph of an EPSO-style note about a delayed project.", "task": "Write one sentence saying that the deadlines the Council had set were not met.", "accept": ["les délais que le conseil avait fixés n'ont pas été respectés", "les délais que le conseil a fixés n'ont pas été respectés", "les délais que le conseil avait fixés n'ont pas été tenus", "les délais que le conseil avait fixés ne sont pas respectés", "les délais fixés par le conseil n'ont pas été respectés", "les délais que le conseil avait fixés n'ont pas pu être respectés"], "model": "Les délais que le Conseil avait fixés n'ont pas été respectés.", "expl": "Que stands for « les délais », a direct object in front of the verb, so fixés takes -s."}, {"id": "ga-pronouns-B2-05", "situation": "A colleague asks whether you have already raised the staffing problem with the head of unit. You did, on Tuesday.", "task": "Answer in one sentence using two pronouns.", "accept": ["oui je lui en ai déjà parlé mardi", "je lui en ai déjà parlé mardi", "oui je lui en ai parlé mardi", "je lui en ai parlé mardi", "oui je lui en ai déjà parlé", "je lui en ai déjà parlé"], "model": "Oui, je lui en ai déjà parlé mardi.", "expl": "Lui (à + person) then en (de + thing); en is always last, and both go before the auxiliary."}, {"id": "ga-pronouns-B2-06", "situation": "You are sending your head of unit the amended files with a one-line covering note. There are four of them.", "task": "Write one sentence saying you are sending the amended files and that there are four.", "accept": ["je vous envoie les dossiers modifiés il y en a quatre", "je vous transmets les dossiers modifiés il y en a quatre", "je vous envoie les dossiers modifiés : il y en a quatre", "veuillez trouver ci-joint les dossiers modifiés il y en a quatre", "je vous envoie les quatre dossiers modifiés", "je vous transmets les dossiers modifiés au nombre de quatre"], "model": "Je vous envoie les dossiers modifiés : il y en a quatre.", "expl": "Y before en, and the number at the end. « Je vous envoie » keeps vous first."}]},
  "relative-B1": {"slug": "relative", "level": "B1", "title": "Les pronoms relatifs — qui, que, où, ce qui, ce que", "summary": "Join two ideas into one sentence: qui as subject, que as object, où for place and time, and ce qui / ce que when there is no noun to hang on to.", "why": "Relative clauses are how a written note stops sounding like a list of short sentences. They cost nothing to learn — the choice is mechanical — and they are the first thing a marker notices when a B1 text reads like a B2 one.", "lesson": [{"id": "gl-relative-B1-01", "heading": "qui and que are not «who» and «which»", "body": "This is the single most useful thing in the chapter: in French the choice between qui and que has nothing to do with people versus things. Both work for both. What decides is the job the pronoun does in its own clause. If it is the SUBJECT of the verb that follows, you need qui: « le collègue qui travaille au cinquième étage », « le tram qui va à Schuman ». If it is the DIRECT OBJECT, and the clause therefore already has its own subject, you need que: « le rapport que je prépare », « la collègue que j'ai rencontrée hier ». The test takes two seconds: look at what comes immediately after the gap. A verb → qui. A subject (je, il, le chef, vous) → que. English speakers who translate «who» as qui and «which» as que get it right about half the time, which is exactly what makes the error hard to notice.", "table": {"cols": ["What follows the gap", "Pronoun", "Example", "English"], "rows": [["a verb", "qui", "le collègue qui travaille ici", "the colleague who works here"], ["a verb", "qui", "le tram qui va à Schuman", "the tram that goes to Schuman"], ["a subject + verb", "que", "le rapport que je prépare", "the report I'm preparing"], ["a subject + verb", "que", "la note que le chef a signée", "the note the head of unit signed"], ["a subject starting with a vowel", "qu'", "le mail qu'il a envoyé", "the email he sent"]]}, "examples": [{"fr": "Le collègue qui travaille au cinquième étage s'appelle Marc.", "en": "The colleague who works on the fifth floor is called Marc.", "gloss": {"qui travaille": "who works", "étage": "floor"}, "note": "A verb follows straight away, so qui."}, {"fr": "Le rapport que je prépare pour la réunion est presque fini.", "en": "The report I'm preparing for the meeting is nearly finished.", "gloss": {"que je prépare": "that I'm preparing"}, "note": "« Je » follows, so the clause already has a subject: que."}, {"fr": "Le tram 81 que je prends tous les matins est souvent en retard.", "en": "The number 81 tram I take every morning is often late.", "gloss": {"que je prends": "that I take", "en retard": "late"}, "note": "A thing, and still que — because it is the object of prends."}]}, {"id": "gl-relative-B1-02", "heading": "Elision: que shortens, qui never does", "body": "In front of a vowel or a silent h, que becomes qu': « le mail qu'il a envoyé », « la personne qu'elle a contactée ». Qui never changes, whatever follows: « le collègue qui a signé », « la note qui arrive ce soir ». This matters more than it looks, because « qu'il » and « qui » sound close in speech and English speakers write qu'il where the sentence needs qui — « le collègue qu'il travaille ici » is a very common B1 error and it is always wrong. Rescue rule: if the next word is a verb (a-t-il signed, arrive, travaille), you cannot elide, because there is nothing to elide in front of.", "table": {"cols": ["Correct", "Wrong", "Why"], "rows": [["le mail qu'il a envoyé", "le mail qui il a envoyé", "que + il = qu'il"], ["le collègue qui a signé", "le collègue qu'a signé", "qui never elides"], ["la note qu'elle a rédigée", "la note qui elle a rédigée", "que + elle = qu'elle"], ["la réunion qui a eu lieu hier", "la réunion qu'a eu lieu hier", "qui is the subject of a eu lieu"]]}, "examples": [{"fr": "Le mail qu'il a envoyé hier soir n'est jamais arrivé au secrétariat.", "en": "The email he sent last night never reached the secretariat.", "gloss": {"qu'il a envoyé": "that he sent"}, "note": "Il is the subject of the clause, so the relative is the object: qu'."}, {"fr": "La note qui arrive du Conseil doit être traduite avant jeudi.", "en": "The note coming in from the Council has to be translated by Thursday.", "gloss": {"qui arrive": "which is arriving", "traduite": "translated"}, "note": "Qui, uncut, in front of a vowel — the form never changes."}]}, {"id": "gl-relative-B1-03", "heading": "After qui, the verb agrees with what qui stands for", "body": "Qui carries the grammatical person of the noun in front of it. With a noun that is easy — « les collègues qui viennent » — but with c'est moi / c'est nous the verb has to follow the pronoun, not the c'est: « c'est moi qui suis responsable de ce dossier », « c'est nous qui sommes chargés du suivi ». English has nothing like this and says «it's me who is responsible», so learners write « c'est moi qui est », which sounds badly wrong to a French ear. This structure is worth having ready: it is the natural way to claim or assign responsibility in a meeting.", "table": {"cols": ["Antecedent", "Sentence", "Verb form"], "rows": [["moi", "c'est moi qui suis responsable", "1st person singular"], ["toi", "c'est toi qui as raison", "2nd person singular"], ["nous", "c'est nous qui sommes chargés du dossier", "1st person plural"], ["les collègues", "les collègues qui viennent de Luxembourg", "3rd person plural"]]}, "examples": [{"fr": "C'est moi qui ai rédigé la note de synthèse, pas le secrétariat.", "en": "I'm the one who drafted the summary note, not the secretariat.", "gloss": {"qui ai rédigé": "who drafted", "note de synthèse": "summary note"}, "note": "« Qui a rédigé » would say someone else did it."}, {"fr": "Ce sont les collègues du service juridique qui suivent ce dossier.", "en": "It's the colleagues in the legal service who follow this file.", "gloss": {"qui suivent": "who follow", "service juridique": "legal service"}, "note": "Plural antecedent, so the verb after qui is plural: suivent, not suit."}]}, {"id": "gl-relative-B1-04", "heading": "où — a place, and also a moment in time", "body": "Où covers place, exactly as English «where» does: « le bureau où je travaille », « la commune où j'habite ». The half English speakers never expect is that où also covers time: « le jour où j'ai reçu ma convocation », « l'année où je suis arrivé en Belgique », « le moment où tout a changé ». English uses «when» there, so learners write « le jour quand… », which does not exist in French — quand joins clauses (« quand je suis arrivé, il pleuvait ») but never attaches to a noun. Two extras you will meet in writing: d'où (from where) and par où (through where): « la station d'où part le tram 92 ».", "table": {"cols": ["Noun", "Relative", "English"], "rows": [["le bureau", "le bureau où je travaille", "the office where I work"], ["la commune", "la commune où j'habite", "the commune where I live"], ["le jour", "le jour où j'ai reçu la convocation", "the day I got the letter"], ["l'année", "l'année où je suis arrivé", "the year I arrived"], ["le moment", "au moment où la réunion a commencé", "just as the meeting started"]]}, "examples": [{"fr": "Le bureau où je travaille se trouve juste en face de la station Schuman.", "en": "The office where I work is right opposite Schuman station.", "gloss": {"où je travaille": "where I work", "en face de": "opposite"}, "note": "« Le bureau que je travaille » would leave travailler without its preposition."}, {"fr": "Je me souviens très bien du jour où j'ai reçu ma convocation EPSO.", "en": "I remember very clearly the day I got my EPSO letter.", "gloss": {"du jour où": "of the day when", "convocation": "letter of invitation"}, "note": "« Le jour quand » does not exist in French."}, {"fr": "L'année où je suis arrivé à Bruxelles, il a plu tout l'été.", "en": "The year I arrived in Brussels, it rained all summer.", "gloss": {"L'année où": "the year when", "il a plu": "it rained"}, "note": "A year is a moment in time, so où — never « l'année quand »."}, {"fr": "La commune où j'habite délivre les documents d'identité le samedi matin.", "en": "The commune where I live issues identity documents on Saturday mornings.", "gloss": {"où j'habite": "where I live", "délivre": "issues"}, "note": "In Belgium your local authority is « la commune » — Ixelles, Schaerbeek, Etterbeek. France says « la mairie »."}]}, {"id": "gl-relative-B1-05", "heading": "ce qui and ce que — when there is no noun in front", "body": "Sometimes the relative does not attach to a noun but to a whole idea, or to something you have not named. Then you add ce in front: ce qui if it is the subject, ce que if it is the object — the same test as before. « Ce qui m'intéresse, c'est le contact avec les États membres. » « Je ne comprends pas ce que vous voulez dire. » After tout it is the same: « tout ce qui est urgent », « tout ce que je sais ». The error to watch for is importing the question form into a statement: English «I don't know what he wants» tempts « je ne sais pas qu'est-ce qu'il veut », which is wrong. Qu'est-ce que only ever begins a question; inside a sentence it becomes ce que.", "table": {"cols": ["Question", "Statement", "Why"], "rows": [["Qu'est-ce qui ne va pas ?", "Dites-moi ce qui ne va pas.", "subject → ce qui"], ["Qu'est-ce qu'il veut ?", "Je ne sais pas ce qu'il veut.", "object → ce que / ce qu'"], ["Qu'est-ce que vous proposez ?", "Expliquez ce que vous proposez.", "object → ce que"], ["—", "Tout ce qui est urgent passe en premier.", "tout ce qui + verb"]]}, "examples": [{"fr": "Ce qui m'intéresse dans ce poste, c'est le travail avec les États membres.", "en": "What interests me about this post is working with the Member States.", "gloss": {"Ce qui": "what (subject)", "États membres": "Member States"}, "note": "Intéresse needs a subject, and ce qui provides it."}, {"fr": "Je ne comprends pas très bien ce qu'il veut dire dans son dernier paragraphe.", "en": "I don't quite understand what he means in his last paragraph.", "gloss": {"ce qu'il veut dire": "what he means"}, "note": "Il is already the subject, so the relative is the object: ce qu'."}, {"fr": "Tout ce que je sais, c'est que la réunion est reportée à jeudi.", "en": "All I know is that the meeting has been moved to Thursday.", "gloss": {"Tout ce que": "everything that", "reportée": "postponed"}, "note": "Two different que here: the relative « ce que », then the conjunction « c'est que »."}]}, {"id": "gl-relative-B1-06", "heading": "French cannot drop the relative the way English does", "body": "English deletes the object relative constantly: «the note I sent», «the colleague I met», «the tram I take». French never can. Every one of those needs que: « la note que j'ai envoyée », « la collègue que j'ai rencontrée », « le tram que je prends ». This is the highest-frequency relative error made by English speakers and it is entirely mechanical, so it is also the easiest to fix: after any noun, if the next words are a subject and a verb that need that noun as their object, insert que. Note the other half of the rule — you cannot end a French sentence with a preposition either: «the colleague I spoke to» becomes « la collègue à qui j'ai parlé », with the preposition in front.", "table": {"cols": ["English", "Wrong French", "Correct French"], "rows": [["the note I sent", "la note j'ai envoyée", "la note que j'ai envoyée"], ["the colleague I met", "la collègue j'ai rencontrée", "la collègue que j'ai rencontrée"], ["the tram I take", "le tram je prends", "le tram que je prends"], ["the colleague I spoke to", "la collègue j'ai parlé à", "la collègue à qui j'ai parlé"], ["the file I need", "le dossier j'ai besoin de", "le dossier dont j'ai besoin (B2)"]]}, "examples": [{"fr": "Le mail que j'ai envoyé hier concernait la réunion du groupe de travail.", "en": "The email I sent yesterday was about the working party meeting.", "gloss": {"que j'ai envoyé": "that I sent", "groupe de travail": "working party"}, "note": "English drops «that»; French cannot."}, {"fr": "La collègue à qui j'ai parlé ce matin s'occupe des dossiers de la DG COMP.", "en": "The colleague I spoke to this morning handles the DG COMP files.", "gloss": {"à qui j'ai parlé": "I spoke to", "s'occupe de": "handles"}, "note": "The preposition goes in front of qui, never at the end."}]}], "recognise": [{"id": "gr-relative-B1-01", "level": "B1", "format": "cloze", "q": "Le collègue ___ travaille au cinquième étage s'appelle Marc.", "options": ["où", "que", "qu'", "qui"], "a": 3, "trap": "que — learners pick it because English says «that»", "expl": "A verb follows the gap, so the relative is the subject: qui."}, {"id": "gr-relative-B1-02", "level": "B1", "format": "cloze", "q": "Le rapport ___ je prépare pour vendredi est presque fini.", "options": ["où", "qui", "que", "dont"], "a": 2, "trap": "qui — a thing tempts «which», which learners map onto qui", "expl": "« Je » follows, so the clause already has a subject; the relative is the object: que."}, {"id": "gr-relative-B1-03", "level": "B1", "format": "cloze", "q": "Le dossier ___ il a envoyé au secrétariat est incomplet.", "options": ["qui", "qu'", "que", "dont"], "a": 1, "trap": "que — the right pronoun, but it must elide in front of il", "expl": "Que + il = qu'il. Qui would never elide, and here the clause already has its subject."}, {"id": "gr-relative-B1-04", "level": "B1", "format": "cloze", "q": "C'est le bureau ___ je travaille depuis janvier.", "options": ["où", "que", "qui", "dont"], "a": 0, "trap": "que — English «the office that I work in» hides the preposition", "expl": "A place needs où. « Le bureau que je travaille » leaves travailler without its preposition."}, {"id": "gr-relative-B1-05", "level": "B1", "format": "cloze", "q": "Je me souviens du jour ___ j'ai reçu ma convocation EPSO.", "options": ["dont", "que", "qui", "où"], "a": 3, "trap": "que — English says «the day that I got», and quand feels even more natural", "expl": "Où covers time as well as place. « Le jour quand » does not exist in French."}, {"id": "gr-relative-B1-06", "level": "B1", "format": "cloze", "q": "___ m'intéresse dans ce poste, c'est le contact avec les États membres.", "options": ["Ce dont", "Ce que", "Ce qui", "Ce à quoi"], "a": 2, "trap": "Ce que — «what interests me» gives no clue in English", "expl": "Intéresse has no other subject, so the relative supplies it: ce qui."}, {"id": "gr-relative-B1-07", "level": "B1", "format": "cloze", "q": "Je ne comprends pas ___ vous voulez dire dans ce paragraphe.", "options": ["ce qui", "ce que", "ce dont", "ce à quoi"], "a": 1, "trap": "ce qui — the two look interchangeable until you check the verb", "expl": "Vous is already the subject of voulez, so the relative is the object: ce que."}, {"id": "gr-relative-B1-08", "level": "B1", "format": "cloze", "q": "La note ___ est sur votre bureau vient du Conseil.", "options": ["qui", "que", "qu'", "où"], "a": 0, "trap": "que — a thing plus «that» in English", "expl": "Est needs a subject and there is none in the clause, so qui."}, {"id": "gr-relative-B1-09", "level": "B1", "format": "cloze", "q": "C'est moi ___ ai rédigé la note de synthèse.", "options": ["où", "que", "qu'", "qui"], "a": 3, "trap": "que — « c'est moi que » exists in other structures, so it looks possible", "expl": "Qui is the subject of ai rédigé, and after « c'est moi qui » the verb stays in the first person."}], "drills": [{"id": "gd-relative-B1-01", "level": "B1", "format": "cloze", "q": "Le formulaire ___ vous devez remplir est disponible sur le site de la commune.", "options": ["où", "qui", "que", "dont"], "a": 2, "trap": "qui — «the form which you must fill in» maps «which» onto qui", "expl": "Vous follows the gap, so the clause has its subject; the form is the object of remplir: que."}, {"id": "gd-relative-B1-02", "level": "B1", "format": "cloze", "q": "Les collègues ___ viennent de Luxembourg arrivent à dix heures.", "options": ["que", "qui", "qu'", "où"], "a": 1, "trap": "que — plural people make learners reach for the «object» pronoun", "expl": "Viennent follows immediately, so the relative is its subject: qui."}, {"id": "gd-relative-B1-03", "level": "B1", "format": "cloze", "q": "L'immeuble ___ se trouve le secrétariat est en travaux jusqu'en mars.", "options": ["où", "que", "qui", "dont"], "a": 0, "trap": "qui — the inverted « se trouve le secrétariat » makes the gap look like a subject", "expl": "The building is the place: où. The subject of se trouve is « le secrétariat », after the verb."}, {"id": "gd-relative-B1-04", "level": "B1", "format": "cloze", "q": "La réunion ___ a eu lieu hier a duré plus de trois heures.", "options": ["où", "que", "qu'", "qui"], "a": 3, "trap": "que — «the meeting that took place» is the classic default to que", "expl": "Avoir lieu has no other subject here, so qui."}, {"id": "gd-relative-B1-05", "level": "B1", "format": "cloze", "q": "Voilà le dossier ___ je vous ai promis d'envoyer avant midi.", "options": ["où", "qui", "que", "dont"], "a": 2, "trap": "dont — « promettre de » puts a de in the sentence and drags learners to dont", "expl": "The de belongs to promettre, not to the relative. The dossier is the object of envoyer: que."}, {"id": "gd-relative-B1-06", "level": "B1", "format": "cloze", "q": "Le candidat ___ a réussi le test de raisonnement viendra lundi.", "options": ["qu'", "qui", "que", "dont"], "a": 1, "trap": "qu' — a vowel follows, so elision looks compulsory", "expl": "Only que elides. Here a verb follows the gap, so it is qui — and qui is never shortened."}, {"id": "gd-relative-B1-07", "level": "B1", "format": "cloze", "q": "Le message ___ elle a laissé au secrétariat était urgent.", "options": ["qu'", "qui", "que", "où"], "a": 0, "trap": "qui — «the message which she left» again", "expl": "Elle is the subject, the message is the object, and que elides in front of elle."}, {"id": "gd-relative-B1-08", "level": "B1", "format": "cloze", "q": "Il y a des semaines ___ tout arrive en même temps.", "options": ["dont", "que", "qui", "où"], "a": 3, "trap": "que — English «weeks when everything arrives», and quand feels natural too", "expl": "A period of time takes où, never quand."}, {"id": "gd-relative-B1-09", "level": "B1", "format": "cloze", "q": "Tout ___ je sais, c'est que la réunion est reportée à jeudi.", "options": ["ce dont", "ce qui", "ce que", "ce à quoi"], "a": 2, "trap": "ce qui — after tout the two forms look identical", "expl": "Je is the subject of sais, so the relative is its object: tout ce que."}, {"id": "gd-relative-B1-10", "level": "B1", "format": "cloze", "q": "Expliquez-moi ___ ne va pas dans cette procédure.", "options": ["ce que", "ce qui", "ce dont", "ce à quoi"], "a": 1, "trap": "ce que — English «explain what is wrong» gives no signal", "expl": "« Ne va pas » has no subject, so the relative supplies it: ce qui."}, {"id": "gd-relative-B1-11", "level": "B1", "format": "collocation", "q": "Which is correct French for «the note I sent yesterday»?", "options": ["la note que j'ai envoyée hier", "la note j'ai envoyée hier", "la note qui j'ai envoyée hier", "la note ce que j'ai envoyée hier"], "a": 0, "trap": "la note j'ai envoyée hier — English drops «that», so learners drop que", "expl": "French never deletes the relative pronoun. (Envoyée agrees because que stands in front of the verb.)"}, {"id": "gd-relative-B1-12", "level": "B1", "format": "collocation", "q": "Which sentence is correct French for «I'm the one who is responsible for this file»?", "options": ["C'est moi qui es responsable de ce dossier.", "C'est moi qui est responsable de ce dossier.", "C'est moi que je suis responsable de ce dossier.", "C'est moi qui suis responsable de ce dossier."], "a": 3, "trap": "C'est moi qui est — English «it's me who is» puts the verb in the third person", "expl": "After qui the verb takes the person of the antecedent, so with moi it is the first person singular: qui suis."}, {"id": "gd-relative-B1-13", "level": "B1", "format": "cloze", "q": "Le quartier ___ j'ai déménagé est bien desservi par le tram 92.", "options": ["qui", "que", "où", "dont"], "a": 2, "trap": "que — «the district that I moved to» hides the preposition at the end", "expl": "Déménager dans un quartier: a place, so où. French can never leave a stranded preposition."}, {"id": "gd-relative-B1-14", "level": "B1", "format": "cloze", "q": "Les documents ___ le chef d'unité a demandés sont prêts depuis ce matin.", "options": ["qui", "que", "qu'", "où"], "a": 1, "trap": "qui — the noun « le chef d'unité » right after the gap looks like a verb is coming", "expl": "The clause has its own subject (le chef d'unité), so the relative is the object: que — and demandés agrees with it."}, {"id": "gd-relative-B1-15", "level": "B1", "format": "collocation", "q": "Which sentence is correct French for «I don't know what he wants»?", "options": ["Je ne sais pas ce qu'il veut.", "Je ne sais pas qu'est-ce qu'il veut.", "Je ne sais pas ce qui il veut.", "Je ne sais pas quoi il veut."], "a": 0, "trap": "Je ne sais pas qu'est-ce qu'il veut — the question form imported straight into a statement", "expl": "Inside a sentence the question form disappears: ce que, elided to ce qu' in front of il. Qu'est-ce que only ever opens a question."}, {"id": "gd-relative-B1-16", "level": "B1", "format": "cloze", "q": "La collègue ___ j'ai parlé ce matin travaille à la DG COMP.", "options": ["chez qui", "de qui", "avec qui", "à qui"], "a": 3, "trap": "de qui — « parler de » exists too, but here you spoke TO her", "expl": "« Parler à quelqu'un »: the preposition goes in front of qui, never at the end of the clause."}, {"id": "gd-relative-B1-17", "level": "B1", "format": "cloze", "q": "L'année ___ je suis arrivé à Bruxelles, il a plu tout l'été.", "options": ["qui", "que", "où", "dont"], "a": 2, "trap": "que — «the year that I arrived» is what English gives you", "expl": "Years, days and moments all take où."}], "write": [{"id": "gw-relative-B1-01", "prompt": "Say in French: the report that I am preparing", "answer": "le rapport que je prépare", "accept": ["le rapport que je prépare"], "hint": "a subject follows the gap", "expl": "Object relative → que."}, {"id": "gw-relative-B1-02", "prompt": "Say in French: the colleague who works on the fifth floor", "answer": "le collègue qui travaille au cinquième étage", "accept": ["le collègue qui travaille au cinquième étage", "la collègue qui travaille au cinquième étage", "le collègue qui travaille au 5e étage"], "hint": "a verb follows the gap", "expl": "Subject relative → qui."}, {"id": "gw-relative-B1-03", "prompt": "Say in French (English drops «that» — French cannot): the email I sent yesterday", "answer": "le mail que j'ai envoyé hier", "accept": ["le mail que j'ai envoyé hier", "l'e-mail que j'ai envoyé hier", "le courriel que j'ai envoyé hier"], "hint": "que never disappears", "expl": "Every English «the X I did» needs que in French."}, {"id": "gw-relative-B1-04", "prompt": "Say in French: the office where I work", "answer": "le bureau où je travaille", "accept": ["le bureau où je travaille"], "hint": "a place", "expl": "Où, not que — travailler needs its preposition otherwise."}, {"id": "gw-relative-B1-05", "prompt": "Say in French: the day I received my EPSO letter", "answer": "le jour où j'ai reçu ma convocation EPSO", "accept": ["le jour où j'ai reçu ma convocation epso", "le jour où j'ai reçu ma convocation"], "hint": "time takes the same pronoun as place", "expl": "« Le jour quand » does not exist; time takes où."}, {"id": "gw-relative-B1-06", "prompt": "Complete: ___ m'intéresse, c'est le poste d'assistant. (what interests me)", "answer": "Ce qui", "accept": ["ce qui"], "hint": "the verb has no other subject", "expl": "No antecedent and a subject role → ce qui."}, {"id": "gw-relative-B1-07", "prompt": "Say in French: I don't understand what he wants.", "answer": "Je ne comprends pas ce qu'il veut.", "accept": ["je ne comprends pas ce qu'il veut"], "hint": "not qu'est-ce que", "expl": "In a statement the question form becomes ce que, elided to ce qu'."}, {"id": "gw-relative-B1-08", "prompt": "Say in French: everything I know", "answer": "tout ce que je sais", "accept": ["tout ce que je sais"], "hint": "je is already the subject", "expl": "Object role after tout ce → que."}, {"id": "gw-relative-B1-09", "prompt": "Join into one sentence: C'est moi. J'ai rédigé la note.", "answer": "C'est moi qui ai rédigé la note.", "accept": ["c'est moi qui ai rédigé la note"], "hint": "the verb keeps the person of moi", "expl": "« C'est moi qui a rédigé » is wrong: after qui the verb agrees with moi."}, {"id": "gw-relative-B1-10", "prompt": "Say in French: the meeting that took place yesterday", "answer": "la réunion qui a eu lieu hier", "accept": ["la réunion qui a eu lieu hier", "la réunion qui s'est tenue hier"], "hint": "what follows the gap is a verb", "expl": "Subject relative → qui."}, {"id": "gw-relative-B1-11", "prompt": "Say in French: the colleague I spoke to this morning", "answer": "la collègue à qui j'ai parlé ce matin", "accept": ["la collègue à qui j'ai parlé ce matin", "le collègue à qui j'ai parlé ce matin"], "hint": "the preposition goes first", "expl": "« Parler à » — French puts à in front of qui and never at the end."}, {"id": "gw-relative-B1-12", "prompt": "Say in French: the tram I take every morning", "answer": "le tram que je prends tous les matins", "accept": ["le tram que je prends tous les matins", "le tram que je prends chaque matin"], "hint": "object of prends", "expl": "Que, and it cannot be dropped."}], "apply": [{"id": "ga-relative-B1-01", "situation": "A new colleague asks which building you work in.", "task": "Answer in one sentence with a relative clause, mentioning Schuman station.", "accept": ["je travaille dans le bâtiment qui est en face de la station schuman", "je travaille dans l'immeuble qui est en face de la station schuman", "je travaille dans le bâtiment qui se trouve en face de la station schuman", "c'est le bâtiment qui est en face de la station schuman", "je travaille dans le bureau qui est en face de la station schuman", "je travaille dans le bâtiment qui se trouve près de la station schuman"], "model": "Je travaille dans le bâtiment qui est en face de la station Schuman.", "expl": "A verb follows the relative, so qui."}, {"id": "ga-relative-B1-02", "situation": "You are writing to the commune of Ixelles about a document you sent last week.", "task": "Write the opening sentence, using a relative clause to refer to the document.", "accept": ["je vous écris au sujet du document que je vous ai envoyé la semaine dernière", "je vous écris concernant le document que je vous ai envoyé la semaine dernière", "je vous contacte au sujet du document que je vous ai envoyé la semaine dernière", "je vous écris au sujet du document que j'ai envoyé la semaine dernière", "je vous écris à propos du document que je vous ai envoyé la semaine dernière", "je vous écris au sujet du formulaire que je vous ai envoyé la semaine dernière"], "model": "Je vous écris au sujet du document que je vous ai envoyé la semaine dernière.", "expl": "The document is the object of ai envoyé, so que — and English would have dropped it."}, {"id": "ga-relative-B1-03", "situation": "In an EPSO interview you are asked what attracts you to the post.", "task": "Answer in one sentence beginning with a relative that has no antecedent.", "accept": ["ce qui m'intéresse dans ce poste c'est le travail en équipe", "ce qui m'intéresse dans ce poste c'est le contact avec les états membres", "ce qui m'intéresse c'est le travail en équipe", "ce qui m'intéresse le plus c'est le travail en équipe", "ce qui m'attire dans ce poste c'est le travail en équipe", "ce qui m'intéresse dans ce poste c'est la dimension européenne"], "model": "Ce qui m'intéresse dans ce poste, c'est le travail en équipe.", "expl": "Ce qui supplies the subject of intéresse; « ce que » would leave the verb without one."}, {"id": "ga-relative-B1-04", "situation": "A friend asks when you arrived in Brussels and where you lived at first.", "task": "Answer in one sentence using où for the year.", "accept": ["l'année où je suis arrivé à bruxelles j'habitais à schaerbeek", "l'année où je suis arrivé à bruxelles j'habitais à ixelles", "l'année où je suis arrivé en belgique j'habitais à schaerbeek", "l'année où je suis arrivée à bruxelles j'habitais à schaerbeek", "l'année où je suis arrivé à bruxelles je vivais à schaerbeek", "l'année où je suis arrivé à bruxelles j'habitais encore à schaerbeek"], "model": "L'année où je suis arrivé à Bruxelles, j'habitais à Schaerbeek.", "expl": "Time takes où. « L'année quand » is not French."}, {"id": "ga-relative-B1-05", "situation": "You are writing a short note about Tuesday's meeting for your head of unit.", "task": "Write one sentence that refers to the meeting with a relative clause and says it clarified several points.", "accept": ["la réunion qui a eu lieu mardi a permis de clarifier plusieurs points", "la réunion qui s'est tenue mardi a permis de clarifier plusieurs points", "la réunion qui a eu lieu mardi a clarifié plusieurs points", "la réunion qui a eu lieu mardi nous a permis de clarifier plusieurs points", "la réunion qui a eu lieu mardi a permis de clarifier deux points", "la réunion qui a eu lieu mardi matin a permis de clarifier plusieurs points"], "model": "La réunion qui a eu lieu mardi a permis de clarifier plusieurs points.", "expl": "Avoir lieu has no other subject in the clause, so qui."}, {"id": "ga-relative-B1-06", "situation": "You are complaining to a colleague about your commute on the STIB.", "task": "Say in one sentence that the tram you take every morning is always late.", "accept": ["le tram que je prends tous les matins est toujours en retard", "le tram que je prends chaque matin est toujours en retard", "le tram 92 que je prends tous les matins est toujours en retard", "le bus que je prends tous les matins est toujours en retard", "le tram que je prends tous les matins a toujours du retard", "le tram que je prends le matin est toujours en retard"], "model": "Le tram que je prends tous les matins est toujours en retard.", "expl": "Object of prends → que, and French cannot leave it out."}]},
  "relative-B2": {"slug": "relative", "level": "B2", "title": "Les pronoms relatifs — dont, lequel, auquel, duquel", "summary": "dont in all three of its jobs, lequel after a preposition, the auquel/duquel contractions, ce dont — and why a native writes one sentence where you wrote two.", "why": "You cannot write a B2 text without dont, and « le dossier dont j'ai besoin » or « la réunion à laquelle j'ai assisté » is precisely what an EPSO written test rewards: one sentence instead of two, with the link made explicit. These forms are also the last ones English speakers acquire, because English strands its prepositions at the end and French never can.", "lesson": [{"id": "gl-relative-B2-01", "heading": "dont = de + something. Start from the verb, not from English", "body": "Dont is not a mysterious word: it is simply the relative that carries « de ». Whenever the clause you are attaching would need « de » — because the verb or the expression takes de — the relative is dont. « Je parle de ce dossier » → « le dossier dont je parle ». « J'ai besoin de ce document » → « le document dont j'ai besoin ». « Il est responsable de ce projet » → « le projet dont il est responsable ». So the method is: build the clause on its own, see whether a de appears, and if it does, use dont and delete the de. English gives you no help at all here, because English either says «about which» (formal) or, far more often, strands the preposition at the end — «the file I'm talking about», «the document I need». Neither shape exists in French, and stranding is not a stylistic slip there: it is impossible.", "table": {"cols": ["Verb / expression with de", "Full clause", "Relative clause"], "rows": [["parler de", "je parle de ce dossier", "le dossier dont je parle"], ["avoir besoin de", "j'ai besoin de ce document", "le document dont j'ai besoin"], ["s'occuper de", "il s'occupe de ce rapport", "le rapport dont il s'occupe"], ["être responsable de", "elle est responsable de ce projet", "le projet dont elle est responsable"], ["faire partie de", "je fais partie de ce groupe", "le groupe dont je fais partie"], ["se souvenir de", "je me souviens de cette réunion", "la réunion dont je me souviens"], ["dépendre de", "nous dépendons de ce service", "le service dont nous dépendons"], ["se plaindre de", "ils se plaignent du délai", "le délai dont ils se plaignent"]]}, "examples": [{"fr": "Le dossier dont je vous parle a été transmis au Conseil la semaine dernière.", "en": "The file I'm telling you about was sent to the Council last week.", "gloss": {"dont je vous parle": "that I'm telling you about", "transmis": "sent on"}, "note": "« Parler DE quelque chose » — the de becomes dont and disappears from the clause."}, {"fr": "C'est exactement le document dont j'ai besoin pour la réunion de jeudi.", "en": "That's exactly the document I need for Thursday's meeting.", "gloss": {"dont j'ai besoin": "that I need"}, "note": "Avoir besoin DE. « Le document que j'ai besoin » is the standard B1 error."}, {"fr": "Le rapport dont ma collègue s'occupe sera présenté en mars.", "en": "The report my colleague is handling will be presented in March.", "gloss": {"dont": "which … of", "s'occupe": "is handling"}, "note": "S'occuper DE — the de is what makes it dont rather than que."}]}, {"id": "gl-relative-B2-02", "heading": "dont for possession — and the two traps inside it", "body": "Dont also translates «whose», because possession in French runs through de: « le bureau DE la collègue » → « la collègue dont le bureau est à côté du mien ». Two things go wrong here for English speakers. First, after dont you use the ordinary article — le, la, les — never a possessive: « la collègue dont SON bureau » is wrong, even though English says «whose office». Second, the word order does not follow English. English fronts the possessed noun («the colleague whose husband I know»); French keeps its normal subject-verb-object order after dont: « la collègue dont je connais le mari ». Read it as «the colleague of whom I know the husband» and the order falls out naturally.", "table": {"cols": ["English", "French", "Note"], "rows": [["the colleague whose office is next to mine", "la collègue dont le bureau est à côté du mien", "article, not son"], ["the report whose conclusions are contested", "le rapport dont les conclusions sont contestées", "les, not ses"], ["the colleague whose husband I know", "la collègue dont je connais le mari", "subject + verb + object after dont"], ["a file whose deadline has passed", "un dossier dont le délai est dépassé", "article again"], ["wrong", "la collègue dont son bureau…", "never a possessive after dont"]]}, "examples": [{"fr": "La collègue dont le bureau est à côté du mien part à la retraite en juin.", "en": "The colleague whose office is next to mine is retiring in June.", "gloss": {"dont le bureau": "whose office", "part à la retraite": "is retiring"}, "note": "Le bureau, not son bureau."}, {"fr": "C'est un dossier dont les conclusions sont encore contestées par deux États membres.", "en": "It's a file whose conclusions are still being contested by two Member States.", "gloss": {"dont les conclusions": "whose conclusions", "contestées": "contested"}, "note": "« Les conclusions DU dossier » → dont, and the noun keeps its article: les, not ses."}, {"fr": "La cheffe d'unité dont je connais bien l'assistante prend ses fonctions lundi.", "en": "The head of unit whose assistant I know well takes up her post on Monday.", "gloss": {"dont je connais bien l'assistante": "whose assistant I know well", "prend ses fonctions": "takes up her post"}, "note": "French order: dont + subject + verb + the possessed noun."}]}, {"id": "gl-relative-B2-03", "heading": "dont for a part of a whole — the quantity use", "body": "The third job of dont is the one that turns up in every EU note: picking out a subset. « Nous avons reçu douze candidatures, dont trois hors délai. » « Une équipe de quinze personnes, dont quatre juristes. » English says «of which», «including» or «among them». Notice what is special about this use: dont does not need a verb after it — a noun phrase is enough — although a verb is perfectly possible: « nonante candidats, dont douze ont été retenus ». This construction is compact, formal and typical of a summary paragraph, which is exactly why it is worth having ready for a written test. Belgian numbers apply as usual: nonante for 90, septante for 70.", "table": {"cols": ["French", "English", "Shape"], "rows": [["douze candidatures, dont trois hors délai", "twelve applications, three of them late", "dont + noun phrase"], ["une équipe de quinze personnes, dont quatre juristes", "a team of fifteen, four of them lawyers", "dont + noun phrase"], ["nonante candidats, dont douze ont été retenus", "ninety candidates, twelve of whom were shortlisted", "dont + full clause"], ["trois réunions, dont deux à Luxembourg", "three meetings, two of them in Luxembourg", "dont + place"], ["quatre dossiers, dont deux urgents", "four files, two of them urgent", "dont + adjective"]]}, "examples": [{"fr": "Nous avons reçu nonante réponses, dont douze hors délai.", "en": "We received ninety replies, twelve of them after the deadline.", "gloss": {"dont douze": "twelve of which", "hors délai": "after the deadline", "nonante": "ninety (Belgian French)"}, "note": "In France you would write quatre-vingt-dix; in Brussels, nonante."}, {"fr": "Le groupe de travail compte quinze membres, dont quatre juristes.", "en": "The working party has fifteen members, four of them lawyers.", "gloss": {"compte": "has / numbers", "dont quatre juristes": "four of them lawyers"}, "note": "No verb needed after dont in this use."}]}, {"id": "gl-relative-B2-04", "heading": "When dont is impossible: preposition + lequel, and the contractions", "body": "Dont only covers a bare de. As soon as the clause needs any other preposition — sur, dans, avec, pour, pendant, par — you need lequel, and it agrees with the noun: lequel, laquelle, lesquels, lesquelles. « Je travaille sur ce projet » → « le projet sur lequel je travaille ». « J'ai assisté à cette réunion » → « la réunion à laquelle j'ai assisté ». With à, the masculine and the plurals contract: auquel, auxquels, auxquelles — but à laquelle stays in two words. With de the contractions are duquel, desquels, desquelles, and de laquelle stays separate. And this is the part to get right: you only use the de-forms after a COMPOUND preposition that itself ends in de — à côté de, au cours de, au sujet de, près de, lors de, à la suite de. « Le bâtiment à côté duquel se trouve la station Schuman. » After a bare de it is always dont, never duquel. For people, avec qui / à qui is more natural than avec lequel, though administrative French uses lequel to avoid ambiguity.", "table": {"cols": ["", "masculine sing.", "feminine sing.", "masculine pl.", "feminine pl."], "rows": [["plain", "lequel", "laquelle", "lesquels", "lesquelles"], ["with à", "auquel", "à laquelle", "auxquels", "auxquelles"], ["with de (compound prep. only)", "duquel", "de laquelle", "desquels", "desquelles"], ["example with à", "le poste auquel je postule", "la réunion à laquelle j'assiste", "les points auxquels je réponds", "les questions auxquelles je réponds"], ["example with de", "le bâtiment à côté duquel…", "la table autour de laquelle…", "les dossiers au sujet desquels…", "les réunions au cours desquelles…"]]}, "examples": [{"fr": "Le projet sur lequel je travaille depuis janvier est cofinancé par la Commission.", "en": "The project I have been working on since January is co-financed by the Commission.", "gloss": {"sur lequel": "on which", "cofinancé": "co-financed"}, "note": "«The project I work on» — French puts sur in front, never at the end."}, {"fr": "La réunion à laquelle j'ai assisté hier a duré plus de trois heures.", "en": "The meeting I attended yesterday lasted more than three hours.", "gloss": {"à laquelle j'ai assisté": "which I attended"}, "note": "Assister À. Feminine, so à laquelle in two words."}, {"fr": "L'appel à candidatures auquel j'ai répondu était publié sur le site d'EPSO.", "en": "The call for applications I replied to was published on the EPSO site.", "gloss": {"auquel j'ai répondu": "which I replied to"}, "note": "à + lequel contracts to auquel."}, {"fr": "Le bâtiment à côté duquel se trouve la station Schuman est en travaux.", "en": "The building next to which Schuman station stands is being renovated.", "gloss": {"à côté duquel": "next to which", "en travaux": "under renovation"}, "note": "« À côté de » ends in de, so de + lequel = duquel. A bare de would have given dont."}]}, {"id": "gl-relative-B2-05", "heading": "ce dont and ce à quoi — no antecedent, but still a preposition", "body": "The ce qui / ce que pair from B1 has two more members, for verbs that take de or à. « J'ai besoin d'un délai » → « ce dont j'ai besoin, c'est d'un délai supplémentaire ». « Je pense à la charge de travail » → « ce à quoi je pense, c'est à la charge de travail ». Note the small detail that catches everyone: when the sentence is completed with « c'est… », the preposition comes back on the second half — « c'est D'un délai », « c'est À la charge de travail ». The English-speaker error is to use ce que for everything, because English «what» never changes: « ce que j'ai besoin » is wrong, always, and it is a very visible mistake in a written test.", "table": {"cols": ["Verb takes", "Form", "Example"], "rows": [["nothing (subject)", "ce qui", "ce qui m'inquiète, c'est le délai"], ["nothing (object)", "ce que", "ce que je propose, c'est un report"], ["de", "ce dont", "ce dont j'ai besoin, c'est d'un délai"], ["à", "ce à quoi", "ce à quoi je pense, c'est à la charge de travail"], ["wrong", "ce que j'ai besoin", "avoir besoin DE, so ce dont"]]}, "examples": [{"fr": "Ce dont j'ai besoin, c'est d'un délai supplémentaire de deux semaines.", "en": "What I need is another two weeks.", "gloss": {"Ce dont j'ai besoin": "what I need", "délai supplémentaire": "extension"}, "note": "The de reappears after c'est."}, {"fr": "Ce dont nous avons discuté ce matin doit rester confidentiel.", "en": "What we discussed this morning must remain confidential.", "gloss": {"Ce dont nous avons discuté": "what we discussed"}, "note": "Discuter DE quelque chose."}, {"fr": "Ce à quoi je pense, c'est à la charge de travail de l'équipe en septembre.", "en": "What I have in mind is the team's workload in September.", "gloss": {"Ce à quoi je pense": "what I'm thinking about", "charge de travail": "workload"}, "note": "Penser À → ce à quoi, and the à comes back after c'est."}]}, {"id": "gl-relative-B2-06", "heading": "Why a native writes one sentence where you wrote two", "body": "At B1 you produce correct short sentences that repeat the noun: « J'ai lu le rapport. Les conclusions du rapport sont contestées. » A B2 writer subordinates: « J'ai lu le rapport, dont les conclusions sont contestées. » Nothing is added, one noun disappears, and the relationship between the two ideas becomes explicit — which is what a marker means by «cohesion». Three practical rules when you do it. Keep the relative pronoun next to its antecedent, or the sentence becomes ambiguous. Use at most one relative clause per sentence in a note; stacked clauses read as heavy administrative French even to French readers. And when the relative clause carries extra, non-essential information, it takes commas — « le rapport, dont les conclusions sont contestées, a été publié en mars » — whereas an identifying clause takes none: « le rapport dont je vous parle ».", "table": {"cols": ["Two B1 sentences", "One B2 sentence"], "rows": [["J'ai lu le rapport. Les conclusions du rapport sont contestées.", "J'ai lu le rapport, dont les conclusions sont contestées."], ["J'ai assisté à une réunion mardi. Elle a duré trois heures.", "La réunion à laquelle j'ai assisté mardi a duré trois heures."], ["Je travaille sur un projet. Il est cofinancé par la Commission.", "Le projet sur lequel je travaille est cofinancé par la Commission."], ["Nous avons reçu nonante réponses. Douze sont arrivées hors délai.", "Nous avons reçu nonante réponses, dont douze hors délai."]]}, "examples": [{"fr": "Le rapport, dont les conclusions ont été contestées, a été publié en mars.", "en": "The report, whose conclusions were contested, was published in March.", "gloss": {"dont les conclusions": "whose conclusions", "publié": "published"}, "note": "Non-essential information, so commas on both sides."}, {"fr": "Le dossier dont ma collègue est responsable sera présenté au comité en mars.", "en": "The file my colleague is responsible for will be presented to the committee in March.", "gloss": {"dont ma collègue est responsable": "that my colleague is responsible for", "comité": "committee"}, "note": "Identifying clause: no commas."}]}], "recognise": [{"id": "gr-relative-B2-01", "level": "B2", "format": "cloze", "q": "Le dossier ___ je vous parle a été transmis au Conseil.", "options": ["où", "que", "qui", "dont"], "a": 3, "trap": "que — «the file I'm telling you about» hides the preposition at the end in English", "expl": "« Parler DE quelque chose »: a de in the clause means dont."}, {"id": "gr-relative-B2-02", "level": "B2", "format": "cloze", "q": "C'est exactement le document ___ j'ai besoin pour jeudi.", "options": ["qui", "que", "dont", "auquel"], "a": 2, "trap": "que — the commonest single relative error made by English speakers", "expl": "Avoir besoin DE → dont. « Le document que j'ai besoin » leaves besoin without its de."}, {"id": "gr-relative-B2-03", "level": "B2", "format": "cloze", "q": "La collègue ___ le bureau est à côté du mien part à la retraite en juin.", "options": ["que", "dont", "qui", "duquel"], "a": 1, "trap": "duquel — the de-form looks more «possessive», but a bare de always gives dont", "expl": "Possession runs through de, so dont — and the noun after it takes le, never son."}, {"id": "gr-relative-B2-04", "level": "B2", "format": "cloze", "q": "Nous avons reçu douze candidatures, ___ trois hors délai.", "options": ["dont", "que", "desquelles", "dans lesquelles"], "a": 0, "trap": "desquelles — «of which» in English suggests the de + lequel form", "expl": "For a part of a whole French uses dont, with no verb needed after it."}, {"id": "gr-relative-B2-05", "level": "B2", "format": "cloze", "q": "Le projet ___ je travaille depuis janvier est cofinancé par la Commission.", "options": ["auquel", "dont", "que", "sur lequel"], "a": 3, "trap": "dont — learners use dont for every preposition once they have learnt it", "expl": "« Travailler SUR », not de, so sur + lequel. Dont only carries de."}, {"id": "gr-relative-B2-06", "level": "B2", "format": "cloze", "q": "La réunion ___ j'ai assisté hier a duré plus de trois heures.", "options": ["que", "dont", "à laquelle", "sur laquelle"], "a": 2, "trap": "que — English «the meeting I attended» has no preposition at all", "expl": "Assister À quelque chose. Feminine singular, so à laquelle, written in two words."}, {"id": "gr-relative-B2-07", "level": "B2", "format": "cloze", "q": "Le bâtiment à côté ___ se trouve la station Schuman est en travaux.", "options": ["dont", "duquel", "auquel", "lequel"], "a": 1, "trap": "dont — it also carries de, but never after another preposition", "expl": "« À côté de » ends in de, so de + lequel contracts to duquel."}, {"id": "gr-relative-B2-08", "level": "B2", "format": "cloze", "q": "___ j'ai besoin, c'est d'un délai supplémentaire de deux semaines.", "options": ["Ce dont", "Ce que", "Ce qui", "Ce à quoi"], "a": 0, "trap": "Ce que — English «what I need» never changes shape", "expl": "Avoir besoin DE, with no antecedent: ce dont. Note the de coming back after c'est."}, {"id": "gr-relative-B2-09", "level": "B2", "format": "cloze", "q": "Les outils informatiques avec ___ nous travaillons sont obsolètes.", "options": ["desquels", "qui", "dont", "lesquels"], "a": 3, "trap": "qui — correct after avec for people, impossible for things", "expl": "After a preposition, things take lequel and its forms; qui is reserved for people."}], "drills": [{"id": "gd-relative-B2-01", "level": "B2", "format": "cloze", "q": "Le rapport ___ le chef d'unité s'occupe sera publié en mars.", "options": ["auquel", "que", "dont", "sur lequel"], "a": 2, "trap": "que — «the report the head of unit is handling» looks like a plain object", "expl": "S'occuper DE quelque chose → dont."}, {"id": "gd-relative-B2-02", "level": "B2", "format": "cloze", "q": "La procédure ___ vous faites référence a été modifiée en 2024.", "options": ["dont", "à laquelle", "que", "de laquelle"], "a": 1, "trap": "dont — «the procedure you refer to» sounds like a de-verb in English", "expl": "« Faire référence À » takes à, so à laquelle. Dont would need a verb built with de."}, {"id": "gd-relative-B2-03", "level": "B2", "format": "cloze", "q": "L'appel à candidatures ___ j'ai répondu était publié sur le site d'EPSO.", "options": ["auquel", "dont", "que", "duquel"], "a": 0, "trap": "dont — the reflex once dont has been learnt", "expl": "Répondre À, masculine singular: à + lequel = auquel."}, {"id": "gd-relative-B2-04", "level": "B2", "format": "cloze", "q": "Une équipe de quinze personnes, ___ quatre juristes, travaille sur ce dossier.", "options": ["desquelles", "que", "qui", "dont"], "a": 3, "trap": "desquelles — the literal rendering of «of whom»", "expl": "A subset of a whole takes dont, and no verb is needed after it."}, {"id": "gd-relative-B2-05", "level": "B2", "format": "cloze", "q": "C'est un dossier ___ les conclusions sont contestées par deux États membres.", "options": ["que", "duquel", "dont", "auquel"], "a": 2, "trap": "duquel — a possessive relationship makes the heavier form look more formal", "expl": "A bare de always gives dont; duquel only follows a compound preposition ending in de."}, {"id": "gd-relative-B2-06", "level": "B2", "format": "cloze", "q": "Le service ___ nous dépendons pour les ressources humaines a déménagé.", "options": ["duquel", "dont", "que", "auquel"], "a": 1, "trap": "auquel — «the service we depend on» feels like a destination", "expl": "« Dépendre DE quelqu'un ou de quelque chose » takes de, so the relative is dont — the same shape as « le service dont je fais partie »."}, {"id": "gd-relative-B2-07", "level": "B2", "format": "cloze", "q": "La table autour ___ nous étions assis était beaucoup trop petite.", "options": ["de laquelle", "dont", "duquel", "à laquelle"], "a": 0, "trap": "duquel — the contraction exists, but not for a feminine noun", "expl": "« Autour de » + une table (feminine) = autour de laquelle, in three words: de laquelle never contracts."}, {"id": "gd-relative-B2-08", "level": "B2", "format": "cloze", "q": "Les raisons pour ___ le délai a été prolongé sont expliquées en annexe.", "options": ["lesquels", "laquelle", "lequel", "lesquelles"], "a": 3, "trap": "laquelle — the singular slips out because « la raison » is so common", "expl": "Lequel agrees with its antecedent: « les raisons » is feminine plural → lesquelles."}, {"id": "gd-relative-B2-09", "level": "B2", "format": "cloze", "q": "Le groupe de travail ___ je fais partie se réunit tous les mardis.", "options": ["que", "auquel", "dont", "duquel"], "a": 2, "trap": "auquel — «the group I belong to» suggests à, as in appartenir à", "expl": "« Faire partie DE » takes de → dont. (« Appartenir à » would indeed give auquel.)"}, {"id": "gd-relative-B2-10", "level": "B2", "format": "cloze", "q": "La réunion au cours ___ cette décision a été prise s'est tenue à Luxembourg.", "options": ["duquel", "de laquelle", "dont", "à laquelle"], "a": 1, "trap": "duquel — the masculine contraction applied to a feminine noun", "expl": "« Au cours de » ends in de, and « la réunion » is feminine, so de laquelle."}, {"id": "gd-relative-B2-11", "level": "B2", "format": "cloze", "q": "___ nous avons discuté ce matin doit rester confidentiel.", "options": ["Ce dont", "Ce que", "Ce qui", "Ce à quoi"], "a": 0, "trap": "Ce que — English «what we discussed» takes a direct object", "expl": "Discuter DE quelque chose, with no antecedent → ce dont."}, {"id": "gd-relative-B2-12", "level": "B2", "format": "cloze", "q": "___ je pense, c'est à la charge de travail de l'équipe en septembre.", "options": ["Ce qui", "Ce dont", "Ce que", "Ce à quoi"], "a": 3, "trap": "Ce dont — the other prepositional form, used for de-verbs only", "expl": "Penser À a thing → ce à quoi, and the à comes back after c'est."}, {"id": "gd-relative-B2-13", "level": "B2", "format": "collocation", "q": "Which sentence is correct French for «the colleague whose office is next to mine»?", "options": ["la collègue que son bureau est à côté du mien", "la collègue dont son bureau est à côté du mien", "la collègue dont le bureau est à côté du mien", "la collègue duquel le bureau est à côté du mien"], "a": 2, "trap": "la collègue dont son bureau… — «whose» in English keeps a possessive, so learners keep son", "expl": "After dont the possessed noun takes an ordinary article: le bureau, les conclusions, la référence."}, {"id": "gd-relative-B2-14", "level": "B2", "format": "collocation", "q": "Which sentence is correct French for «the project I'm working on»?", "options": ["le projet que je travaille sur", "le projet sur lequel je travaille", "le projet dont je travaille", "le projet lequel je travaille sur"], "a": 1, "trap": "le projet dont je travaille — dont used as an all-purpose preposition", "expl": "Travailler SUR: the preposition moves to the front with lequel. French never strands a preposition."}, {"id": "gd-relative-B2-15", "level": "B2", "format": "cloze", "q": "L'entretien ___ je me prépare depuis trois mois aura lieu en octobre.", "options": ["auquel", "dont", "que", "duquel"], "a": 0, "trap": "dont — «prepare for» feels like a de-verb, and « se préparer » looks reflexive enough to take de", "expl": "« Se préparer À quelque chose » → à + lequel = auquel."}, {"id": "gd-relative-B2-16", "level": "B2", "format": "collocation", "q": "Which single sentence best joins « J'ai lu le rapport. Les conclusions du rapport sont claires. »?", "options": ["J'ai lu le rapport, duquel les conclusions sont claires.", "J'ai lu le rapport, dont ses conclusions sont claires.", "J'ai lu le rapport, que les conclusions sont claires.", "J'ai lu le rapport, dont les conclusions sont claires."], "a": 3, "trap": "dont ses conclusions — the English possessive kept in place", "expl": "« Les conclusions DU rapport » → dont + article. This is the standard B2 way to avoid repeating the noun."}, {"id": "gd-relative-B2-17", "level": "B2", "format": "cloze", "q": "Il y a eu nonante candidats, ___ douze ont été retenus pour l'oral.", "options": ["dans lesquels", "desquels", "dont", "que"], "a": 2, "trap": "desquels — «twelve of whom» pushes learners towards the de + lequel form", "expl": "Dont covers the part-of-a-whole use, with or without a verb after it."}], "write": [{"id": "gw-relative-B2-01", "prompt": "Say in French: the file I'm telling you about", "answer": "le dossier dont je vous parle", "accept": ["le dossier dont je vous parle", "le dossier dont je te parle"], "hint": "parler DE", "expl": "The de in parler de becomes dont."}, {"id": "gw-relative-B2-02", "prompt": "Say in French: the document I need", "answer": "le document dont j'ai besoin", "accept": ["le document dont j'ai besoin"], "hint": "avoir besoin DE", "expl": "« Que j'ai besoin » leaves besoin without its preposition."}, {"id": "gw-relative-B2-03", "prompt": "Say in French: the colleague whose office is next to mine", "answer": "la collègue dont le bureau est à côté du mien", "accept": ["la collègue dont le bureau est à côté du mien", "le collègue dont le bureau est à côté du mien"], "hint": "article, not a possessive", "expl": "Dont + le bureau — never « dont son bureau »."}, {"id": "gw-relative-B2-04", "prompt": "Say in French: twelve applications, three of them late", "answer": "douze candidatures, dont trois hors délai", "accept": ["douze candidatures dont trois hors délai", "douze candidatures, dont trois hors délai", "douze candidatures dont trois étaient hors délai"], "hint": "part of a whole", "expl": "Dont needs no verb in this use."}, {"id": "gw-relative-B2-05", "prompt": "Say in French: the project I have been working on since January", "answer": "le projet sur lequel je travaille depuis janvier", "accept": ["le projet sur lequel je travaille depuis janvier"], "hint": "travailler SUR", "expl": "Any preposition other than a bare de means lequel, placed in front."}, {"id": "gw-relative-B2-06", "prompt": "Say in French: the meeting I attended yesterday", "answer": "la réunion à laquelle j'ai assisté hier", "accept": ["la réunion à laquelle j'ai assisté hier"], "hint": "assister À, feminine", "expl": "À laquelle stays in two words; only auquel, auxquels and auxquelles contract."}, {"id": "gw-relative-B2-07", "prompt": "Say in French: the call for applications I replied to", "answer": "l'appel à candidatures auquel j'ai répondu", "accept": ["l'appel à candidatures auquel j'ai répondu", "l'avis de vacance auquel j'ai répondu"], "hint": "répondre À, masculine", "expl": "à + lequel = auquel."}, {"id": "gw-relative-B2-08", "prompt": "Complete with the right contraction: le bâtiment à côté ___ se trouve la station Schuman", "answer": "duquel", "accept": ["duquel"], "hint": "the preposition already ends in de", "expl": "de + lequel = duquel. After a bare de it would have been dont."}, {"id": "gw-relative-B2-09", "prompt": "Say in French: what I need is an extension of two weeks", "answer": "Ce dont j'ai besoin, c'est d'un délai supplémentaire de deux semaines.", "accept": ["ce dont j'ai besoin c'est d'un délai supplémentaire de deux semaines", "ce dont j'ai besoin, c'est d'un délai supplémentaire de deux semaines", "ce dont j'ai besoin c'est d'un délai de deux semaines"], "hint": "no antecedent, and the verb takes de", "expl": "Ce dont, and the de comes back after c'est."}, {"id": "gw-relative-B2-10", "prompt": "Say in French: the reasons for which the deadline was extended", "answer": "les raisons pour lesquelles le délai a été prolongé", "accept": ["les raisons pour lesquelles le délai a été prolongé", "les raisons pour lesquelles le délai a été reporté"], "hint": "feminine plural", "expl": "Lequel agrees with its antecedent: lesquelles."}, {"id": "gw-relative-B2-11", "prompt": "Say in French: the working party I belong to", "answer": "le groupe de travail dont je fais partie", "accept": ["le groupe de travail dont je fais partie"], "hint": "faire partie DE", "expl": "De-expression → dont, not auquel."}, {"id": "gw-relative-B2-12", "prompt": "Join into one sentence: J'ai lu le rapport. Les conclusions du rapport sont claires.", "answer": "J'ai lu le rapport, dont les conclusions sont claires.", "accept": ["j'ai lu le rapport dont les conclusions sont claires", "j'ai lu le rapport, dont les conclusions sont claires"], "hint": "de + noun", "expl": "Dont replaces « du rapport » and the second noun keeps its article."}], "apply": [{"id": "ga-relative-B2-01", "situation": "You are drafting the opening of a note to your head of unit about Tuesday's working party.", "task": "Write one sentence referring to the meeting you attended and saying that it clarified two points.", "accept": ["la réunion du groupe de travail à laquelle j'ai assisté mardi a permis de clarifier deux points", "la réunion à laquelle j'ai assisté mardi a permis de clarifier deux points", "la réunion à laquelle j'ai participé mardi a permis de clarifier deux points", "la réunion du groupe de travail à laquelle j'ai assisté mardi a permis de clarifier plusieurs points", "la réunion à laquelle j'ai assisté mardi a clarifié deux points", "la réunion à laquelle j'ai assisté mardi dernier a permis de clarifier deux points"], "model": "La réunion du groupe de travail à laquelle j'ai assisté mardi a permis de clarifier deux points.", "expl": "Assister À, feminine antecedent → à laquelle. English «the meeting I attended» gives no preposition at all."}, {"id": "ga-relative-B2-02", "situation": "You are summarising a public consultation for an EPSO-style note. Ninety replies came in; twelve of them arrived after the deadline.", "task": "Write the sentence in one line, using the part-of-a-whole construction and Belgian numbers.", "accept": ["nous avons reçu nonante réponses dont douze hors délai", "nous avons reçu nonante réponses, dont douze hors délai", "nous avons reçu nonante réponses dont douze après la date limite", "la consultation a recueilli nonante réponses dont douze hors délai", "nous avons reçu quatre-vingt-dix réponses dont douze hors délai", "nous avons reçu nonante réponses dont douze sont arrivées hors délai"], "model": "Nous avons reçu nonante réponses, dont douze hors délai.", "expl": "Dont for a subset, with no verb needed. Nonante is Belgian; France writes quatre-vingt-dix."}, {"id": "ga-relative-B2-03", "situation": "You are emailing the commune of Ixelles about a document you no longer have the reference number for.", "task": "Write the opening sentence, using dont for the missing reference.", "accept": ["je vous écris au sujet d'un document dont je n'ai pas la référence", "je vous écris au sujet d'un document dont je n'ai plus la référence", "je vous contacte au sujet d'un document dont je n'ai pas la référence", "je vous écris concernant un document dont je n'ai pas la référence", "je vous écris au sujet d'un document dont j'ai perdu la référence", "je vous écris à propos d'un document dont je n'ai pas la référence"], "model": "Je vous écris au sujet d'un document dont je n'ai pas la référence.", "expl": "« La référence DU document » → dont, followed by ordinary subject-verb-object order."}, {"id": "ga-relative-B2-04", "situation": "In a note you must state what the unit needs before it can finish the report.", "task": "Write one sentence beginning with the relative that has no antecedent.", "accept": ["ce dont l'unité a besoin c'est d'un délai supplémentaire", "ce dont l'unité a besoin, c'est d'un délai supplémentaire", "ce dont nous avons besoin c'est d'un délai supplémentaire", "ce dont l'unité a besoin c'est de personnel supplémentaire", "ce dont l'unité a besoin c'est d'un délai de deux semaines", "ce dont nous avons besoin c'est de temps supplémentaire"], "model": "Ce dont l'unité a besoin, c'est d'un délai supplémentaire.", "expl": "Avoir besoin DE, no antecedent → ce dont, and the de reappears after c'est."}, {"id": "ga-relative-B2-05", "situation": "You are introducing a colleague's file at a coordination meeting.", "task": "Write one sentence saying that the file your colleague is responsible for will be presented in March.", "accept": ["le dossier dont ma collègue est responsable sera présenté en mars", "le dossier dont mon collègue est responsable sera présenté en mars", "le dossier dont ma collègue est responsable sera présenté au comité en mars", "le dossier dont ma collègue s'occupe sera présenté en mars", "le dossier dont ma collègue est responsable sera présenté en mars prochain", "le dossier dont elle est responsable sera présenté en mars"], "model": "Le dossier dont ma collègue est responsable sera présenté au comité en mars.", "expl": "« Être responsable DE » → dont, and the clause needs no commas because it identifies the file."}, {"id": "ga-relative-B2-06", "situation": "You are rewriting two short sentences from a draft note: « Le rapport a été publié en mars. Les conclusions du rapport ont été contestées. »", "task": "Write them as one B2 sentence with a relative clause.", "accept": ["le rapport dont les conclusions ont été contestées a été publié en mars", "le rapport, dont les conclusions ont été contestées, a été publié en mars", "le rapport dont les conclusions ont été contestées a été publié en mars dernier", "le rapport publié en mars, dont les conclusions ont été contestées, a fait l'objet de critiques", "le rapport, dont les conclusions ont été contestées, a été publié au mois de mars", "le rapport dont les conclusions sont contestées a été publié en mars"], "model": "Le rapport, dont les conclusions ont été contestées, a été publié en mars.", "expl": "Dont replaces « du rapport ». The information is non-essential here, so it sits between commas."}]},
  "connectors-B1": {"slug": "connectors", "level": "B1", "title": "Les connecteurs logiques", "summary": "The everyday joining words — adding, contrasting, cause, consequence, sequence, illustration, conclusion — grouped by the job they do, and marked for spoken or written register.", "why": "In the EUFTE written test the marker reads fast and looks for structure. Connectors are how structure becomes visible on the page: they show that you are adding, conceding or concluding, and they are worth marks in themselves. They also stop the commonest structural error an English speaker makes in French — running two clauses together with a comma and no joining word.", "lesson": [{"heading": "Why French will not let you use a comma instead", "body": "English tolerates two ideas glued together: « The room was not booked, we met online. » French does not. A comma between two full clauses with no joining word is read as an error, and in an EPSO written test it is read as an error you made ten times. Every logical step has to be named. The second thing to fix is which family the connector belongs to, because that decides what is allowed to follow it. Conjunctions (parce que, car, puisque, comme) take a whole clause and live inside the sentence. Adverbial connectors (donc, cependant, de plus, par conséquent) also take a whole clause but need a full stop or a semicolon in front of them. Prepositions (à cause de, grâce à, en raison de) take a noun and never a clause — « à cause de la salle n'était pas libre » is the classic English-speaker sentence, and it is impossible.", "table": {"cols": ["Family", "What follows it", "Examples", "Where it sits"], "rows": [["Conjunction", "a full clause: subject + verb", "parce que, puisque, comme, car", "inside the sentence, joining two clauses"], ["Adverbial connector", "a full clause, after a full stop or semicolon", "donc, cependant, de plus, par conséquent", "opening the sentence, or just after the verb"], ["Preposition", "a noun or an infinitive — never a clause", "à cause de, grâce à, en raison de, afin de", "inside the clause"]]}, "examples": [{"fr": "La réunion a été annulée parce que la salle n'était pas réservée.", "en": "The meeting was cancelled because the room had not been booked.", "gloss": {"annulée": "cancelled", "salle": "room", "réservée": "booked"}, "note": "parce que is a conjunction: a whole clause follows it."}, {"fr": "La réunion a été annulée en raison d'un problème de salle.", "en": "The meeting was cancelled owing to a problem with the room.", "gloss": {"en raison d'": "owing to", "problème": "problem"}, "note": "en raison de is a preposition: only a noun may follow. Swapping the two families is the error to watch."}, {"fr": "La salle n'était pas libre ; nous nous sommes donc réunis en ligne.", "en": "The room was not free, so we met online.", "gloss": {"libre": "free", "réunis": "met", "en ligne": "online"}, "note": "A semicolon, then the second clause with donc inside it. A bare comma here would be the English comma splice."}]}, {"heading": "Adding a point", "body": "You are stacking one argument on another. The written default is de plus; en outre is the same move one notch more formal and belongs in a note, never in speech. par ailleurs adds a point on a different subject — « on another matter » — while d'ailleurs, which looks almost identical, adds a remark that backs up what you have just said. Two mistakes are worth naming. English speakers write « En plus, … » in a formal note: it is spoken French, keep it for the corridor. And they open a sentence with « Aussi » meaning « also » — at the head of a sentence aussi means therefore and forces inversion (« Aussi la Commission a-t-elle proposé un report »). For « also » use également, inside the clause.", "table": {"cols": ["Connector", "Force", "Register", "Watch out"], "rows": [["et", "plain and", "all", "fine between two items, weak between two arguments"], ["de plus", "moreover", "neutral, written", "the safe default in a note"], ["en outre", "furthermore", "written, formal", "EU written French; nobody says it out loud"], ["par ailleurs", "on another matter", "neutral, written", "adds a different point, not a stronger one"], ["d'ailleurs", "besides, and in fact", "neutral, spoken", "backs up what you just said — not the same word as par ailleurs"], ["en plus", "on top of that", "spoken", "keep it out of the written test"], ["également", "also, as well", "all", "the safe way to say « also »; goes after the verb"]]}, "examples": [{"fr": "Le dossier est incomplet ; de plus, il est arrivé après la date limite.", "en": "The file is incomplete; moreover, it arrived after the deadline.", "gloss": {"dossier": "file", "date limite": "deadline"}, "note": "Two complaints on the same line of argument: de plus."}, {"fr": "La proposition coûte cher. Par ailleurs, elle arrive trop tard dans le cycle budgétaire.", "en": "The proposal is expensive. On another matter, it comes too late in the budget cycle.", "gloss": {"coûte": "costs", "cycle budgétaire": "budget cycle"}, "note": "A second, separate objection: par ailleurs."}, {"fr": "Il connaît bien ce dossier ; d'ailleurs, c'est lui qui a rédigé la première version.", "en": "He knows this file well; besides, he is the one who drafted the first version.", "gloss": {"rédigé": "drafted"}, "note": "d'ailleurs offers evidence for the claim just made."}, {"fr": "La délégation belge soutient le texte ; elle a également proposé un amendement.", "en": "The Belgian delegation supports the text; it has also tabled an amendment.", "gloss": {"soutient": "supports", "également": "also", "amendement": "amendment"}, "note": "This is how you say « also » — après le verbe, and never « Aussi » at the head."}]}, {"heading": "Setting one thing against another", "body": "mais joins inside a sentence and is fine everywhere, but a paragraph of a written test cannot open with it. cependant is the neutral written « however ». pourtant is « and yet »: it marks a contradiction that surprises, so it needs an expectation to defeat. en revanche puts two different things side by side, typically one drawback and one advantage — it is the connector of the option-weighing paragraph an EPSO note lives on. par contre means exactly the same as en revanche but is spoken register and is still marked down by careful readers, so keep it out of the exam. The English-speaker error is reaching for pourtant every time « however » appears: if nothing surprising is happening, you want cependant.", "table": {"cols": ["Connector", "Meaning", "Register", "Watch out"], "rows": [["mais", "but", "all", "joins inside a sentence; weak at the head of a written paragraph"], ["cependant", "however", "neutral, written", "the safe default in a note"], ["pourtant", "and yet", "all", "needs something surprising; not a plain « however »"], ["en revanche", "on the other hand", "written", "compares two different things, one plus one minus"], ["par contre", "on the other hand", "spoken", "same meaning as en revanche, wrong register for the exam"], ["alors que / tandis que", "whereas", "all", "conjunction + indicative, joins two clauses"], ["quand même", "all the same", "spoken", "goes after the verb: « il l'a fait quand même »"]]}, "examples": [{"fr": "Le rapport est clair ; cependant, il ne propose aucune solution.", "en": "The report is clear; however, it proposes no solution.", "gloss": {"aucune": "no, not any"}, "note": "Plain « however »: cependant."}, {"fr": "Nous avons envoyé le projet dix jours à l'avance. Pourtant, personne ne l'avait lu.", "en": "We sent the draft ten days in advance. And yet nobody had read it.", "gloss": {"à l'avance": "in advance", "personne": "nobody"}, "note": "Ten days should have been enough — the expectation is defeated, so pourtant."}, {"fr": "Le premier scénario est coûteux ; en revanche, il est rapide à mettre en œuvre.", "en": "The first scenario is expensive; on the other hand, it is quick to implement.", "gloss": {"coûteux": "expensive", "mettre en œuvre": "to implement"}, "note": "One minus, one plus, same object: en revanche."}, {"fr": "La délégation française soutient le texte, alors que la délégation belge demande un report.", "en": "The French delegation supports the text, whereas the Belgian delegation is asking for a postponement.", "gloss": {"alors que": "whereas", "report": "postponement"}, "note": "alors que is a conjunction: it takes a clause and stays inside the sentence."}]}, {"heading": "Giving the reason", "body": "Four conjunctions do this job and all four take the indicative — there is no subjunctive after any of them, whatever your instinct says. parce que gives the reason as new information and is the only one that answers the question « Pourquoi ? » on its own. car justifies what you have just written and can never open a sentence: it always attaches to something already said. puisque signals a reason the reader already knows or accepts — « since you have already read the report ». comme puts the cause first and therefore opens the sentence; used in the middle it stops meaning « since ». For a cause expressed as a noun you need a preposition instead: à cause de blames, grâce à thanks, en raison de is the neutral administrative form and is what a note to a head of unit uses.", "table": {"cols": ["Connector", "What follows", "What it signals", "Register"], "rows": [["parce que", "clause, indicative", "the reason as new information; answers « pourquoi ? »", "all"], ["car", "clause, indicative", "justifies what you just said; never opens a sentence", "neutral, written"], ["puisque", "clause, indicative", "a reason the reader already knows or accepts", "all"], ["comme", "clause, indicative", "cause first — comme opens the sentence", "all"], ["à cause de", "noun", "a cause you are complaining about", "all"], ["grâce à", "noun", "a cause you are pleased about", "all"], ["en raison de", "noun", "neutral, administrative", "written"]]}, "examples": [{"fr": "Comme la salle était déjà prise, nous avons fait la réunion en ligne.", "en": "Since the room was already taken, we held the meeting online.", "gloss": {"prise": "taken", "en ligne": "online"}, "note": "comme first, main clause second. That order is obligatory."}, {"fr": "Je ne peux pas venir jeudi, car je suis en mission à Luxembourg.", "en": "I can't come on Thursday, as I'm on mission in Luxembourg.", "gloss": {"en mission": "on a work trip"}, "note": "car justifies the statement in front of it — you could never start the message with it."}, {"fr": "Puisque vous connaissez déjà le dossier, je vous envoie directement la version consolidée.", "en": "Since you already know the file, I'm sending you the consolidated version straight away.", "gloss": {"consolidée": "consolidated"}, "note": "puisque: the reason is common ground between you and the reader."}, {"fr": "Le tram 92 ne circule pas en raison d'une grève à la STIB.", "en": "Tram 92 is not running owing to a strike at the STIB.", "gloss": {"circule": "runs", "grève": "strike"}, "note": "A noun follows, so a preposition is needed. « à cause d'une grève » is also correct but blames; en raison de is the neutral form on the STIB screens."}]}, {"heading": "Drawing the consequence", "body": "donc is the neutral all-purpose one, and native speakers usually put it after the verb rather than at the head: « il faut donc revoir le calendrier ». alors is the spoken narrative « so then », and du coup, which you will hear in every Brussels office kitchen, is squarely spoken — both are wrong in a note. par conséquent is the formal written one and opens the clause. c'est pourquoi opens a sentence and points back to the whole of what came before. ainsi means « thus » and also « in this way », so keep it for a consequence that is also a demonstration. The English-speaker error here is starting every sentence of an essay with « Donc », which reads as a spoken tic; vary it, and put donc after the verb when you can.", "table": {"cols": ["Connector", "Meaning", "Register", "Position"], "rows": [["donc", "so, therefore", "all", "best after the verb: « nous avons donc reporté »"], ["alors", "so then", "spoken, narrative", "opens the clause"], ["du coup", "so, as a result", "very spoken", "never in a note"], ["c'est pourquoi", "that is why", "written", "opens the sentence"], ["par conséquent", "consequently", "formal, written", "opens the clause, after a semicolon or full stop"], ["ainsi", "thus, in this way", "written", "opens the sentence"], ["d'où + noun", "hence the…", "written", "takes a noun, not a clause: « d'où le report »"]]}, "examples": [{"fr": "Le quorum n'était pas atteint ; par conséquent, le vote a été reporté.", "en": "The quorum was not reached; consequently, the vote was postponed.", "gloss": {"atteint": "reached", "reporté": "postponed"}, "note": "Formal written consequence, after a semicolon."}, {"fr": "La note est trop longue ; il faut donc la raccourcir avant vendredi.", "en": "The note is too long, so it has to be shortened before Friday.", "gloss": {"raccourcir": "to shorten"}, "note": "donc sits after the verb. « Donc il faut la raccourcir » is possible but sounds spoken."}, {"fr": "Le dossier est sensible. C'est pourquoi je préfère en parler de vive voix.", "en": "The file is sensitive. That is why I would rather talk about it face to face.", "gloss": {"sensible": "sensitive", "de vive voix": "face to face, in person"}, "note": "c'est pourquoi points back at the previous sentence as a whole."}, {"fr": "Trois États membres ont demandé un délai ; d'où le report du vote.", "en": "Three member states asked for more time; hence the postponement of the vote.", "gloss": {"délai": "extra time, time limit", "report": "postponement"}, "note": "d'où takes a noun. There is no verb in the second half, and that is correct."}]}, {"heading": "Sequence, and pointing to an example", "body": "A note or an essay that says d'abord, ensuite, enfin has already shown its plan to the marker. Use tout d'abord or premièrement to open, ensuite or par la suite in the middle, enfin or en dernier lieu to close. The trap is finalement: it does not mean « finally » as the last item of a list, it means « in the end, contrary to what was planned ». For examples, par exemple is neutral, notamment means « in particular, among others » and is the workhorse of EU French, and c'est-à-dire or à savoir introduces not an example but a restatement of exactly the same thing. notamment is not the English « notably » in the sense of « remarkably ».", "table": {"cols": ["Connector", "Meaning", "Register", "Watch out"], "rows": [["tout d'abord / d'abord", "first of all", "all", "opens the list"], ["ensuite / puis", "then, next", "all", "puis is slightly more spoken"], ["enfin", "lastly", "all", "the last item of a list"], ["finalement", "in the end, as it turned out", "all", "NOT the last item of a list — a false friend of « finally »"], ["par exemple", "for example", "all", "one case among many"], ["notamment", "in particular, including", "written", "a partial list, not « notably = remarkably »"], ["c'est-à-dire / à savoir", "that is to say, namely", "written", "the same thing said again, not an example"]]}, "examples": [{"fr": "D'abord, je résume la position du groupe ; ensuite, je propose deux options ; enfin, je recommande la deuxième.", "en": "First I summarise the group's position; then I set out two options; lastly I recommend the second.", "gloss": {"résume": "summarise", "recommande": "recommend"}, "note": "Three moves, three markers. This alone shows the marker your plan."}, {"fr": "Plusieurs délégations, notamment la Belgique et l'Irlande, ont demandé un report.", "en": "Several delegations, Belgium and Ireland in particular, asked for a postponement.", "gloss": {"notamment": "in particular, including", "report": "postponement"}, "note": "notamment names some of them, not all of them."}, {"fr": "Nous avions prévu un vote ; finalement, la présidence a préféré un tour de table.", "en": "We had planned a vote; in the end the presidency preferred a round of comments.", "gloss": {"prévu": "planned", "tour de table": "round of comments from each delegation"}, "note": "finalement = things turned out otherwise. Use enfin for the last point of a list."}]}, {"heading": "Closing, and the four false friends that wreck a paragraph", "body": "Close with en résumé, pour conclure, en conclusion or pour finir; bref is the spoken version and has no place in a note. Then learn these four words, because each of them turns a sentence into nonsense for a French reader. actuellement means « currently », not « actually » — for « actually » say en fait or en réalité. éventuellement means « possibly, if need be », not « eventually » — for « eventually » say finalement or à terme. en effet is not « in effect »: it confirms what you just said and introduces its reason, whereas en fait corrects what the reader was assuming. And or, which you will meet properly at B2, is never the English « or »: the English « or » is ou.", "table": {"cols": ["French word", "Looks like", "Actually means", "Say the English idea with"], "rows": [["actuellement", "actually", "currently, at the moment", "en fait, en réalité"], ["éventuellement", "eventually", "possibly, if need be", "finalement, à terme"], ["en effet", "in effect", "indeed — and here is the reason", "en fait (actually), concrètement (in practice)"], ["finalement", "finally (last in a list)", "in the end, as it turned out", "enfin"], ["or", "or", "now; and yet (a new fact that changes things)", "ou"], ["notamment", "notably (= remarkably)", "in particular, including", "remarquablement (rarely what you mean)"]]}, "examples": [{"fr": "Je travaille actuellement à la DG Emploi, mais je change d'unité en janvier.", "en": "I currently work at DG Employment, but I'm changing unit in January.", "gloss": {"actuellement": "currently", "unité": "unit"}, "note": "« Actually I work at… » would be « En fait, je travaille… »."}, {"fr": "Le texte n'est pas encore adopté ; en effet, deux États membres bloquent le compromis.", "en": "The text has not yet been adopted; indeed, two member states are blocking the compromise.", "gloss": {"adopté": "adopted", "bloquent": "are blocking"}, "note": "en effet confirms the statement and gives its reason."}, {"fr": "— Le rapport est prêt ? — En fait, il manque encore l'annexe statistique.", "en": "— Is the report ready? — Actually, the statistical annex is still missing.", "gloss": {"manque": "is missing", "annexe": "annex"}, "note": "en fait corrects the assumption in the question."}, {"fr": "En résumé, la proposition est acceptable sur le fond mais irréaliste sur le calendrier.", "en": "In short, the proposal is acceptable in substance but unrealistic on the timetable.", "gloss": {"sur le fond": "in substance", "calendrier": "timetable"}, "note": "A closing line a head of unit can read on its own. « Bref » would be the corridor version."}]}], "recognise": [{"id": "gr-connectors-B1-01", "level": "B1", "format": "cloze", "q": "J'ai raté mon tram, ___ je suis arrivé en retard au bureau.", "options": ["car", "pourtant", "puisque", "donc"], "a": 3, "trap": "car — it fills the same slot but points the other way: it would make arriving late the reason for missing the tram", "expl": "The second clause is the result, so you need a consequence connector: donc. car and puisque introduce a cause, and pourtant would claim the lateness was surprising."}, {"id": "gr-connectors-B1-02", "level": "B1", "format": "cloze", "q": "Le premier scénario coûte plus cher ; ___, il peut être mis en œuvre en six mois.", "options": ["par conséquent", "en revanche", "de plus", "c'est pourquoi"], "a": 1, "trap": "de plus — it adds a point on the same side, but here the second fact pulls the other way", "expl": "One drawback then one advantage about the same object is exactly what en revanche marks. par conséquent and c'est pourquoi both announce a consequence, which the sentence does not contain."}, {"id": "gr-connectors-B1-03", "level": "B1", "format": "cloze", "q": "In a written note to your head of unit: « Le calendrier est très serré ; ___, nous proposons de reporter la réunion. »", "options": ["du coup", "alors", "par conséquent", "et puis"], "a": 2, "trap": "du coup — everyone says it in the corridor, and it is pure spoken French; in a written note it marks you down", "expl": "All four announce a consequence; only the register differs. par conséquent is the written form. alors and et puis are narrative speech, du coup is informal speech."}, {"id": "gr-connectors-B1-04", "level": "B1", "format": "cloze", "q": "___ vous avez déjà lu le rapport, je ne joins que le résumé.", "options": ["Parce que", "Puisque", "Car", "Donc"], "a": 1, "trap": "Parce que — grammatically possible at the head of a sentence, but it presents the reason as news; here the reader knows it already", "expl": "puisque signals a reason the reader already accepts. parce que gives the reason as new information, car can never open a sentence, and donc would announce a result instead of a reason."}, {"id": "gr-connectors-B1-05", "level": "B1", "format": "cloze", "q": "A note for the file: « La demande est incomplète ; ___, elle a été transmise hors délai. »", "options": ["pourtant", "en plus", "en outre", "donc"], "a": 2, "trap": "en plus — the same meaning exactly, but it is spoken register and looks careless in a written note", "expl": "Two complaints stacked on the same side call for an addition connector, and the written one is en outre (or de plus). pourtant would claim a contradiction and donc a consequence."}, {"id": "gr-connectors-B1-06", "level": "B1", "format": "cloze", "q": "Le texte doit être adopté par les colégislateurs, ___ le Parlement européen et le Conseil.", "options": ["notamment", "par exemple", "c'est-à-dire", "en particulier"], "a": 2, "trap": "notamment — « including, among others »; but the Parliament and the Council are not examples, they are the complete list", "expl": "c'est-à-dire restates exactly the same thing in other words. notamment, par exemple and en particulier all announce a partial list, which would be false here: there are only two colegislators."}, {"id": "gr-connectors-B1-07", "level": "B1", "format": "cloze", "q": "Je travaille ___ à la DG Emploi, mais je change d'unité en janvier.", "options": ["éventuellement", "actuellement", "finalement", "récemment"], "a": 1, "trap": "éventuellement — it looks like « eventually » and means « possibly, if need be »", "expl": "actuellement means « currently ». For the English « actually » use en fait; for « eventually » use finalement or à terme."}, {"id": "gr-connectors-B1-08", "level": "B1", "format": "cloze", "q": "D'abord je présente le contexte, ensuite les deux options, ___ je recommande une solution.", "options": ["enfin", "finalement", "au final", "en fin de compte"], "a": 0, "trap": "finalement — a false friend: it means « in the end, contrary to plan », not « lastly »", "expl": "enfin closes a list: d'abord, ensuite, enfin. finalement, au final and en fin de compte all narrate how something turned out."}, {"id": "gr-connectors-B1-09", "level": "B1", "format": "cloze", "q": "Le vote a été reporté ___ l'absence de quorum.", "options": ["grâce à", "malgré", "en raison de", "au lieu de"], "a": 2, "trap": "grâce à — it sits in the same slot and takes the same noun, but it marks a cause you are pleased about", "expl": "All four are prepositions taking a noun. en raison de is the neutral administrative cause. grâce à thanks, malgré concedes, au lieu de replaces."}], "drills": [{"id": "gd-connectors-B1-01", "level": "B1", "format": "collocation", "q": "One of these four sentences puts its connector somewhere French never allows. Which one?", "options": ["Car la salle était prise, nous nous sommes réunis en ligne.", "Comme la salle était prise, nous nous sommes réunis en ligne.", "Puisque la salle était prise, nous nous sommes réunis en ligne.", "Parce que la salle était prise, nous nous sommes réunis en ligne."], "a": 0, "trap": "Parce que at the head of a sentence — unusual, but perfectly legal; car is the one that is banned there", "expl": "car always attaches to something already said, so it can never open a sentence or come first in a pair of clauses. comme, puisque and parce que can all be fronted."}, {"id": "gd-connectors-B1-02", "level": "B1", "format": "cloze", "q": "Le rapport a pris du retard ; ___, le service juridique a demandé une seconde relecture.", "options": ["en fait", "en effet", "en revanche", "enfin"], "a": 1, "trap": "en fait — the near neighbour: it corrects what the reader assumed, and here nothing is being corrected", "expl": "en effet confirms the statement you just made and gives the reason for it. en fait would signal « no, actually it is not what you think »."}, {"id": "gd-connectors-B1-03", "level": "B1", "format": "cloze", "q": "Le scénario A est coûteux ; le scénario B, ___, tient dans l'enveloppe budgétaire.", "options": ["en revanche", "pourtant", "de plus", "donc"], "a": 0, "trap": "pourtant — it contradicts an expectation about the same thing; here two different scenarios are being compared", "expl": "en revanche sets two distinct objects against each other, which is what an options paragraph does. pourtant would need an expectation about scenario B to defeat, and none has been set."}, {"id": "gd-connectors-B1-04", "level": "B1", "format": "cloze", "q": "An official note: « Le délai initial ne peut être tenu ; ___, la publication est repoussée à septembre. »", "options": ["du coup", "alors", "par conséquent", "et donc"], "a": 2, "trap": "et donc — correct French and very common in speech, but a note wants the single formal connector", "expl": "Written administrative register takes par conséquent (or en conséquence). alors is narrative speech, du coup is informal, and « et donc » is the spoken way of stringing clauses together."}, {"id": "gd-connectors-B1-05", "level": "B1", "format": "cloze", "q": "A note to your head of unit, neutral administrative register: « La réunion du groupe de travail a été reportée ___ la grève des transports. »", "options": ["à cause de", "grâce à", "malgré", "en raison de"], "a": 3, "trap": "à cause de — correct French, but it attributes blame and is conversational; a note uses the neutral form", "expl": "en raison de is the neutral administrative cause and the form you will read on any official notice. à cause de blames, grâce à credits, malgré concedes."}, {"id": "gd-connectors-B1-06", "level": "B1", "format": "cloze", "q": "Two colleagues at the coffee machine: « Le tram était supprimé, ___ j'ai pris le bus. »", "options": ["du coup", "par conséquent", "c'est pourquoi", "en conséquence"], "a": 0, "trap": "par conséquent — impeccable French, absurdly formal standing at a coffee machine", "expl": "Register works in both directions. Spoken French takes du coup or alors; par conséquent, c'est pourquoi and en conséquence belong to written notes."}, {"id": "gd-connectors-B1-07", "level": "B1", "format": "collocation", "q": "You want to write « The unit is short-staffed. Also, the deadline has been brought forward. » Which second sentence is right?", "options": ["De plus, le délai a été avancé.", "Aussi, le délai a été avancé.", "Aussi le délai a été avancé.", "Également le délai a été avancé."], "a": 0, "trap": "« Aussi, … » — the word an English speaker reaches for; at the head of a sentence aussi means « therefore » and requires inversion (« Aussi le délai a-t-il été avancé »)", "expl": "For « also » adding a point, open with De plus or En outre. également does mean « also » but goes after the verb: « le délai a également été avancé »."}, {"id": "gd-connectors-B1-08", "level": "B1", "format": "cloze", "q": "Le règlement s'applique à toutes les agences, ___ celles qui n'ont pas de personnalité juridique.", "options": ["c'est-à-dire", "y compris", "à savoir", "autrement dit"], "a": 1, "trap": "à savoir — it announces the complete list, but « toutes les agences » has already covered everything; what follows is a subset you are insisting on", "expl": "y compris singles out a sub-group inside a set already named in full. c'est-à-dire, à savoir and autrement dit all restate the whole set in other words."}, {"id": "gd-connectors-B1-09", "level": "B1", "format": "cloze", "q": "— Pourquoi la réunion a-t-elle été annulée ? — ___ le président est souffrant.", "options": ["Parce que", "Puisque", "Car", "Comme"], "a": 0, "trap": "Puisque — the reason as common ground; but the question shows the asker does not know it yet", "expl": "Only parce que answers a « pourquoi ? » question directly. car cannot open an utterance, comme would need its main clause after it, and puisque would wrongly treat the reason as already known."}, {"id": "gd-connectors-B1-10", "level": "B1", "format": "cloze", "q": "Nous pourrons ___ revoir le calendrier si le Conseil le demande.", "options": ["finalement", "éventuellement", "actuellement", "effectivement"], "a": 1, "trap": "finalement — this is what English « eventually » actually means; éventuellement is « possibly »", "expl": "éventuellement = possibly, if need be, which is what « si le Conseil le demande » sets up. actuellement is « currently » and effectivement is « indeed »."}, {"id": "gd-connectors-B1-11", "level": "B1", "format": "cloze", "q": "Trois arguments : d'abord le coût, ensuite le calendrier, ___ l'acceptabilité politique.", "options": ["au final", "en fin de compte", "enfin", "finalement"], "a": 2, "trap": "finalement — the direct-looking translation of « finally », but it narrates an outcome instead of closing a list", "expl": "enfin is the list-closing word that pairs with d'abord and ensuite. finalement, au final and en fin de compte all mean « in the end, as it turned out »."}, {"id": "gd-connectors-B1-12", "level": "B1", "format": "cloze", "q": "La délégation allemande soutient le compromis, ___ la délégation polonaise demande un nouveau tour de négociation.", "options": ["pendant que", "alors que", "depuis que", "dès que"], "a": 1, "trap": "pendant que — the same slot and the same indicative clause, but it only says « at the same time as »; it carries no contrast", "expl": "alors que (and tandis que) can mean « whereas » and set two positions against each other. The other three are purely temporal."}, {"id": "gd-connectors-B1-13", "level": "B1", "format": "cloze", "q": "Je vous confirme que la note sera prête vendredi. ___, je serai absent toute la semaine prochaine.", "options": ["D'ailleurs", "Par ailleurs", "Pourtant", "Par conséquent"], "a": 1, "trap": "D'ailleurs — one letter apart and a different job: it adds a remark that supports what you just said, and being away does not support the note being ready", "expl": "par ailleurs opens a separate matter — « on another point ». d'ailleurs offers extra evidence for the claim just made."}, {"id": "gd-connectors-B1-14", "level": "B1", "format": "cloze", "q": "The last line of a written note: « ___, la proposition est défendable sur le fond mais irréaliste sur le calendrier. »", "options": ["Bref", "En fait", "Enfin", "En résumé"], "a": 3, "trap": "Bref — the same meaning, but it is the spoken version and out of place in a written note", "expl": "En résumé (or Pour conclure, En conclusion) closes a written text. En fait corrects, and Enfin only marks the last item of a list."}, {"id": "gd-connectors-B1-15", "level": "B1", "format": "cloze", "q": "Nous avons pu boucler le dossier dans les délais ___ l'aide du secrétariat.", "options": ["à cause de", "grâce à", "en raison de", "faute de"], "a": 1, "trap": "à cause de — the same slot, the same noun, the opposite colour: it blames the cause instead of thanking it", "expl": "grâce à marks a cause with a welcome result. à cause de complains, en raison de is neutral and impersonal, faute de means « for want of »."}, {"id": "gd-connectors-B1-16", "level": "B1", "format": "collocation", "q": "Which version would an EPSO marker accept in a written note for « The room was not booked, so we met online »?", "options": ["La salle n'était pas réservée, nous nous sommes donc réunis en ligne.", "La salle n'était pas réservée, nous nous sommes réunis en ligne.", "La salle n'était pas réservée nous nous sommes réunis en ligne.", "La salle n'était pas réservée, alors on s'est réunis en ligne."], "a": 0, "trap": "« La salle n'était pas réservée, alors on s'est réunis en ligne » — correct French, but « alors » plus « on s'est réunis » is spoken register and loses marks in a note", "expl": "Two full clauses need a connector, not a bare comma. donc inside the second clause is the neutral written solution; the versions with a bare comma, or with no punctuation at all, are comma splices."}, {"id": "gd-connectors-B1-17", "level": "B1", "format": "cloze", "q": "— La version consolidée est prête ? — ___, il manque encore l'avis du service juridique.", "options": ["En effet", "En fait", "En outre", "En résumé"], "a": 1, "trap": "En effet — it would confirm that the version is ready, and the answer does the opposite", "expl": "en fait corrects the assumption behind the question. en effet confirms and explains the statement in front of it."}], "write": [{"id": "gw-connectors-B1-01", "prompt": "Write in French: « I can't come to the working party on Thursday, as I'll be on mission in Luxembourg. » Use car.", "answer": "Je ne pourrai pas venir au groupe de travail jeudi, car je serai en mission à Luxembourg.", "accept": ["je ne pourrai pas venir au groupe de travail jeudi car je serai en mission à luxembourg", "je ne peux pas venir au groupe de travail jeudi car je serai en mission à luxembourg", "je ne pourrai pas assister au groupe de travail jeudi car je serai en mission à luxembourg", "je ne peux pas assister au groupe de travail jeudi car je serai en mission à luxembourg", "je ne pourrai pas être au groupe de travail jeudi car je serai en mission à luxembourg", "je ne pourrai pas venir au groupe de travail jeudi car je suis en mission à luxembourg"], "hint": "car + clause, and it comes second — never at the head.", "expl": "car justifies the statement in front of it, so the refusal comes first and the reason second."}, {"id": "gw-connectors-B1-02", "prompt": "Same idea, cause first: « Since the room was already taken, we held the meeting online. » Use comme.", "answer": "Comme la salle était déjà prise, nous avons fait la réunion en ligne.", "accept": ["comme la salle était déjà prise nous avons fait la réunion en ligne", "comme la salle était déjà prise nous avons organisé la réunion en ligne", "comme la salle était déjà réservée nous avons fait la réunion en ligne", "comme la salle était prise nous avons fait la réunion en ligne", "comme la salle était déjà occupée nous avons fait la réunion en ligne", "comme la salle était déjà prise nous nous sommes réunis en ligne"], "hint": "comme opens the sentence; the main clause follows the comma.", "expl": "comme meaning « since » only works in first position. In the middle of a sentence it stops meaning cause."}, {"id": "gw-connectors-B1-03", "prompt": "The reader already knows the reason. Write: « Since you have already read the report, I'm only attaching the summary. » Use puisque.", "answer": "Puisque vous avez déjà lu le rapport, je ne joins que le résumé.", "accept": ["puisque vous avez déjà lu le rapport je ne joins que le résumé", "puisque vous avez déjà lu le rapport je joins seulement le résumé", "puisque vous avez déjà lu le rapport je vous envoie seulement le résumé", "puisque vous avez déjà lu le rapport je vous envoie uniquement le résumé", "puisque vous avez déjà lu le rapport je n'envoie que le résumé"], "hint": "puisque + indicative; vous, because it is a note to a colleague.", "expl": "puisque presents the reason as common ground. parce que would offer it as news the reader does not have."}, {"id": "gw-connectors-B1-04", "prompt": "Written note, formal consequence: « The quorum was not reached; consequently, the vote was postponed. »", "answer": "Le quorum n'était pas atteint ; par conséquent, le vote a été reporté.", "accept": ["le quorum n'était pas atteint par conséquent le vote a été reporté", "le quorum n'était pas atteint par conséquent le vote a été repoussé", "le quorum n'a pas été atteint par conséquent le vote a été reporté", "le quorum n'était pas atteint en conséquence le vote a été reporté", "le quorum n'était pas atteint c'est pourquoi le vote a été reporté"], "hint": "par conséquent opens the second clause, after a semicolon.", "expl": "par conséquent is the written consequence connector. du coup and alors would drop the note into spoken register."}, {"id": "gw-connectors-B1-05", "prompt": "Plain « however »: « The report is clear; however, it proposes no solution. »", "answer": "Le rapport est clair ; cependant, il ne propose aucune solution.", "accept": ["le rapport est clair cependant il ne propose aucune solution", "le rapport est clair cependant il ne propose pas de solution", "le rapport est clair toutefois il ne propose aucune solution", "le rapport est clair cependant aucune solution n'est proposée", "le rapport est clair mais il ne propose aucune solution"], "hint": "Nothing surprising is happening, so not pourtant.", "expl": "cependant is the neutral written « however ». pourtant would claim the absence of a solution defeats an expectation."}, {"id": "gw-connectors-B1-06", "prompt": "Weigh two options: « The first scenario is expensive; on the other hand, it can be implemented in six months. »", "answer": "Le premier scénario est coûteux ; en revanche, il peut être mis en œuvre en six mois.", "accept": ["le premier scénario est coûteux en revanche il peut être mis en œuvre en six mois", "le premier scénario est cher en revanche il peut être mis en œuvre en six mois", "le premier scénario est coûteux en revanche il est rapide à mettre en œuvre", "le premier scénario coûte cher en revanche il peut être mis en œuvre en six mois", "le premier scénario est coûteux en revanche il peut être appliqué en six mois"], "hint": "One minus, one plus, same object.", "expl": "en revanche is the option-weighing connector an EPSO note needs. par contre says the same thing in spoken register."}, {"id": "gw-connectors-B1-07", "prompt": "Stack a second complaint, written register: « The file is incomplete; moreover, it arrived after the deadline. » Use de plus or en outre.", "answer": "Le dossier est incomplet ; de plus, il est arrivé après la date limite.", "accept": ["le dossier est incomplet de plus il est arrivé après la date limite", "le dossier est incomplet en outre il est arrivé après la date limite", "le dossier est incomplet de plus il a été transmis après la date limite", "le dossier est incomplet en outre il a été transmis hors délai", "le dossier est incomplet de plus il est arrivé hors délai"], "hint": "Not « en plus », which is spoken.", "expl": "de plus and en outre are the written addition connectors; en plus belongs to speech."}, {"id": "gw-connectors-B1-08", "prompt": "Announce a three-part plan in one sentence: first the context, then two options, lastly a recommendation.", "answer": "D'abord, je présente le contexte ; ensuite, j'expose deux options ; enfin, je recommande une solution.", "accept": ["d'abord je présente le contexte ensuite j'expose deux options enfin je recommande une solution", "tout d'abord je présente le contexte ensuite je présente deux options enfin je recommande une solution", "d'abord je présente le contexte ensuite je propose deux options enfin je recommande une solution", "premièrement je présente le contexte ensuite j'expose deux options enfin je recommande une solution", "d'abord je présente le contexte puis j'expose deux options enfin je recommande une solution"], "hint": "d'abord … ensuite … enfin. Not finalement.", "expl": "This one sentence shows the marker your plan. finalement would mean « in the end, contrary to plan »."}, {"id": "gw-connectors-B1-09", "prompt": "A cause expressed as a noun, official register: « Tram 92 is not running owing to a strike at the STIB. »", "answer": "Le tram 92 ne circule pas en raison d'une grève à la STIB.", "accept": ["le tram 92 ne circule pas en raison d'une grève à la stib", "le tram 92 ne roule pas en raison d'une grève à la stib", "le tram 92 ne circule pas en raison d'un mouvement de grève à la stib", "le tram 92 est supprimé en raison d'une grève à la stib", "le tram 92 ne circule pas à cause d'une grève à la stib"], "hint": "A noun follows, so a preposition, not parce que.", "expl": "en raison de + noun is the neutral administrative cause. « en raison que » does not exist; with a clause you would need parce que."}, {"id": "gw-connectors-B1-10", "prompt": "Point to part of a list: « Several delegations, Belgium and Ireland in particular, asked for a postponement. »", "answer": "Plusieurs délégations, notamment la Belgique et l'Irlande, ont demandé un report.", "accept": ["plusieurs délégations notamment la belgique et l'irlande ont demandé un report", "plusieurs délégations notamment la belgique et l'irlande ont demandé un report du vote", "plusieurs délégations en particulier la belgique et l'irlande ont demandé un report", "plusieurs délégations notamment la belgique et l'irlande ont demandé le report du point", "plusieurs délégations dont la belgique et l'irlande ont demandé un report"], "hint": "notamment sits between two commas.", "expl": "notamment means « in particular, among others » — a partial list. c'est-à-dire would claim these were the only delegations."}, {"id": "gw-connectors-B1-11", "prompt": "Close a note: « In short, the proposal is acceptable in substance but unrealistic on the timetable. »", "answer": "En résumé, la proposition est acceptable sur le fond mais irréaliste sur le calendrier.", "accept": ["en résumé la proposition est acceptable sur le fond mais irréaliste sur le calendrier", "en conclusion la proposition est acceptable sur le fond mais irréaliste sur le calendrier", "pour conclure la proposition est acceptable sur le fond mais irréaliste sur le calendrier", "en résumé la proposition est acceptable sur le fond mais irréaliste quant au calendrier", "en résumé la proposition est acceptable sur le fond mais le calendrier est irréaliste"], "hint": "Written closing formula, not « Bref ».", "expl": "En résumé, Pour conclure and En conclusion all close a written text. Bref is the spoken equivalent."}], "apply": [{"id": "ga-connectors-B1-01", "situation": "You are writing a short note to your head of unit. The working party meeting has to move because of a transport strike in Brussels.", "task": "In one sentence, announce the postponement and give the reason in neutral administrative register (a noun, not a clause).", "accept": ["la réunion du groupe de travail est reportée en raison de la grève des transports", "la réunion du groupe de travail a été reportée en raison de la grève des transports", "je vous informe que la réunion du groupe de travail est reportée en raison de la grève des transports", "la réunion du groupe de travail est reportée en raison d'une grève des transports", "la réunion du groupe de travail est reportée en raison de la grève à la stib", "la réunion est reportée en raison de la grève des transports"], "model": "La réunion du groupe de travail est reportée en raison de la grève des transports.", "expl": "en raison de + noun is the register a note takes. « à cause de » would blame, and « parce qu'il y a une grève » would drop into speech."}, {"id": "ga-connectors-B1-02", "situation": "Same note, next line. You want to add a second, separate problem: the Dutch translation is not ready either.", "task": "Write one sentence adding this second point in written register.", "accept": ["par ailleurs la traduction néerlandaise n'est pas encore disponible", "par ailleurs la traduction en néerlandais n'est pas encore disponible", "de plus la traduction néerlandaise n'est pas encore disponible", "en outre la traduction néerlandaise n'est pas encore disponible", "en outre la traduction en néerlandais n'est pas encore prête", "par ailleurs la version néerlandaise n'est pas encore disponible"], "model": "Par ailleurs, la traduction néerlandaise n'est pas encore disponible.", "expl": "par ailleurs opens a separate matter; de plus and en outre also work. « En plus » is spoken and « D'ailleurs » would claim this supports the previous point."}, {"id": "ga-connectors-B1-03", "situation": "You are writing the summary of a Council working party meeting for a colleague who was not there. Two delegations took opposite positions.", "task": "In one sentence, report that the German delegation supports the compromise whereas the Polish delegation wants a further round of negotiation.", "accept": ["la délégation allemande soutient le compromis alors que la délégation polonaise demande un nouveau tour de négociation", "la délégation allemande soutient le compromis tandis que la délégation polonaise demande un nouveau tour de négociation", "la délégation allemande soutient le compromis alors que la délégation polonaise souhaite un nouveau tour de négociation", "la délégation allemande est favorable au compromis alors que la délégation polonaise demande un nouveau tour de négociation", "la délégation allemande soutient le compromis en revanche la délégation polonaise demande un nouveau tour de négociation", "la délégation allemande soutient le texte tandis que la délégation polonaise demande une nouvelle négociation"], "model": "La délégation allemande soutient le compromis, alors que la délégation polonaise demande un nouveau tour de négociation.", "expl": "alors que and tandis que carry the contrast inside one sentence; en revanche does the same job across two clauses."}, {"id": "ga-connectors-B1-04", "situation": "Your note has explained that the file is incomplete and late. You now have to state what follows from that.", "task": "Write one sentence drawing the consequence in formal written register: the examination of the point is postponed to the next meeting.", "accept": ["par conséquent l'examen du point est reporté à la prochaine réunion", "par conséquent l'examen de ce point est reporté à la prochaine réunion", "c'est pourquoi l'examen du point est reporté à la prochaine réunion", "en conséquence l'examen du point est reporté à la prochaine réunion", "par conséquent l'examen du point est repoussé à la prochaine réunion", "par conséquent ce point est reporté à la prochaine réunion"], "model": "Par conséquent, l'examen de ce point est reporté à la prochaine réunion.", "expl": "par conséquent, c'est pourquoi and en conséquence are the written consequence connectors. du coup would be a corridor sentence in a formal note."}, {"id": "ga-connectors-B1-05", "situation": "A colleague at the commune of Ixelles already knows that your file has been transferred to another service — you told her yesterday.", "task": "Write one sentence telling her that, since she already knows, you are sending the reference number straight away.", "accept": ["puisque vous êtes déjà au courant je vous envoie directement le numéro de référence", "puisque vous êtes déjà au courant je vous transmets directement le numéro de référence", "puisque vous connaissez déjà le dossier je vous envoie directement le numéro de référence", "puisque vous savez déjà que le dossier a été transféré je vous envoie directement le numéro de référence", "puisque vous êtes déjà informée je vous envoie directement le numéro de référence", "puisque vous connaissez déjà le dossier je vous transmets directement la référence"], "model": "Puisque vous êtes déjà au courant, je vous envoie directement le numéro de référence.", "expl": "puisque is the connector for a reason both of you already accept. parce que would offer it as news she does not have."}, {"id": "ga-connectors-B1-06", "situation": "You are closing a one-page note to your head of unit on a Commission proposal.", "task": "Write the closing sentence: in short, the proposal is acceptable in substance but the timetable is unrealistic.", "accept": ["en résumé la proposition est acceptable sur le fond mais le calendrier est irréaliste", "en résumé la proposition est acceptable sur le fond mais irréaliste sur le calendrier", "pour conclure la proposition est acceptable sur le fond mais le calendrier est irréaliste", "en conclusion la proposition est acceptable sur le fond mais le calendrier est irréaliste", "en résumé la proposition est défendable sur le fond mais le calendrier est irréaliste", "pour finir la proposition est acceptable sur le fond mais le calendrier est irréaliste"], "model": "En résumé, la proposition est acceptable sur le fond, mais le calendrier est irréaliste.", "expl": "A closing connector plus a two-part verdict is what a head of unit reads first. Bref would be the spoken version of the same sentence."}]},
  "connectors-B2": {"slug": "connectors", "level": "B2", "title": "Les connecteurs logiques", "summary": "The register jump: or, néanmoins, toutefois, certes… mais, bien que and quoique with the subjunctive, dans la mesure où, si bien que, afin de against afin que, en dépit de against malgré — and the thèse / antithèse / synthèse shape they mark.", "why": "The EUFTE marker reads for structure, and at B2 the structure is an argued movement, not a list of points. These connectors are the ones that show a position being stated, conceded and resolved. One of them, « or », is the single most misused word in the French of English speakers, and using it correctly is instantly visible on the page.", "lesson": [{"heading": "« Or » — the hinge, and the word English speakers get wrong every time", "body": "or is not « or ». The English « or » is ou. French or introduces the fact that cuts across what has just been said: the new element that makes the argument turn. In a classical piece of reasoning it introduces the second premise — « Tout acte délégué doit être notifié. Or, celui-ci ne l'a pas été. Le vote est donc irrégulier. » In an EUFTE paragraph it is the word that opens your antithesis. It almost always starts a sentence and takes a comma after it. English speakers make three mistakes with it: they read it as « or » and are baffled by the sentence; they write it where they mean donc, because it stands in the position an English « so » would take; and, most often, they avoid it altogether — which costs them the one connector that proves to a marker they can turn an argument rather than list opinions.", "table": {"cols": ["Word", "Means", "What follows", "What it does"], "rows": [["or", "now; and yet", "a full clause", "brings in the fact that changes the argument"], ["ou", "or", "a word or a clause", "a plain alternative — this is the real « or »"], ["donc", "therefore", "a full clause", "the conclusion drawn afterwards"], ["en effet", "indeed, for", "a full clause", "supports what you have just said"], ["cependant", "however", "a full clause", "a plain contrast, with no argumentative turn"]]}, "examples": [{"fr": "La note annonce une économie de deux millions d'euros. Or, le tableau annexé fait état d'un surcoût.", "en": "The note announces a saving of two million euros. And yet the annexed table shows an extra cost.", "gloss": {"économie": "saving", "annexé": "annexed", "surcoût": "extra cost"}, "note": "or introduces the fact that contradicts the claim just made. This is the antithesis move in one word."}, {"fr": "Le règlement doit être adopté avant le 1er janvier. Or, le Parlement ne siège plus après le 15 décembre. Le calendrier est donc intenable.", "en": "The regulation must be adopted before 1 January. Now, Parliament does not sit after 15 December. The timetable is therefore untenable.", "gloss": {"siège": "sits, is in session", "intenable": "untenable"}, "note": "Premise, or + second premise, donc + conclusion. Learn this three-sentence shape; it is worth marks on its own."}, {"fr": "Vous pouvez répondre par écrit ou par oral.", "en": "You may reply in writing or orally.", "gloss": {"par écrit": "in writing", "par oral": "orally"}, "note": "This is the real « or »: ou. Writing « or » here is the mistake to kill first."}]}, {"heading": "The « however » ladder, and where French puts it", "body": "mais, cependant, toutefois and néanmoins are not interchangeable stylistic variants: they sit on a register ladder, and néanmoins carries an extra job. toutefois and néanmoins are formal written French — a note to a director, a considérant, an essay. néanmoins specifically takes back a concession you have just made, so it is the natural partner of certes. en revanche stays what it was at B1: two different objects compared. par contre means the same but is spoken and is still penalised by careful readers. Two placement points English speakers miss. First, these are adverbs, so two clauses joined by them need a semicolon or a full stop, never the bare comma English tolerates — « The solution is attractive, however it raises a legal problem » becomes a comma splice if you translate it word for word. Second, French likes to drop toutefois, cependant and néanmoins inside the clause, after the verb: « elle se heurte toutefois à une difficulté ». That placement reads as native and costs nothing to learn.", "table": {"cols": ["Connector", "Force", "Register", "Placement"], "rows": [["mais", "but", "all", "joins inside the sentence"], ["cependant", "however", "neutral, written", "opens the clause, or after the verb"], ["toutefois", "however, nevertheless", "formal, written", "opens the clause, or after the verb"], ["néanmoins", "nevertheless", "formal, written", "opens the clause; takes back a concession"], ["en revanche", "on the other hand", "written", "opens the clause; compares two objects"], ["par contre", "on the other hand", "spoken", "avoid in the written test"], ["il n'en demeure pas moins que", "the fact remains that", "very formal", "opens a clause + indicative"]]}, "examples": [{"fr": "La solution est séduisante ; elle se heurte toutefois à une difficulté juridique.", "en": "The solution is attractive; it does, however, run into a legal difficulty.", "gloss": {"séduisante": "attractive", "se heurte": "runs up against"}, "note": "toutefois after the verb, and a semicolon between the clauses — not a comma."}, {"fr": "Le délai est très serré ; néanmoins, un report n'est pas envisageable.", "en": "The deadline is very tight; nevertheless, a postponement is not an option.", "gloss": {"serré": "tight", "report": "postponement", "envisageable": "conceivable, an option"}, "note": "néanmoins pushes back after something has been granted."}, {"fr": "Le rapport est complet ; il n'en demeure pas moins que ses conclusions sont contestées.", "en": "The report is thorough; the fact remains that its conclusions are disputed.", "gloss": {"il n'en demeure pas moins que": "the fact remains that", "contestées": "disputed"}, "note": "The most formal rung of the ladder, and it takes the indicative."}]}, {"heading": "Conceding in order to win", "body": "The strongest paragraph an EUFTE candidate can write gives the other side its best sentence and then takes it back. French has fixed machinery for that. certes … mais is the workhorse: certes grants the point, mais recovers it. il est vrai que … néanmoins does the same at higher register. bien que and quoique take the subjunctive — always, with no exception you will meet — while même si, which does the same work in English, takes the indicative, and quand bien même takes the conditional. Two errors to name. The first is « Bien que le délai est court » : the indicative there is the most visible B1 mistake left in a B2 text. The second is the English habit of writing « Although X, but Y »: French allows the subordinator or the mais, never both. « Bien que le coût soit élevé, mais le gain le justifie » is wrong; drop the mais, or drop the bien que and use certes.", "table": {"cols": ["Structure", "Mood after it", "Register", "Opener"], "rows": [["certes … mais …", "indicative", "all, very common in writing", "Certes, le coût est élevé, mais…"], ["il est vrai que … néanmoins", "indicative", "written", "Il est vrai que le délai est court ; néanmoins…"], ["bien que", "SUBJUNCTIVE", "all", "Bien que le délai soit court…"], ["quoique (one word)", "SUBJUNCTIVE", "written", "Quoique le délai soit court…"], ["quoi que (two words)", "SUBJUNCTIVE", "written", "Quoi que le rapporteur en dise…"], ["même si", "indicative", "all", "Même si le délai est court…"], ["quand bien même", "CONDITIONAL", "formal, written", "Quand bien même le délai serait court…"]]}, "examples": [{"fr": "Certes, le coût est élevé, mais le gain à long terme le justifie.", "en": "Admittedly the cost is high, but the long-term benefit justifies it.", "gloss": {"Certes": "admittedly", "gain": "benefit", "à long terme": "long-term"}, "note": "The concession and its recovery in one sentence. Never add bien que in front of it."}, {"fr": "Bien que le délai soit très court, le service juridique a rendu son avis.", "en": "Although the deadline is very short, the legal service delivered its opinion.", "gloss": {"soit": "is (subjunctive)", "avis": "opinion"}, "note": "bien que + subjunctive, every single time."}, {"fr": "Même si le rapport est adopté demain, la publication prendra deux mois.", "en": "Even if the report is adopted tomorrow, publication will take two months.", "gloss": {"adopté": "adopted", "prendra": "will take"}, "note": "même si looks like bien que and behaves like si: indicative, never subjunctive."}, {"fr": "Quoi que le rapporteur en dise, la base juridique reste contestée.", "en": "Whatever the rapporteur may say about it, the legal basis remains disputed.", "gloss": {"Quoi que": "whatever", "base juridique": "legal basis"}, "note": "Two words: « whatever ». One word, quoique, means « although »."}]}, {"heading": "Cause and consequence when a clause follows", "body": "At B2 you stop saying parce que in writing and start choosing. étant donné que and du fait que state a cause as an established fact; dans la mesure où is proportional — « in so far as », « to the extent that » — and is the connector of a conditional or partial justification, not a plain « because »; d'autant plus que adds a reason that reinforces one already given; dès lors que is the legal-administrative « once, given that ». On the other side, si bien que introduces the result, and de sorte que introduces a purpose when a subjunctive follows and a result when an indicative follows. The error to name is directional: English « so » translates both « c'est pourquoi » and « parce que » depending on the sentence, and English speakers regularly put a cause connector in front of what is in fact the result. Test yourself with the question: is the second clause the reason, or the effect?", "table": {"cols": ["Connector", "Mood", "Means", "Register"], "rows": [["étant donné que", "indicative", "given that", "written"], ["du fait que", "indicative", "owing to the fact that", "written, administrative"], ["dans la mesure où", "indicative", "in so far as, to the extent that", "written"], ["d'autant plus que", "indicative", "all the more so because", "written and spoken"], ["dès lors que", "indicative", "once, given that", "written, legal"], ["si bien que", "indicative", "with the result that", "written"], ["de sorte que", "subjunctive = purpose, indicative = result", "so that", "written"], ["au point que", "indicative", "to the point where", "written"]]}, "examples": [{"fr": "Le règlement d'exécution a pris six mois de retard, si bien que les États membres n'ont pas pu adapter leurs systèmes à temps.", "en": "The implementing regulation was six months late, with the result that the member states could not adapt their systems in time.", "gloss": {"retard": "delay", "adapter": "to adapt", "à temps": "in time"}, "note": "The second clause is the effect, so si bien que. étant donné que here would reverse the logic."}, {"fr": "Étant donné que la version consolidée n'a pas été distribuée, la présidence propose de reporter l'examen du point.", "en": "Given that the consolidated version has not been circulated, the presidency proposes to postpone examination of the item.", "gloss": {"consolidée": "consolidated", "distribuée": "circulated", "examen": "examination"}, "note": "Cause first, decision second — the standard opening of a note."}, {"fr": "Le cofinancement sera versé dans la mesure où les dépenses seront effectivement justifiées.", "en": "The co-financing will be paid in so far as the expenditure is actually substantiated.", "gloss": {"cofinancement": "co-financing", "versé": "paid out", "dépenses": "expenditure"}, "note": "Proportional, not plain cause: the payment follows the justification to that extent."}, {"fr": "Le dossier est urgent, d'autant plus que le texte est attendu depuis deux ans.", "en": "The file is urgent, all the more so because the text has been awaited for two years.", "gloss": {"d'autant plus que": "all the more so because", "attendu": "awaited"}, "note": "It piles a second reason on top of one already accepted."}]}, {"heading": "No clause, just a noun: the nominal style of EU French", "body": "Administrative French prefers a noun where English uses a clause, and the connectors follow. compte tenu de opens half the notes written in this town; du fait de is the noun twin of du fait que; en dépit de is malgré one register higher. Watch three things. First, the pairs: du fait de + noun but du fait que + clause; en raison de + noun but parce que + clause. Second, malgré que is condemned in careful written French — write malgré + noun, or bien que + subjunctive. Third, and most examinable, afin de takes an infinitive and requires the same subject in both halves, while afin que takes a clause with a different subject and a subjunctive. « J'ai avancé la réunion afin que je puisse consulter le service juridique » is wrong for that reason alone; it has to be afin de pouvoir consulter.", "table": {"cols": ["Connector", "What follows", "Means", "Note"], "rows": [["compte tenu de", "noun", "in view of, having regard to", "the standard note opener"], ["du fait de", "noun", "owing to", "clause version: du fait que + indicative"], ["en raison de", "noun", "owing to", "neutral administrative"], ["en dépit de", "noun", "in spite of", "malgré one register higher"], ["malgré", "noun", "despite", "« malgré que » is condemned in writing"], ["faute de", "bare noun, no article", "for want of", "faute de consensus, faute de temps"], ["à défaut de", "noun", "failing that, in the absence of", "introduces a fallback"], ["afin de / en vue de", "INFINITIVE", "in order to", "same subject in both halves"], ["afin que / pour que", "clause + SUBJUNCTIVE", "so that", "different subject in the two halves"]]}, "examples": [{"fr": "Compte tenu de l'ampleur des amendements, la présidence a proposé une version consolidée.", "en": "In view of the scale of the amendments, the presidency proposed a consolidated version.", "gloss": {"Compte tenu de": "in view of", "ampleur": "scale", "amendements": "amendments"}, "note": "A noun follows, so no que. « Compte tenu que » is not standard."}, {"fr": "J'ai avancé la réunion afin de pouvoir consulter le service juridique.", "en": "I brought the meeting forward so as to be able to consult the legal service.", "gloss": {"avancé": "brought forward", "afin de": "in order to"}, "note": "Same subject in both halves — French insists on the infinitive here."}, {"fr": "La présidence a distribué le texte la veille afin que chacun puisse le lire.", "en": "The presidency circulated the text the day before so that everyone could read it.", "gloss": {"la veille": "the day before", "chacun": "everyone", "puisse": "can (subjunctive)"}, "note": "Different subject, so afin que + subjunctive."}, {"fr": "En dépit des efforts consentis, l'objectif n'a pas été atteint.", "en": "In spite of the efforts made, the objective was not reached.", "gloss": {"consentis": "made, expended", "atteint": "reached"}, "note": "« Malgré les efforts consentis » says the same thing one notch lower."}]}, {"heading": "Connectors that come in pairs", "body": "Some connectors open a slot that has to be closed by a specific partner, and the marker notices when the pair is broken. d'une part is closed by d'autre part; d'un côté is closed by de l'autre; crossing them (« d'une part… de l'autre ») looks careless. non seulement is closed by mais aussi, mais également or mais encore, and by nothing else — closing it with de plus or en outre leaves the sentence hanging. soit … soit gives two alternatives, ni … ni negates both, tant … que means « both… and ». One optional refinement: when non seulement opens a whole sentence, formal French may invert the subject and verb — « Non seulement la Commission a-t-elle proposé un report, mais elle a également revu le calendrier ». The inversion is literary and not required; the pair is.", "table": {"cols": ["Opens with", "Closes with", "Register", "Watch out"], "rows": [["d'une part", "d'autre part", "written", "the two-sided paragraph"], ["d'un côté", "de l'autre", "neutral", "never cross the two pairs"], ["non seulement", "mais aussi / mais également / mais encore", "written", "only a « mais » can close it"], ["soit", "soit", "all", "two alternatives"], ["ni", "ni", "all", "« ni le Conseil ni le Parlement »"], ["tant", "que", "written", "« tant la Belgique que l'Irlande »"]]}, "examples": [{"fr": "D'une part, la base juridique est fragile ; d'autre part, le calendrier est intenable.", "en": "On the one hand the legal basis is weak; on the other, the timetable is untenable.", "gloss": {"fragile": "weak", "intenable": "untenable"}, "note": "Two objections announced as a pair. The marker sees the plan immediately."}, {"fr": "Non seulement le délai a été dépassé, mais aucune explication n'a été fournie.", "en": "Not only was the deadline missed, but no explanation was given.", "gloss": {"dépassé": "exceeded, missed", "fournie": "provided"}, "note": "mais closes the pair; mais encore or mais également would do the same."}, {"fr": "Le point sera traité soit en groupe de travail, soit au Coreper.", "en": "The item will be dealt with either in the working party or in Coreper.", "gloss": {"traité": "dealt with", "Coreper": "the committee of permanent representatives"}, "note": "soit … soit: the two halves must be the same kind of phrase."}]}, {"heading": "Thèse, antithèse, synthèse — the shape the marker is reading for", "body": "A French argued paragraph is a movement, not a list. You state the position and support it (thèse). You then either grant the strongest point against you (concession) or bring in the fact that complicates it (or). You resolve (synthèse) — and the resolution is not a restatement of the thesis, it is what survives the objection. Connectors are how each move announces itself, which is why they are worth marks: a marker skimming your third paragraph finds Certes and Or and knows without reading closely that you have argued rather than asserted. Two habits to change if you write like an English speaker. Drop the first-person parade — « Je pense que… Je crois que… » — and use impersonal openers: Il convient de, Il apparaît que, Force est de constater que. And make the concession real: granting a point you immediately call absurd is not a concession, and it reads as weakness rather than control.", "table": {"cols": ["Move", "What you are doing", "Connectors that mark it"], "rows": [["Thèse", "state the position", "Il convient d'abord de rappeler que… ; En premier lieu… ; D'une part…"], ["Appui", "support it with evidence", "En effet… ; Ainsi… ; notamment…"], ["Concession", "grant the other side its best point", "Certes… ; Il est vrai que… ; Bien que + subjonctif…"], ["Antithèse", "turn the argument", "Or… ; Toutefois… ; Néanmoins… ; Il n'en demeure pas moins que…"], ["Synthèse", "resolve what survives", "Dès lors… ; Il apparaît donc que… ; En définitive… ; Sous réserve de…"]]}, "examples": [{"fr": "Il convient d'abord de rappeler que le report du vote laisse aux délégations le temps d'examiner la version consolidée. Certes, ce délai retarde l'entrée en vigueur du règlement.", "en": "It should first be recalled that postponing the vote gives delegations time to examine the consolidated version. Admittedly, this delay puts back the entry into force of the regulation.", "gloss": {"Il convient": "it is appropriate, one should", "report": "postponement", "entrée en vigueur": "entry into force"}, "note": "Thèse, then the concession. Two sentences, two moves, both signposted."}, {"fr": "Or, un texte adopté sans consensus se heurterait aux mêmes objections au stade de la mise en œuvre. Il apparaît dès lors préférable de reporter le vote, sous réserve d'une date ferme fixée dès à présent.", "en": "Now, a text adopted without consensus would run into the same objections at the implementation stage. It therefore appears preferable to postpone the vote, subject to a firm date being set here and now.", "gloss": {"se heurterait": "would run into", "mise en œuvre": "implementation", "sous réserve d'": "subject to"}, "note": "Or turns the argument, then the synthesis resolves it with a condition rather than repeating the thesis."}]}], "recognise": [{"id": "gr-connectors-B2-01", "level": "B2", "format": "cloze", "q": "La note annonce une économie de deux millions d'euros. ___, le tableau annexé fait état d'un surcoût.", "options": ["Donc", "Ainsi", "En effet", "Or"], "a": 3, "trap": "Donc — « or » sits where an English « so » would sit, so English speakers key it as a conclusion word; it is the opposite, the fact that blocks the conclusion", "expl": "or brings in the element that contradicts what was just claimed. Donc and Ainsi would announce a conclusion, En effet a confirmation."}, {"id": "gr-connectors-B2-02", "level": "B2", "format": "cloze", "q": "A note to your director, formal register: « Le calendrier est très serré ; ___, un report n'est pas envisageable. »", "options": ["du coup", "quand même", "néanmoins", "par contre"], "a": 2, "trap": "par contre — close in meaning and one register too low; careful readers still penalise it in a formal note", "expl": "néanmoins (or toutefois) is the formal written form and it takes back the point just conceded. du coup and quand même are spoken."}, {"id": "gr-connectors-B2-03", "level": "B2", "format": "cloze", "q": "Bien que le délai ___ très court, le service juridique a rendu son avis dans les temps.", "options": ["soit", "est", "sera", "était"], "a": 0, "trap": "est — English « although » takes the indicative, so the indicative is what an English speaker writes; bien que never allows it", "expl": "bien que and quoique always take the subjunctive: bien que le délai soit court. Only même si takes the indicative."}, {"id": "gr-connectors-B2-04", "level": "B2", "format": "cloze", "q": "Même si le rapport ___ adopté demain, la publication prendra encore deux mois.", "options": ["soit", "est", "ait été", "fût"], "a": 1, "trap": "soit — même si looks like a twin of bien que and behaves like si: indicative only", "expl": "si and même si never take the subjunctive. Concession with the subjunctive is bien que / quoique."}, {"id": "gr-connectors-B2-05", "level": "B2", "format": "collocation", "q": "Which sentence is correct?", "options": ["Le président a suspendu la séance afin que les délégations puissent se consulter.", "Le président a suspendu la séance afin que les délégations peuvent se consulter.", "Le président a suspendu la séance afin que les délégations pourront se consulter.", "Le président a suspendu la séance afin de les délégations puissent se consulter."], "a": 0, "trap": "« afin que les délégations peuvent » — the indicative looks harmless and is exactly what an English speaker writes after « so that »", "expl": "afin que always takes the subjunctive. afin de takes an infinitive, and only when both halves share the same subject."}, {"id": "gr-connectors-B2-06", "level": "B2", "format": "collocation", "q": "Which version is acceptable in careful written French?", "options": ["Malgré l'opposition de deux délégations, le point a été maintenu.", "Malgré que deux délégations s'y opposent, le point a été maintenu.", "Malgré que deux délégations s'y opposaient, le point a été maintenu.", "Malgré de l'opposition de deux délégations, le point a été maintenu."], "a": 0, "trap": "« Malgré que » — very common in speech and condemned in written French; the subjunctive in it does not rescue it", "expl": "malgré takes a noun directly: malgré l'opposition. For a clause, use bien que or quoique + subjunctive."}, {"id": "gr-connectors-B2-07", "level": "B2", "format": "cloze", "q": "L'avis soulève deux difficultés : ___, la base juridique ; d'autre part, le calendrier.", "options": ["d'un côté", "d'une part", "premièrement", "en premier lieu"], "a": 1, "trap": "d'un côté — a real connector, but it is closed by « de l'autre », not by « d'autre part »", "expl": "The pairs are fixed: d'une part … d'autre part, d'un côté … de l'autre. premièrement and en premier lieu open a numbered list, which « d'autre part » cannot continue."}, {"id": "gr-connectors-B2-08", "level": "B2", "format": "cloze", "q": "Le recours est recevable ___ il a été introduit dans le délai de deux mois.", "options": ["dans la mesure où", "au fur et à mesure que", "à mesure que", "dans le cas où"], "a": 0, "trap": "dans le cas où — the same shape and nearly the same words, but it introduces a hypothesis and takes the conditional", "expl": "dans la mesure où = in so far as, and takes the indicative. au fur et à mesure que and à mesure que mean « as, progressively »."}, {"id": "gr-connectors-B2-09", "level": "B2", "format": "cloze", "q": "___ la complexité du dossier, la présidence a prévu deux séances supplémentaires.", "options": ["Du fait de", "En dépit de", "Au lieu de", "À défaut de"], "a": 0, "trap": "En dépit de — identical shape, opposite logic: it concedes the complexity instead of explaining the decision by it", "expl": "All four take a noun. Du fait de states the cause; en dépit de concedes, au lieu de replaces, à défaut de offers a fallback."}], "drills": [{"id": "gd-connectors-B2-01", "level": "B2", "format": "cloze", "q": "La proposition prévoit une entrée en vigueur en janvier. ___, le règlement d'exécution ne sera pas adopté avant mars.", "options": ["En effet", "Or", "Ainsi", "Donc"], "a": 1, "trap": "En effet — it would present the second sentence as support for the first, when it in fact destroys it", "expl": "or introduces the fact that makes the announced timetable impossible. En effet confirms, Ainsi and Donc conclude."}, {"id": "gd-connectors-B2-02", "level": "B2", "format": "cloze", "q": "Le Conseil n'a pas encore tranché ; ___ le délai de transposition expire vendredi.", "options": ["ou", "or", "donc", "car"], "a": 1, "trap": "ou — one letter away, and the word an English eye expects; « ou » is the real « or » and gives an alternative, not a complication", "expl": "or brings in the fact that makes the delay a problem. donc would draw a conclusion, car would give a reason for the Council's silence."}, {"id": "gd-connectors-B2-03", "level": "B2", "format": "collocation", "q": "You want to concede the cost and then recover the point. Which sentence is correct French?", "options": ["Certes, le coût est élevé, mais le gain à long terme le justifie.", "Bien que le coût soit élevé, mais le gain à long terme le justifie.", "Bien que le coût est élevé, mais le gain à long terme le justifie.", "Malgré que le coût soit élevé, mais le gain à long terme le justifie."], "a": 0, "trap": "« Bien que le coût soit élevé, mais… » — the subjunctive after bien que is right, and the mais still cannot stay: French takes the subordinator or the mais, never both", "expl": "certes … mais is the concession pair. bien que + subjunctive works on its own: « Bien que le coût soit élevé, le gain le justifie. »"}, {"id": "gd-connectors-B2-04", "level": "B2", "format": "cloze", "q": "___ le texte ait été distribué la veille, plusieurs délégations ne l'avaient pas lu.", "options": ["Bien que", "Afin que", "Pour que", "De sorte que"], "a": 0, "trap": "Pour que — the same subjunctive, the opposite job: it states a purpose, not an obstacle", "expl": "All four take the subjunctive, so only the meaning decides. The circulation of the text is an obstacle overcome, not a purpose: bien que."}, {"id": "gd-connectors-B2-05", "level": "B2", "format": "cloze", "q": "Le règlement d'exécution a pris six mois de retard, ___ les États membres n'ont pas pu adapter leurs systèmes à temps.", "options": ["étant donné que", "dans la mesure où", "si bien que", "du fait que"], "a": 2, "trap": "étant donné que — same slot, same indicative clause, wrong direction: it would make the failure to adapt the cause of the delay", "expl": "si bien que introduces the result. étant donné que, dans la mesure où and du fait que all introduce the cause."}, {"id": "gd-connectors-B2-06", "level": "B2", "format": "cloze", "q": "Le cofinancement sera versé ___ les dépenses seront effectivement justifiées.", "options": ["dans la mesure où", "étant donné que", "du fait que", "puisque"], "a": 0, "trap": "étant donné que — it states a cause already established, but nothing here is established yet: the payment is conditional on the justification", "expl": "dans la mesure où is proportional and looks forward — payment to the extent that the expenditure is substantiated. The other three assert the reason as a fact."}, {"id": "gd-connectors-B2-07", "level": "B2", "format": "cloze", "q": "___ l'ampleur des amendements déposés, la présidence a proposé une nouvelle version consolidée.", "options": ["Au terme de", "Au lieu de", "À défaut de", "Compte tenu de"], "a": 3, "trap": "Au terme de — the same shape and register, but it means « at the end of » and turns a reason into a date", "expl": "compte tenu de = in view of, having regard to, and is the standard opener of a note. All four take a noun; only the meaning separates them."}, {"id": "gd-connectors-B2-08", "level": "B2", "format": "cloze", "q": "A recital in a legal act. Which of these is the most formal? « ___ les efforts consentis, l'objectif de 2025 n'a pas été atteint. »", "options": ["En dépit des", "Malgré les", "Nonobstant les", "Compte tenu des"], "a": 2, "trap": "Malgré les — perfectly correct and perfectly ordinary; the question asks for the highest register, and malgré is the neutral one", "expl": "nonobstant is legal-register French and appears in recitals; en dépit de is formal, malgré neutral. compte tenu de would give a reason instead of conceding one."}, {"id": "gd-connectors-B2-09", "level": "B2", "format": "cloze", "q": "Certes, le calendrier est serré ; ___, un report supplémentaire n'est pas envisageable.", "options": ["en revanche", "néanmoins", "par ailleurs", "en effet"], "a": 1, "trap": "en revanche — it sets two different objects side by side; after « certes » you need the word that takes the concession back", "expl": "certes opens a concession and néanmoins (or toutefois) closes it. par ailleurs would add a separate point and en effet would confirm the concession instead of resisting it."}, {"id": "gd-connectors-B2-10", "level": "B2", "format": "cloze", "q": "___ le rapporteur en dise, la base juridique reste contestée.", "options": ["Quoique", "Quoi que", "Bien que", "Encore que"], "a": 1, "trap": "Quoique — the same sound, one word instead of two, and it means « although », which leaves « en dise » without an object", "expl": "quoi que in two words = « whatever ». All four take the subjunctive; only quoi que can be the object of « dire »."}, {"id": "gd-connectors-B2-11", "level": "B2", "format": "cloze", "q": "Non seulement le délai a été dépassé, ___ aucune explication n'a été fournie.", "options": ["de plus", "mais encore", "en outre", "par ailleurs"], "a": 1, "trap": "de plus — a perfectly good addition connector, but « non seulement » has opened a pair and only a « mais » can close it", "expl": "non seulement … mais encore / mais aussi / mais également. Any other addition word leaves the first half unresolved."}, {"id": "gd-connectors-B2-12", "level": "B2", "format": "cloze", "q": "D'une part, la base juridique est fragile ; ___, le calendrier est intenable.", "options": ["de l'autre", "d'autre part", "d'ailleurs", "en outre"], "a": 1, "trap": "de l'autre — the right idea in the wrong pair: « de l'autre » closes « d'un côté »", "expl": "d'une part is closed by d'autre part. en outre and d'ailleurs are additions and do not answer the announcement made by d'une part."}, {"id": "gd-connectors-B2-13", "level": "B2", "format": "cloze", "q": "Le groupe se réunira une nouvelle fois ___ finaliser le compromis.", "options": ["au lieu de", "loin de", "à défaut de", "en vue de"], "a": 3, "trap": "au lieu de — the same preposition + infinitive shape, and it replaces the purpose instead of stating it", "expl": "en vue de + infinitive = with a view to, the nominal-style twin of afin de. The other three deny, distance or replace the action."}, {"id": "gd-connectors-B2-14", "level": "B2", "format": "collocation", "q": "In which sentence is « or » used correctly?", "options": ["Vous pouvez répondre par écrit or par oral.", "Le quorum n'était pas atteint, or la séance a été levée.", "Le texte est très clair, or il a été rédigé par le service juridique.", "Le budget est voté. Or, sa mise en œuvre suppose un acte d'exécution qui n'existe pas encore."], "a": 3, "trap": "« Le quorum n'était pas atteint, or la séance a été levée » — « or » standing where an English speaker would put « so »; that slot belongs to donc", "expl": "or introduces the fact that complicates what was just said. « par écrit or par oral » needs ou; the quorum sentence needs donc; « or il a été rédigé par le service juridique » needs car or en effet."}, {"id": "gd-connectors-B2-15", "level": "B2", "format": "cloze", "q": "Quand bien même le Conseil ___ sa position la semaine prochaine, le calendrier ne pourrait plus être tenu.", "options": ["modifie", "modifierait", "modifiera", "ait modifié"], "a": 1, "trap": "modifie — the indicative you would use after « même si », which is the near twin of quand bien même", "expl": "quand bien même takes the conditional, and the main clause is conditional too. même si would take the present indicative."}, {"id": "gd-connectors-B2-16", "level": "B2", "format": "collocation", "q": "Both halves have the same subject — you. Which sentence is correct?", "options": ["J'ai avancé la réunion afin que je puisse consulter le service juridique.", "J'ai avancé la réunion afin que je peux consulter le service juridique.", "J'ai avancé la réunion afin de je puisse consulter le service juridique.", "J'ai avancé la réunion afin de pouvoir consulter le service juridique."], "a": 3, "trap": "« afin que je puisse consulter » — the subjunctive is correctly formed, and French still refuses afin que when both halves share a subject", "expl": "Same subject: afin de + infinitive. Different subject: afin que + subjunctive, as in « afin que le service juridique puisse répondre »."}, {"id": "gd-connectors-B2-17", "level": "B2", "format": "cloze", "q": "Le retard n'est pas imputable au service juridique ; ___, l'avis a été rendu dans les délais.", "options": ["en effet", "en fait", "or", "toutefois"], "a": 0, "trap": "or — the argumentative hinge; here the second clause supports the first instead of turning against it", "expl": "en effet backs up the statement just made and gives its reason. en fait would correct it, or would contradict it, toutefois would qualify it."}, {"id": "gd-connectors-B2-18", "level": "B2", "format": "collocation", "q": "Your paragraph has stated a position and supported it. Which sentence opens the antithesis?", "options": ["En effet, cette lecture repose sur trois arguments convergents.", "Ainsi, cette lecture emporte la conviction.", "Or, cette lecture se heurte à une objection sérieuse.", "En résumé, cette lecture doit être retenue."], "a": 2, "trap": "« En effet » — it looks like the start of a new movement and in fact continues the same one, adding support", "expl": "Or turns the argument and opens the antithesis. En effet supports, Ainsi draws the consequence, En résumé closes."}], "write": [{"id": "gw-connectors-B2-01", "prompt": "Turn the argument with the right hinge word: « The note announces a saving of two million euros. And yet the annexed table shows an extra cost. » Write the second sentence.", "answer": "Or, le tableau annexé fait état d'un surcoût.", "accept": ["or le tableau annexé fait état d'un surcoût", "or le tableau annexé fait apparaître un surcoût", "or le tableau en annexe fait état d'un surcoût", "or le tableau annexé montre un surcoût", "or le tableau annexé fait état d'un coût supplémentaire"], "hint": "One syllable, not « ou ».", "expl": "or introduces the fact that undermines what was just claimed. It opens the sentence and takes a comma."}, {"id": "gw-connectors-B2-02", "prompt": "Formal note, concede then push back: « The deadline is very tight; nevertheless, a postponement is not an option. »", "answer": "Le délai est très serré ; néanmoins, un report n'est pas envisageable.", "accept": ["le délai est très serré néanmoins un report n'est pas envisageable", "le délai est très serré toutefois un report n'est pas envisageable", "le calendrier est très serré néanmoins un report n'est pas envisageable", "le délai est très serré néanmoins un report n'est pas possible", "le délai est très serré néanmoins aucun report n'est envisageable"], "hint": "Formal register — not « quand même », not « du coup ».", "expl": "néanmoins and toutefois are the written forms and both take back a point just granted."}, {"id": "gw-connectors-B2-03", "prompt": "The concession pair: « Admittedly the cost is high, but the long-term benefit justifies it. »", "answer": "Certes, le coût est élevé, mais le gain à long terme le justifie.", "accept": ["certes le coût est élevé mais le gain à long terme le justifie", "certes le coût est élevé mais le bénéfice à long terme le justifie", "certes le coût est élevé mais le gain à long terme la justifie", "certes le coût est élevé mais les gains à long terme le justifient", "certes le coût est élevé mais le gain sur le long terme le justifie"], "hint": "certes … mais. Never bien que … mais.", "expl": "certes grants the point and mais recovers it. Adding bien que in front would make the sentence ungrammatical."}, {"id": "gw-connectors-B2-04", "prompt": "Same concession with a subordinator: « Although the deadline is very short, the legal service delivered its opinion. »", "answer": "Bien que le délai soit très court, le service juridique a rendu son avis.", "accept": ["bien que le délai soit très court le service juridique a rendu son avis", "bien que le délai soit court le service juridique a rendu son avis", "quoique le délai soit très court le service juridique a rendu son avis", "bien que le délai soit très court le service juridique a rendu son avis dans les temps", "bien que le délai ait été très court le service juridique a rendu son avis"], "hint": "bien que + subjunctive of être, and no « mais » afterwards.", "expl": "bien que and quoique always take the subjunctive: soit, not est. Only même si takes the indicative."}, {"id": "gw-connectors-B2-05", "prompt": "Same subject in both halves: « I brought the meeting forward so as to be able to consult the legal service. »", "answer": "J'ai avancé la réunion afin de pouvoir consulter le service juridique.", "accept": ["j'ai avancé la réunion afin de pouvoir consulter le service juridique", "j'ai avancé la réunion afin de consulter le service juridique", "j'ai avancé la réunion pour pouvoir consulter le service juridique", "j'ai avancé la réunion en vue de consulter le service juridique", "j'ai avancé la réunion afin de pouvoir consulter le juriste"], "hint": "Same subject means an infinitive.", "expl": "afin de + infinitive when both halves share a subject. « afin que je puisse » is wrong here for that reason alone."}, {"id": "gw-connectors-B2-06", "prompt": "Different subjects: « The presidency circulated the text the day before so that everyone could read it. »", "answer": "La présidence a distribué le texte la veille afin que chacun puisse le lire.", "accept": ["la présidence a distribué le texte la veille afin que chacun puisse le lire", "la présidence a distribué le texte la veille pour que chacun puisse le lire", "la présidence a diffusé le texte la veille afin que chacun puisse le lire", "la présidence a distribué le texte la veille afin que tous puissent le lire", "la présidence a transmis le texte la veille afin que chacun puisse le lire"], "hint": "Different subject means afin que + subjunctive.", "expl": "afin que and pour que take the subjunctive: puisse, not peut."}, {"id": "gw-connectors-B2-07", "prompt": "Proportional condition: « The co-financing will be paid in so far as the expenditure is actually substantiated. »", "answer": "Le cofinancement sera versé dans la mesure où les dépenses seront effectivement justifiées.", "accept": ["le cofinancement sera versé dans la mesure où les dépenses seront effectivement justifiées", "le cofinancement sera versé dans la mesure où les dépenses sont effectivement justifiées", "le cofinancement sera payé dans la mesure où les dépenses seront effectivement justifiées", "le cofinancement sera versé dans la mesure où les dépenses seront dûment justifiées", "le cofinancement sera versé dans la mesure où les dépenses seront réellement justifiées"], "hint": "Not « parce que » — the payment is proportional to the justification.", "expl": "dans la mesure où + indicative. It is a conditional, proportional justification, not a statement of established cause."}, {"id": "gw-connectors-B2-08", "prompt": "Open a note with an established cause: « Given that the consolidated version has not been circulated, the presidency proposes to postpone the item. »", "answer": "Étant donné que la version consolidée n'a pas été distribuée, la présidence propose de reporter le point.", "accept": ["étant donné que la version consolidée n'a pas été distribuée la présidence propose de reporter le point", "étant donné que la version consolidée n'a pas été diffusée la présidence propose de reporter le point", "étant donné que la version consolidée n'a pas été distribuée la présidence propose de reporter l'examen du point", "du fait que la version consolidée n'a pas été distribuée la présidence propose de reporter le point", "étant donné que la version consolidée n'a pas été transmise la présidence propose de reporter le point"], "hint": "Cause first, decision second; + indicative.", "expl": "étant donné que states an established fact as the reason. « Étant donné » without que would need a noun instead of a clause."}, {"id": "gw-connectors-B2-09", "prompt": "Nominal style, no clause: « In view of the scale of the amendments, the presidency proposed a consolidated version. »", "answer": "Compte tenu de l'ampleur des amendements, la présidence a proposé une version consolidée.", "accept": ["compte tenu de l'ampleur des amendements la présidence a proposé une version consolidée", "compte tenu du nombre d'amendements la présidence a proposé une version consolidée", "en raison de l'ampleur des amendements la présidence a proposé une version consolidée", "du fait de l'ampleur des amendements la présidence a proposé une version consolidée", "compte tenu de l'ampleur des amendements déposés la présidence a proposé une version consolidée"], "hint": "A noun follows, so no « que ».", "expl": "compte tenu de + noun opens half the notes written in Brussels. « Compte tenu que » is not standard French."}, {"id": "gw-connectors-B2-10", "prompt": "The result, not the cause: « The implementing regulation was six months late, with the result that the member states could not adapt their systems in time. »", "answer": "Le règlement d'exécution a pris six mois de retard, si bien que les États membres n'ont pas pu adapter leurs systèmes à temps.", "accept": ["le règlement d'exécution a pris six mois de retard si bien que les états membres n'ont pas pu adapter leurs systèmes à temps", "le règlement d'exécution a pris six mois de retard si bien que les états membres n'ont pas pu adapter leurs systèmes", "le règlement d'exécution a eu six mois de retard si bien que les états membres n'ont pas pu adapter leurs systèmes à temps", "le règlement d'exécution a pris six mois de retard de sorte que les états membres n'ont pas pu adapter leurs systèmes à temps", "le règlement d'exécution a pris six mois de retard si bien que les états membres n'ont pas eu le temps d'adapter leurs systèmes"], "hint": "si bien que + indicative.", "expl": "si bien que introduces the effect. étant donné que would put the cause there and reverse the logic."}, {"id": "gw-connectors-B2-11", "prompt": "Close the pair correctly: « Not only was the deadline missed, but no explanation was given. »", "answer": "Non seulement le délai a été dépassé, mais aucune explication n'a été fournie.", "accept": ["non seulement le délai a été dépassé mais aucune explication n'a été fournie", "non seulement le délai a été dépassé mais aucune explication n'a été donnée", "non seulement le délai a été dépassé mais encore aucune explication n'a été fournie", "non seulement le délai n'a pas été respecté mais aucune explication n'a été fournie", "non seulement le délai a été dépassé mais également aucune explication n'a été fournie"], "hint": "Only a « mais » can close « non seulement ».", "expl": "non seulement … mais aussi / mais également / mais encore. de plus or en outre would leave the first half hanging."}, {"id": "gw-connectors-B2-12", "prompt": "Announce two objections as a pair: « On the one hand the legal basis is weak; on the other, the timetable is untenable. »", "answer": "D'une part, la base juridique est fragile ; d'autre part, le calendrier est intenable.", "accept": ["d'une part la base juridique est fragile d'autre part le calendrier est intenable", "d'une part la base juridique est fragile d'autre part le calendrier n'est pas tenable", "d'une part la base juridique est fragile d'autre part le calendrier est irréaliste", "d'un côté la base juridique est fragile de l'autre le calendrier est intenable", "d'une part la base juridique est faible d'autre part le calendrier est intenable"], "hint": "Keep the two halves of the pair together.", "expl": "d'une part … d'autre part, or d'un côté … de l'autre. Crossing the pairs is the mistake to avoid."}], "apply": [{"id": "ga-connectors-B2-01", "situation": "Note to your head of unit. You are recommending that the working party vote be postponed, and you know she will object that a delay pushes back the entry into force.", "task": "Write TWO sentences: first your recommendation, then a concession that grants the objection and takes it back (certes… mais, or a concession plus néanmoins).", "accept": ["je recommande de reporter le vote certes ce report retarde l'entrée en vigueur du règlement mais un texte adopté sans consensus se heurterait aux mêmes objections au stade de la mise en œuvre", "je recommande de reporter le vote certes ce report retarde l'entrée en vigueur du règlement mais un texte adopté sans consensus poserait les mêmes problèmes plus tard", "je recommande de reporter le vote certes ce délai retarde l'entrée en vigueur du règlement mais un texte adopté sans consensus se heurterait aux mêmes objections", "je propose de reporter le vote certes ce report retarde l'entrée en vigueur néanmoins un texte adopté sans consensus serait contesté à la mise en œuvre", "je recommande de reporter le vote il est vrai que ce report retarde l'entrée en vigueur néanmoins un texte sans consensus serait contesté plus tard", "je recommande le report du vote certes l'entrée en vigueur sera retardée mais un texte adopté sans consensus poserait les mêmes difficultés au stade de la mise en œuvre"], "model": "Je recommande de reporter le vote. Certes, ce report retarde l'entrée en vigueur du règlement, mais un texte adopté sans consensus se heurterait aux mêmes objections au stade de la mise en œuvre.", "expl": "Claim, then concession, then recovery: certes … mais, or a concession closed by néanmoins. Granting the objection first is what makes the recommendation look considered rather than defensive."}, {"id": "ga-connectors-B2-02", "situation": "You are writing the third paragraph of an EUFTE essay. You have argued that the proposed timetable is realistic. You now have to turn the argument: the implementing act will not be adopted before March.", "task": "Write TWO sentences: bring in the fact that complicates your position, then draw the conclusion that survives it.", "accept": ["or le règlement d'exécution ne sera pas adopté avant mars il apparaît dès lors nécessaire de revoir le calendrier", "or le règlement d'exécution ne sera pas adopté avant mars le calendrier doit dès lors être revu", "or l'acte d'exécution ne sera pas adopté avant mars il apparaît donc nécessaire de revoir le calendrier", "or le règlement d'exécution ne sera pas adopté avant mars il convient dès lors de revoir le calendrier", "or le règlement d'exécution ne sera pas adopté avant mars en définitive le calendrier doit être revu"], "model": "Or, le règlement d'exécution ne sera pas adopté avant mars. Il apparaît dès lors nécessaire de revoir le calendrier.", "expl": "Or opens the antithesis; dès lors, il apparaît donc que or en définitive opens the synthesis. Those two connectors alone show the marker that the paragraph argues rather than asserts."}, {"id": "ga-connectors-B2-03", "situation": "You are summarising a Council working party meeting for your head of unit. Two objections were raised to the text: the legal basis is weak, and the timetable cannot be met.", "task": "Report both objections in one sentence, announced as a pair.", "accept": ["deux objections ont été soulevées d'une part la base juridique est fragile d'autre part le calendrier est intenable", "deux objections ont été soulevées d'une part la fragilité de la base juridique d'autre part le caractère intenable du calendrier", "les délégations ont soulevé deux objections d'une part la base juridique est fragile d'autre part le calendrier est intenable", "d'une part la base juridique est fragile d'autre part le calendrier est intenable", "deux objections ont été formulées d'une part la base juridique est fragile d'autre part le calendrier ne peut être tenu"], "model": "Deux objections ont été soulevées : d'une part, la base juridique est fragile ; d'autre part, le calendrier est intenable.", "expl": "Announcing the number and then splitting it with d'une part … d'autre part is the fastest way to make a summary readable at a glance."}, {"id": "ga-connectors-B2-04", "situation": "You are drafting the opening line of a note explaining why the presidency is proposing to postpone examination of an agenda item. The consolidated version was never circulated.", "task": "Write one sentence putting the established cause first, in formal written register, and the proposal second.", "accept": ["étant donné que la version consolidée n'a pas été distribuée la présidence propose de reporter l'examen de ce point", "étant donné que la version consolidée n'a pas été distribuée la présidence propose de reporter l'examen du point", "étant donné que la version consolidée n'a pas été diffusée la présidence propose de reporter l'examen du point", "compte tenu de la non-distribution de la version consolidée la présidence propose de reporter l'examen du point", "du fait que la version consolidée n'a pas été distribuée la présidence propose de reporter l'examen du point", "étant donné que la version consolidée n'a pas été transmise aux délégations la présidence propose de reporter l'examen du point", "en raison de l'absence de version consolidée la présidence propose de reporter l'examen du point"], "model": "Étant donné que la version consolidée n'a pas été distribuée, la présidence propose de reporter l'examen de ce point.", "expl": "étant donné que + clause, or compte tenu de / en raison de + noun. Choosing between them is a choice between a clause and a nominal group, not a change of meaning."}, {"id": "ga-connectors-B2-05", "situation": "You are writing to the secretariat of the working party. You want the consolidated text circulated the day before, so that the delegations can read it in advance.", "task": "Write one sentence asking for this, with the purpose expressed in a clause (the two halves have different subjects).", "accept": ["pourriez-vous distribuer la version consolidée la veille afin que les délégations puissent la lire à l'avance", "pourriez-vous diffuser la version consolidée la veille afin que les délégations puissent la lire à l'avance", "je vous serais reconnaissant de distribuer la version consolidée la veille afin que les délégations puissent la lire", "pourriez-vous transmettre la version consolidée la veille afin que les délégations puissent en prendre connaissance", "pourriez-vous distribuer la version consolidée la veille pour que les délégations puissent la lire à l'avance", "merci de distribuer la version consolidée la veille afin que les délégations puissent la lire à l'avance"], "model": "Pourriez-vous distribuer la version consolidée la veille, afin que les délégations puissent la lire à l'avance ?", "expl": "Different subjects, so afin que (or pour que) + subjunctive: puissent. With the same subject it would have to be afin de + infinitive."}, {"id": "ga-connectors-B2-06", "situation": "A colleague objects that your proposal costs too much. You accept the figure but not the conclusion.", "task": "Write TWO sentences: first grant the cost using a subordinator with the subjunctive, then state what makes it worth paying.", "accept": ["bien que le coût soit élevé la proposition reste la plus efficace à long terme le gain attendu dépasse largement la dépense initiale", "bien que le coût soit élevé la proposition reste défendable le gain à long terme dépasse la dépense initiale", "quoique le coût soit élevé la proposition reste la plus efficace le gain à long terme justifie la dépense", "bien que le coût soit élevé cette option reste la plus efficace le gain attendu justifie la dépense initiale", "bien que le coût soit élevé la proposition demeure la plus efficace néanmoins il convient de préciser le gain attendu"], "model": "Bien que le coût soit élevé, la proposition reste la plus efficace à long terme. Le gain attendu dépasse largement la dépense initiale.", "expl": "bien que + subjunctive concedes without a mais; the second sentence carries the recovery. Writing « Bien que le coût est élevé, mais… » would make two errors in one line."}]}
};
